 /* Is the RCU grace-period kthread being starved of CPU time? */
 static bool rcu_is_gp_kthread_starving(unsigned long *jp)
 {
 	unsigned long j = jiffies - READ_ONCE(rcu_state.gp_activity);

 	if (jp)
 		*jp = j;
 	return j > 2 * HZ;
 }

