 static void
 voice_kmode_process_send(struct voice_chan *chan, struct msghdr *msg)
 {
 	struct kvec vec;
 	unsigned char *enc_buf;
 	int to_send = 0, sent = 0;
 	struct rtp_packet_header *packet_header = NULL;

 	/* kernel mode is on */
 	while ((to_send = cfifo_get(chan->enc_fifo, (void **)&enc_buf)) > 0) {
 		/* send data */
 		packet_header = (struct rtp_packet_header *)enc_buf;
 		to_send = to_send - sizeof(struct rtp_packet_header);
 		vec.iov_base = enc_buf + sizeof(struct rtp_packet_header);
 		vec.iov_len = to_send;
 		/* send to appropriate destination according to RTP/RTCP flag */
 		msg->msg_namelen = sizeof(chan->remote_addr);

 		/* If RTCP-MUX flag is enabled, Send RTCP Packet on the same RTP port*/
                 if (chan->config.rtcp_mux){
                         msg->msg_name = &chan->remote_addr;
                         sent = kernel_sendmsg(chan->sock, msg, &vec, 1, to_send);
                 } else {
 			if (packet_header->packetType == CFIFO_RTP_PACKET) {
 				msg->msg_name = &chan->remote_addr;
 				sent = kernel_sendmsg(chan->sock, msg, &vec, 1, to_send);
 			} else if (packet_header->packetType == CFIFO_RTCP_PACKET) {
 				msg->msg_name = &chan->remote_addr_rtcp;
 				sent = kernel_sendmsg(chan->sock_rtcp, msg, &vec, 1, to_send);
 			}
 		}
 		if (sent < 0)
 			pr_err("%s: sock_sendmsg() failed with error %d "
 			       "(channel %d)\n", SERVICE_NAME, chan->id, sent);
 		else if (sent != to_send)
 			pr_err("%s: failed to send %d bytes (channel %d)\n",
 			        SERVICE_NAME, chan->id, to_send - sent);

 		cfifo_processed(chan->enc_fifo);
 	}
 }

 static int
 voice_kmode_process_recv(struct voice_chan *chan, struct msghdr *msg)
 {
 	struct kvec vec;
 	unsigned char *dec_buf;
 	int recvd = 0;
 	struct timeval timestamp;
 	unsigned long timediff;
 	struct rtp_packet_header *packet_header = NULL;
 	unsigned char ctrl_buf[100];
 	struct cmsghdr *cmsg;
 	int ttl = 0;
 	RTP_HDR *pRtpHdr = NULL;	

 	if (chan->config.codec.opts & RTP_ENABLE_SYMMETRIC_RSP) {
 		msg->msg_name = &chan->remote_addr;
 		msg->msg_namelen = sizeof(chan->remote_addr);
 	}
 	msg->msg_control = ctrl_buf;
 	msg->msg_controllen = sizeof(ctrl_buf);
 	memset(&ctrl_buf, 0, sizeof(ctrl_buf));

 	while (1) {
 		vec.iov_base = kthread_buf;
 		vec.iov_len  = sizeof(kthread_buf);
 		recvd = kernel_recvmsg(chan->sock, msg, &vec, 1,
 				       sizeof(kthread_buf), MSG_DONTWAIT);
 		if (recvd <= 0)
 			break;

 		do_gettimeofday(&timestamp);
 		timediff = timeval_to_rtp(&timestamp) -
 			   timeval_to_rtp(&chan->last_timestamp);
 		chan->last_timestamp.tv_sec = timestamp.tv_sec;
 		chan->last_timestamp.tv_usec = timestamp.tv_usec;

 		dec_buf = cfifo_request(chan->dec_fifo, recvd +
 					sizeof(struct rtp_packet_header));
 		if (IS_ERR(dec_buf))
 			return NF_DROP; /* drop the packet */

 		cmsg = (struct cmsghdr *)ctrl_buf;
 		msg->msg_control = ctrl_buf;
 		msg->msg_controllen = sizeof(ctrl_buf);
 		for (cmsg = CMSG_FIRSTHDR(msg); cmsg; cmsg = CMSG_NXTHDR(msg, cmsg)) {
 			if (!CMSG_OK(msg, cmsg))
 				break;

 			if (cmsg->cmsg_level != SOL_IP)
 				continue;

 			if (cmsg->cmsg_type != IP_TTL)
 				continue;

 			ttl = *(int *)CMSG_DATA(cmsg);
 		}

 		packet_header = (struct rtp_packet_header *)dec_buf;
 		packet_header->ttl = ttl;

 		if (chan->config.rtcp_mux) {
 			pRtpHdr = (RTP_HDR *)kthread_buf;
 			if (pRtpHdr->bMarkerPayload == RTCP_TYPE_SR 
 				|| pRtpHdr->bMarkerPayload == RTCP_TYPE_RR
 					|| pRtpHdr->bMarkerPayload == RTCP_TYPE_XR)
 				packet_header->packetType = CFIFO_RTCP_PACKET;
 		} else {
 			packet_header->packetType = CFIFO_RTP_PACKET;
 		}

 		chan->last_rtptime += timediff;
 		packet_header->receiptTime = chan->last_rtptime;
 		memcpy(dec_buf + sizeof(struct rtp_packet_header),
 		       kthread_buf, recvd);
 		cfifo_commit(chan->dec_fifo);
 	}

 	/* Try to Recv RTCP packets if any */
 	if (!chan->sock_rtcp)
 		return 0;

 	if (chan->config.codec.opts & RTP_ENABLE_SYMMETRIC_RSP) {
 		msg->msg_name = &chan->remote_addr_rtcp;
 		msg->msg_namelen = sizeof(chan->remote_addr_rtcp);
 	}

 	while (1) {
 		vec.iov_base = kthread_buf;
 		vec.iov_len  = sizeof(kthread_buf);
 		recvd = kernel_recvmsg(chan->sock_rtcp, msg, &vec, 1,
 				       sizeof(kthread_buf), MSG_DONTWAIT);
 		if (recvd <= 0)
 			break;

 		/* Add extra space to distinguish RTP and RTCP */
 		dec_buf = cfifo_request(chan->dec_fifo, recvd +
 					sizeof(struct rtp_packet_header));
 		if (IS_ERR(dec_buf))
 			return NF_DROP; /* drop the packet */

 		cmsg = (struct cmsghdr *)ctrl_buf;
 		msg->msg_control = ctrl_buf;
 		msg->msg_controllen = sizeof(ctrl_buf);
 		for (cmsg = CMSG_FIRSTHDR(msg); cmsg; cmsg = CMSG_NXTHDR(msg, cmsg)) {
 			if (!CMSG_OK(msg, cmsg))
 				break;

 			if (cmsg->cmsg_level != SOL_IP)
 				continue;

 			if (cmsg->cmsg_type != IP_TTL)
 				continue;

 			ttl = *(int *)CMSG_DATA(cmsg);
 		}

 		packet_header = (struct rtp_packet_header *)dec_buf;
 		packet_header->packetType = CFIFO_RTCP_PACKET;
 		packet_header->ttl = ttl;
 		packet_header->receiptTime = 0;
 		memcpy(dec_buf + sizeof(struct rtp_packet_header),
 		       kthread_buf, recvd);
 		cfifo_commit(chan->dec_fifo);
 	}

 	return 0;
 }

 static void
 voice_kmode_process_recv_loop(struct voice_chan *chan, struct msghdr *msg)
 {
 	struct kvec vec;
 	int recvd = 0;
 	int sent = 0;

 	if (chan->config.codec.opts & RTP_ENABLE_SYMMETRIC_RSP) {
 		msg->msg_name = &chan->remote_addr;
 		msg->msg_namelen = sizeof(chan->remote_addr);
 	}

 	while (1) {
 		vec.iov_base = kthread_buf;
 		vec.iov_len  = sizeof(kthread_buf);
 		recvd = kernel_recvmsg(chan->sock, msg, &vec, 1,
 		                       sizeof(kthread_buf), MSG_DONTWAIT);
 		if (recvd <= 0)
 			break;

 		if (recvd > 0) {
 			vec.iov_base = kthread_buf;
 			vec.iov_len  = sizeof(kthread_buf);

 			msg->msg_namelen = sizeof(chan->remote_addr);
 			msg->msg_name = &chan->remote_addr;

 			sent = kernel_sendmsg(chan->sock, msg, &vec, 1, recvd);

 			if (sent < 0)
 				pr_err("%s: sock_sendmsg() failed with error %d "
 				       "(channel %d)\n", SERVICE_NAME, chan->id, sent);
 			else if (sent != recvd)
 				pr_err("%s: failed to send %d bytes (channel %d)\n",
 				       SERVICE_NAME, chan->id, recvd - sent);
 		}
 	}
 }

 static int
 voice_kmode_thread(void *data)
 {
 	struct voice_chan *chan;
 	struct task_struct *tsk = current;
 	struct sched_param param = {.sched_priority = 1 };
 	int i;

 	sched_setscheduler(tsk, SCHED_FIFO, &param);

 	while (!kthread_should_stop()) {
 		for (i = 0; i < voice_numlines ; i++) {
 			chan = &voice_channels[i];
 			if (chan->status != CHANNEL_STARTED)
 				continue;

 			if ((chan->config.media_loop_level == RTP_LOOP_IP_LEVEL)) {
 				voice_kmode_process_recv_loop(chan, &chan->rxmsg);
 				continue;
 			}

 			if (chan->sock) {
 				voice_kmode_process_send(chan, &chan->txmsg);
 				if (voice_kmode_process_recv(chan, &chan->rxmsg) < 0)
 					pr_warning("%s: FIFO full - dropping incoming RTP packet\n", SERVICE_NAME);
 			} else {
 				if (!cfifo_empty(chan->enc_fifo))
 					wake_up(&chan->enc_wq);
 			}
 		}
 		usleep_range(2000, 3000);
 	}

 	return 0;
 }
