 			voice_kmode_stop_rtcp(chan);
 		}

 		return 0;
 	}

 	case VOICE_IOCUPDATE_CHAN:
 	{
 		if (copy_from_user(&chan->config, argp, sizeof(chan->config)))
 			return -EFAULT;

 		ret = voice_kmode_update_chan(chan, &chan->config);
 		if (ret < 0)
