@@ -1205,176 +1205,176 @@
 voice_open(struct inode *inode, struct file *file)
 {
 	int ret = 0;
 	unsigned int flags = file->f_flags & O_ACCMODE;
 	unsigned int minor = iminor(inode);
 	struct voice_chan *chan = &voice_channels[minor];

 	if (!voice_registered())
 		return -1;

 	/* only allow one reader */
 	if (flags == O_RDONLY || flags == O_RDWR) {
 		if (chan->reader) {
 			return -EBUSY;
 		} else {
 			chan->reader = file;
 			file->private_data = chan;
 		}
 	}

 	/* only allow one writer */
 	if (flags == O_WRONLY || flags == O_RDWR) {
 		if (chan->writer) {
 			return -EBUSY;
 		} else {
 			chan->writer = file;
 			file->private_data = chan;
 		}
 	}

 	if (chan->status == CHANNEL_INVALID) {
 		chan->id = minor;
 		ret = voice_chan_init(chan);
 	}

 	return ret;
 }

 static int
 voice_release(struct inode *inode, struct file *file)
 {
 	int ret = 0;
 	unsigned int minor = iminor(inode);
 	struct voice_chan *chan = &voice_channels[minor];

 	if (!voice_registered())
 		return -1;

 	if (chan->reader == file)
 		chan->reader = NULL;

 	if (chan->writer == file)
 		chan->writer = NULL;

 	if (!chan->reader && !chan->writer) {
 		voice_stop_chan(chan);
 		if (chan->sock)
 			voice_kmode_stop(chan);
 		voice_free_chan(chan);
 		voice_chan_reset(chan);
 	}

 	return ret;
 }

 static ssize_t
 voice_read(struct file *file, char __user *buf, size_t count_want,
            loff_t *f_pos)
 {
 	struct voice_chan *chan = (struct voice_chan *)file->private_data;
 	unsigned char *enc_buf;
 	size_t not_copied;
 	ssize_t to_copy;
 	ssize_t ret;

 	if (!voice_registered())
 		return -1;

 	if (chan->sock)
 		return -EBUSY;

 	if (wait_event_interruptible(chan->enc_wq,
 			     (cfifo_empty(chan->enc_fifo) == 0))){
 		pr_err("%s: voice_read returning ERESTARTSYS\n", SERVICE_NAME);
 		return -ERESTARTSYS;
 	}

 	ret = cfifo_get(chan->enc_fifo, (void **)&enc_buf);

 	/* copy one rtp packet at a time */
 	to_copy = ret;
 	/* Need to check if we are returning more than what has been asked ??? */
 	if(count_want < to_copy){
 		pr_err("%s: coma-voice: Got more data of '%d' than requested, copying only requested '%d' \n" , SERVICE_NAME , to_copy , count_want);
 		to_copy = count_want;
 	}
 	not_copied = copy_to_user(buf, enc_buf, to_copy);
 	cfifo_processed(chan->enc_fifo);

 	return (to_copy - not_copied);
 }

 static ssize_t
 voice_write(struct file *file, const char __user *buf, size_t count,
             loff_t *f_pos)
 {
 	int ret = 0;
 	struct voice_chan *chan = (struct voice_chan *)file->private_data;
 	char *fifo_buf;

 	if (!voice_registered())
 		return -1;

 	if (chan->sock)
 		return -EBUSY;
 	fifo_buf = cfifo_request(chan->dec_fifo, count);
 	if (IS_ERR(fifo_buf))
 		return -ENOMEM;

 	ret = copy_from_user(fifo_buf, buf, count);
 	if (ret != 0)
 		return -1;

 	cfifo_commit(chan->dec_fifo);

 	return count;
 }

 static unsigned int
 voice_poll(struct file *file, poll_table * event_list)
 {
 	struct voice_chan *chan = (struct voice_chan *)file->private_data;
 	unsigned int mask = POLLOUT | POLLWRNORM; /* we always allow writing */

 	if (!cfifo_empty(chan->enc_fifo))
 		mask |= POLLIN | POLLRDNORM;

 	poll_wait(file, &chan->enc_wq, event_list);

 	return mask;
 }

 static struct file_operations voice_fops = {
 	.owner   = THIS_MODULE,
