 /* Called from __schedule() with the rq lock held and IRQs disabled. */
 void notrace starve_dbg_switch(u64 now, bool preempt, struct task_struct *prev,
 			       struct task_struct *next)
 {
 	struct sd_switch *s = &sd_sw[sd_sw_head++ & (SD_NR_SWITCH - 1)];

 	s->ts = now;
 	s->prev_pid = prev->pid;
 	s->next_pid = next->pid;
 	s->prev_prio = prev->prio;
 	s->next_prio = next->prio;
 	s->prev_state = preempt ? 'R' : task_state_to_char(prev);
 	s->preempt = preempt;
 	memcpy(s->prev_comm, prev->comm, TASK_COMM_LEN);
 	memcpy(s->next_comm, next->comm, TASK_COMM_LEN);
 	s->prev_comm[TASK_COMM_LEN - 1] = '\0';
 	s->next_comm[TASK_COMM_LEN - 1] = '\0';

 	if (prev == sd_gpk)
 		sd_gpk_out = *s;
 	else if (next == sd_gpk)
 		sd_gpk_in_ts = now;
 }

 /* Called from __handle_irq_event_percpu() after each action handler. */
 void notrace starve_dbg_irq(unsigned int irq, void *handler, u64 t0)
 {
 	struct sd_longirq *l;
 	u64 dur;

 	/* this handler printed a report: its duration is ours, not the driver's */
 	if (unlikely(sd_skip_irq)) {
 		sd_skip_irq = false;
 		return;
 	}
 	dur = local_clock() - t0;
 	if (likely(dur < SD_LONGIRQ_NS))
 		return;

 	l = &sd_longirq[sd_longirq_head++ & (SD_NR_LONGIRQ - 1)];
 	l->ts = t0;
 	l->dur = dur;
 	l->handler = handler;
 	l->irq = irq;
 	if (dur > sd_irq_max.dur)
 		sd_irq_max = *l;
 }

 void starve_dbg_note(const char *tag, long a, long b)
 {
