 	if (sd_irq_max.dur) {
 		sd_ts(sd_irq_max.ts, &sec, &usec);
 		pr_info(SD " longest hardirq since boot: [%5lu.%06lu] irq %u %ps %llu us\n",
 			sec, usec, sd_irq_max.irq, sd_irq_max.handler,
 			div_u64(sd_irq_max.dur, NSEC_PER_USEC));
 	}
 	for (i = SD_NR_LONGIRQ; i > 0; i--) {
 		const struct sd_longirq *l =
 			&sd_longirq[(sd_longirq_head - i) & (SD_NR_LONGIRQ - 1)];

 		if (!l->ts)
 			continue;
 		sd_ts(l->ts, &sec, &usec);
 		pr_info(SD "  long hardirq [%5lu.%06lu] irq %u %ps %llu us\n",
 			sec, usec, l->irq, l->handler,
 			div_u64(l->dur, NSEC_PER_USEC));
 	}
 }

 static void sd_print_tasks(struct rq *rq, u64 now, u64 window_ns, bool full)
 {
 	struct task_struct *g, *p, *cur = current;
 	int max_ran = full ? 24 : 12;
 	int nrun = 0, nran = 0, nstack = 0, hidden = 0;

 	rcu_read_lock();
 	for_each_process_thread(g, p) {
 		if (!task_on_rq_queued(p) && p != cur)
 			continue;
 		if (nrun++ >= 16) {
 			hidden++;
 			continue;
 		}
 		sd_print_task("run", p, rq, now);
 		/* other runnable RT tasks: show where they are */
 		if (p != cur && rt_task(p) && nstack < 3) {
 			nstack++;
 			sched_show_task(p);
 		}
 	}
 	for_each_process_thread(g, p) {
 		if (task_on_rq_queued(p) || p == cur)
 			continue;
 		if (!p->se.exec_start || now - p->se.exec_start > window_ns)
 			continue;
 		if (nran++ >= max_ran) {
 			hidden++;
 			continue;
 		}
 		sd_print_task("ran", p, rq, now);
 	}
 	rcu_read_unlock();
 	if (hidden)
 		pr_info(SD " (%d more runnable/recently-run tasks not shown)\n",
 			hidden);
 }

 static void sd_print_rt_tasks(void)
 {
 	struct task_struct *g, *p;
 	int len = 0, n = 0;

 	rcu_read_lock();
 	for_each_process_thread(g, p) {
 		if (!rt_policy(p->policy) && !dl_policy(p->policy))
 			continue;
 		len += scnprintf(sd_line + len, sizeof(sd_line) - len,
 				 " %d/%s/%c%u", p->pid, p->comm,
 				 p->policy == SCHED_FIFO ? 'F' :
 				 p->policy == SCHED_RR ? 'R' : 'D',
 				 p->rt_priority);
 		if (len > 150) {
 			pr_info(SD " rt:%s\n", sd_line);
 			len = 0;
 		}
 		if (++n >= 128)
 			goto out;
 	}
 out:
 	rcu_read_unlock();
 	if (len)
 		pr_info(SD " rt:%s\n", sd_line);
 	pr_info(SD " rt/dl tasks: %d%s\n", n, n >= 128 ? "+" : "");
 }

 static void sd_print_notes(void)
 {
 	unsigned long sec, usec;
 	unsigned int i;

 	for (i = SD_NR_NOTES; i > 0; i--) {
 		const struct sd_note *n =
 			&sd_notes[(sd_notes_head - i) & (SD_NR_NOTES - 1)];

 		if (!n->ts)
 			continue;
 		sd_ts(n->ts, &sec, &usec);
 		pr_info(SD " note [%5lu.%06lu] %d/%s %s %#lx %ld\n", sec, usec,
 			n->pid, n->comm, n->tag, (unsigned long)n->a, n->b);
 	}
 }

 /* Must be called from the tick (hard IRQ, interrupts disabled). */
 static void sd_report(struct task_struct *gpk, const char *why, bool full)
 {
 	struct rq *rq = this_rq();
 	struct pt_regs *regs = get_irq_regs();
 	struct task_struct *cur = current;
 	unsigned long j = jiffies;
 	unsigned long starve = sd_active ? j - sd_gpa : 0;
 	u64 now = rq->clock_task;
 	u64 window_ns = (u64)jiffies_to_msecs(starve) * NSEC_PER_MSEC;
 	u64 rt_runtime = rq->rt.rt_runtime;

 	pr_err(SD "==== %s: GP kthread not run for %u ms (since uptime %u ms); cur %d(%d) %s pol=%u prio=%d pcnt=%#x %s ====\n",
 	       why, jiffies_to_msecs(starve), sd_j2ms(sd_gpa), cur->pid,
 	       cur->tgid, cur->comm, cur->policy, cur->prio, sd_irq_pcnt(),
 	       !regs ? "no-regs" : user_mode(regs) ? "user" : "kernel");
 	pr_info(SD " episode #%u samples=%u detect_gap=%lu max_tick_gap=%lu ctxsw+%llu clock+%llums jiffies+%ums\n",
 		sd_episodes, sd_nsamples, sd_detect_gap, sd_max_gap,
 		rq->nr_switches - sd_start_switches,
 		div_u64(local_clock() - sd_start_ns, NSEC_PER_MSEC),
 		jiffies_to_msecs(j - sd_start_j));
 	pr_info(SD " rq nr_running=%u cfs=%u rt=%u rt_throttled=%d rt_time=%lluus rt_runtime=%lldus sysctl_rt=%d/%u nr_switches=%llu\n",
 		rq->nr_running, rq->cfs.h_nr_running, rq->rt.rt_nr_running,
 		rq->rt.rt_t

