 /**
  * @brief Set the CSRC in the select FD table
  *
  * @param[in] sdata The sdata
  * @param[in] csrc The CSRC
  * @param[in] mask The mask to apply to the CSRC
  *
  * @return MS_OK or MS_ERROR
  */
 t_msReturnCodes slm_setCsrc(int sdata, int csrc, int mask)
 {
     int i, j;
     t_msReturnCodes retval = MS_ERROR;

     // loop through all fds
     for (i = 0; i < MAX_MS_SELECT_FDS; i++) {
         // loop through the shared spot
         for (j = 0; j < MAX_MS_SHARED_FDS; j++) {
             // find the correct sdata
             if (fdDSP.fdfcn[i].sessInfo[j].sdata == sdata) {
                 // found it
                 fdDSP.fdfcn[i].sessInfo[j].csrc = csrc;
                 fdDSP.fdfcn[i].sessInfo[j].mask = mask;
                 retval = MS_OK;
                 SYSLOG(LOG_NOTICE | MS_SELECT,
                        "Add positional CSRC [idx=%d][subidx=%d]"
                        "[sdata=%d][csrc=%d][mask=%d]",
                        i, j, sdata, csrc, mask);
                 break;
             }
         }
     }

     return retval;
 }

 //--------------------------------------------------------------------------;
