 //==========================================================================;
 // Function:
 //   int slm_createServerSocket(void)
 //
 // Description:
 //   This function creates a local socket.  The local socket is used to get the
 //   select thread out of the select.  This will bind and connect the socket.
 //
 // Parameters:
 //   None
 //
 // Returns:
 //   The local socket or MS_ERROR
 //==========================================================================;
 int slm_createServerSocket(void)
 {
     int sock = MS_ERROR;
     struct sockaddr_un addr;
     struct sockaddr_un* addrPtr = &addr;

     memset ( &addr, 0x00, sizeof(struct sockaddr_un) );

     // create IPC to receive requests, a local socket, which is selectable
     sock = socket( PF_LOCAL, SOCK_DGRAM, 0);

     // make an address
     addr.sun_family = AF_LOCAL;
     strncpy(addr.sun_path, RTP_SOCK, strlen(RTP_SOCK)+1);

     unlink(addr.sun_path);

     // bind the socket to the address
     if (bind(sock, (struct sockaddr *)addrPtr, sizeof(struct sockaddr_un)) < 0) {
         SYSLOG (LOG_ERR, "select thread-  bind error %m");
         close(sock);
         sock = MS_ERROR;
     }

     SYSLOG (LOG_NOTICE | MS_SELECT,
             "Server socket created [sock=%d]", sock);
     return sock;
 }

