 int rtpsndrcv_recvFromWTos(int sock, char* buf, int bufSize, t_peerIP* peerIPPtr,
                            int* tos_received)
 {
     int retVal = MS_OK;
     int peerIPlen = sizeof(t_peerIP);

     // default to ipv4
     bool ipv4 = (peerIPPtr->peerAddr.sa_family == AF_INET6) ? false : true;

     retVal = sockm_recvfromWtos(sock, buf, bufSize, 0, &peerIPPtr->peerAddr,
                                 (socklen_t*) &peerIPlen, tos_received);

     // check ip type and log
     if (ipv4 == true) {
         LOG (LOG_DEBUG|MS_STREAM, "[bytes=%d][peerIP=IPv4::0x%x][tos=0x%x]",
              retVal, (unsigned int) peerIPPtr->peerIP.sin_addr.s_addr,
              *tos_received);
     } else {
         LOG (LOG_DEBUG|MS_STREAM, "[bytes=%d][peerIP=IPv6::0x%x][tos=0x%x]",
