/**
 * This function receives rtp audio packets from the socket.  If can't get a
 * buffer the error message is logged in the common function.
 *
 * @param sock - The socket to read from
 * @param streamId - MS src element Id
 * @return MS_OK if successful, MS_ERROR if otherwise
 */
int rtpmgr_rcvAudioPacket(int sock, int streamId)
{
    int bufSize;
    char* buf;
    int retVal;

    // validate the streamId
    if ((streamId <= 0) || (streamId > MAX_MS_MELEMENTS)) {
        MS_LOG_SESSION(MS_STREAM | LOG_ERROR, streamMgr.ops.getSessionId(streamId),
                       "Invalid stream ID [streamId=%d]", streamId);
        return MS_ERROR;
    }

    bufSize = packetBufferManagerGetAudioBufferSize();
    buf = (char*)packetBufferManagerGetAudioBuffer();

    // IPV6 TODO: In previous code this called rtp_convergeRxStack which
    //            manipulates data structures only allowed to be changed
    //            by MS Thread, therefore, code has been removed for now.

    // rcv from socket, send it for processing
    retVal = rtpsndrcv_rcvPacket(sock, streamId, buf, bufSize);

#ifdef EXTRA_RTP_STATS
    rtpsndrcv_selectStats(streamId);
#endif

    return retVal;
}

/**
 * @brief This function allocates an audio buffer and passes it to the
 *        audio demux function
 *
 * @param[in] sock : The socket
 * @param[in] fdPtr : A pointer to the FD session information
 *
 * @return MS_OK or MS_ERROR
 */
int rtpmgr_demuxAudioPacket(int sock, const t_fdsession* fdPtr)
{
    int i, bufSize;
    char* buf;
    int retVal = MS_ERROR;
    bool stream_good = false;

    // validate the streamId
    for (i = 0; i < MAX_MS_SHARED_FDS; i++) {
        if ((fdPtr[i].sdata > 0) && (fdPtr[i].sdata < MAX_MS_MELEMENTS)) {
            stream_good = true;
            break;
        }
    }

    // only continue if there is a valid streamId
    if (stream_good == true) {
        bufSize = packetBufferManagerGetAudioBufferSize();
        buf = (char*)packetBufferManagerGetAudioBuffer();

        // send to demux function
        retVal = rtpsndrcv_demuxPacket(sock, fdPtr, buf, bufSize);
    } else {
        LOG(MS_STREAM | LOG_ERROR, "No valid stream ID");
    }

    return retVal;
}

