 /*
  * Called from __skb_recv_udp() when a receive returns -EAGAIN.  Records the
  * socket if datagram_poll()/udp_poll() would still report it readable,
  * i.e. select()/poll() and recv() disagree.  Printed at most once a second.
  */
 void starve_dbg_udp_eagain(struct sock *sk)
 {
 	struct sk_buff_head *q = &sk->sk_error_queue;
 	const struct inet_sock *inet = inet_sk(sk);
 	struct sd_icmp last_icmp = {};
 	struct sk_buff *skb;
 	unsigned long flags, gap = 0;
 	bool print = false;
 	struct sd_udp s;
 	u64 now;

 	s.err = READ_ONCE(sk->sk_err);
 	s.shut = READ_ONCE(sk->sk_shutdown);
 	s.eq = skb_queue_len_lockless(q);
 	s.rq = skb_queue_len_lockless(&sk->sk_receive_queue);
 	s.rdq = skb_queue_len_lockless(&udp_sk(sk)->reader_queue);
 	if (!s.err && !s.eq && !s.rq && !s.rdq && !(s.shut & RCV_SHUTDOWN))
 		return;

 	s.ee_errno = 0;
 	s.ee_origin = 0;
 	s.ee_type = 0;
 	s.ee_code = 0;
 	spin_lock_irqsave(&q->lock, flags);
 	skb = skb_peek(q);
 	if (skb) {
 		const struct sock_extended_err *ee = &SKB_EXT_ERR(skb)->ee;

 		s.ee_errno = ee->ee_errno;
 		s.ee_origin = ee->ee_origin;
 		s.ee_type = ee->ee_type;
 		s.ee_code = ee->ee_code;
 	}
 	spin_unlock_irqrestore(&q->lock, flags);

 	s.pid = current->pid;
 	s.policy = current->policy;
 	memcpy(s.comm, current->comm, TASK_COMM_LEN);
 	s.comm[TASK_COMM_LEN - 1] = '\0';
 	s.raddr = inet->inet_daddr;
 	s.lport = inet->inet_num;
 	s.rport = ntohs(inet->inet_dport);
 	s.err_soft = READ_ONCE(sk->sk_err_soft);
 	s.state = sk->sk_state;
 	s.recverr = inet->recverr;
 	s.rmem = atomic_read(&sk->sk_rmem_alloc);
 	s.rcvbuf = READ_ONCE(sk->sk_rcvbuf);
 	s.drops = atomic_read(&sk->sk_drops);

 	local_irq_save(flags);
 	now = local_clock();
 	s.ts = now;
 	s.seq = ++sd_cnt[SD_CNT_UDP_EAGAIN_RD];
 	if (s.seq <= 4 || now - sd_udp_push_ns >= SD_UDP_RING_NS) {
 		sd_udp_push_ns = now;
 		sd_udp_ring[sd_udp_head++ & (SD_NR_UDP - 1)] = s;
 	}
 	if (!sd_udp_printed || time_after_eq(jiffies, sd_udp_print_j + HZ)) {
 		print = true;
 		gap = s.seq - sd_udp_print_seq;
 		sd_udp_printed = true;
 		sd_udp_print_j = jiffies;
 		sd_udp_print_seq = s.seq;
 		last_icmp = sd_icmp_ring[(sd_icmp_head - 1) & (SD_NR_ICMP - 1)];
 	}
 	local_irq_restore(flags);

 	if (!print)
 		return;
 	pr_warn(SD "udp readable-but-EAGAIN: %lu event(s) since last print\n",
 		gap);
 	sd_print_udp_snap(" udp", &s);
 	if (last_icmp.ts)
 		sd_print_icmp_entry(&last_icmp);
 }

 /* Called from __udp4_lib_err() (softirq) for ICMP errors matched to sk. */
 void starve_dbg_udp_icmp(struct sock *sk, __be32 from, __be32 saddr,
 			 __be32 daddr, __be16 dport, int type, int code)
 {
 	struct sd_icmp *e;
 	unsigned long flags;
 	bool local = from == saddr;

 	local_irq_save(flags);
 	sd_cnt[SD_CNT_UDP_ICMP]++;
 	if (local)
 		sd_cnt[SD_CNT_UDP_ICMP_LOCAL]++;
 	e = &sd_icmp_ring[sd_icmp_head++ & (SD_NR_ICMP - 1)];
 	e->ts = local_clock();
 	e->from = from;
 	e->daddr = daddr;
 	e->dport = ntohs(dport);
 	e->lport = inet_sk(sk)->inet_num;
 	e->type = type;
 	e->code = code;
 	e->recverr = inet_sk(sk)->recverr;
 	e->local = local;
 	local_irq_restore(flags);
 }

