 /*
  * Histogram of what an RT user task (current) is doing on each tick: the
  * syscall number and first argument from its user pt_regs, or the user
  * PC.  The user call site is resolved on the first hit of each entry.
  */
 static void sd_account_sys(struct task_struct *p, int user)
 {
 #ifdef CONFIG_ARM
 	struct pt_regs *u = task_pt_regs(p);
 	unsigned long arg0 = 0;
 	struct sd_sys *s;
 	int nr, i;

 	if (user) {
 		nr = -1;
 		arg0 = u->ARM_pc & ~0x3fUL;
 	} else if (u->ARM_ORIG_r0 != ~0UL) {
 		nr = (int)u->ARM_r7;
 		arg0 = u->ARM_ORIG_r0;
 	} else {
 		nr = -2;
 	}

 	for (i = 0; i < SD_NR_SYS; i++) {
 		s = &sd_sys[i];
 		if (!s->hits) {
 			s->pid = p->pid;
 			s->nr = nr;
 			s->arg0 = arg0;
 			sd_sys_where(s, u);
 		} else if (s->pid != p->pid || s->nr != nr ||
 			   s->arg0 != arg0) {
 			continue;
 		}
 		s->hits++;
 		if (nr >= 0 && sd_sys_has_fd(nr))
 			sd_fd_desc(s->sock, sizeof(s->sock), arg0);
 		return;
 	}
 	sd_sys_other++;
 #endif
 }

 static void sd_print_sys(int max)
 {
 	const struct sd_sys *s;
 	int i, k, best;

 	memset(sd_used, 0, sizeof(sd_used));
 	for (k = 0; k < max; k++) {
 		best = -1;
 		for (i = 0; i < SD_NR_SYS; i++) {
 			if (!sd_sys[i].hits || sd_used[i])
 				continue;
 			if (best < 0 || sd_sys[i].hits > sd_sys[best].hits)
 				best = i;
 		}
 		if (best < 0)
 			break;
 		sd_used[best] = true;
 		s = &sd_sys[best];
 		pr_info(SD " rt %u ticks pid %d %s(%d) a0=%#lx %s\n", s->hits,
 			s->pid, sd_sys_name(s->nr), s->nr, s->arg0, s->sock);
 		pr_info(SD "    at %s\n", s->where);
 	}
 	if (sd_sys_other)
 		pr_info(SD " rt <others>: %u ticks\n", sd_sys_other);
 }

