 //==========================================================================;
 // Function:
 //   void slm_selectThread(void)
 //
 // Description:
 //   This function implements the select thread.  It will read the select readset.
 //
 // Parameters:
 //   None
 //
 // Returns:
 //   None
 //==========================================================================;
 void slm_selectThread(void)
 {
     int fd, rv;
     int retVal;
     int select_slot;
     struct sched_param param = { .sched_priority = MEDIA_SELECT_PRIORITY };

     SYSLOG(LOG_NOTICE | MS_SELECT, "Select thread starting...");

     // name the thread
     rv = prctl(PR_SET_NAME, (unsigned long) "ms_selectThread", 0, 0, 0);
     if (rv == -1) {
         SYSLOG(LOG_NOTICE | MS_INIT,"Can't set thread name");
     }

     // create the local socket
     fd = slm_createServerSocket();

     // check for error in create
     if (fd == MS_ERROR) {
         SYSLOG(LOG_ERR, "Can't create local socket for select thread");
     } else {
         // tell whoever is waiting that this thread has started
         sem_post(&semSelectThread);

         // get a slot for the select manager
         select_slot = slm_getFileDescriptorBlk(fd);

         // check for error
         if (select_slot == MS_ERROR) {
             SYSLOG(LOG_ERR,
                    "No available file descriptor blocks for select thread");
             if(close(fd) != 0){
                 SYSLOG(LOG_WARNING,"close socket %d error",fd);
             }
         } else {
             // initialize the local socket in the fd blk
             retVal = slm_selectFdInit(select_slot, fd, 1, slm_readIPC, NULL, NULL);

             if (retVal != MS_ERROR) {
                 // set the scheduling policy to realtime roundrobin
                 if (sched_setscheduler(0, SCHED_RR, &param) == -1) {
                     SYSLOG(LOG_ERR, "Can't set scheduling policy - %m");
                     setpriority(PRIO_PROCESS,0,TID_SELECT_RTPRX);
                 }

                 // loop forever.  handling all reads
                 while (1) {
                     slm_selectRead();
                 }
             } else {
                 SYSLOG(LOG_ERR, "Select thread not started - init error");
                 slm_closeIPC();
                 if(close(fd)!=0){
                     SYSLOG(LOG_WARNING,"close socket %d error,errno:%d",fd,errno);
                 }
             }
         }
     }
 }

