  * @param[in] idx    : The FD table index
  * @param[in] sdata  : The FD specific data
  *
  * @return true if slot was found, false otherwise
  */
 static bool slm_selectFdClose_locked(int idx, int sdata, t_proxyHdl proxyHdl)
 {
   int i;
   bool slotFound = false;

     if (fdDSP.fdfcn[idx].inuse == TRUE) {
         if (-1!=proxyHdl) {
             if (fdDSP.fdfcn[idx].proxyHdl==proxyHdl) {
                 slotFound = true;
                 fdDSP.fdfcn[idx].proxyHdl = 0;
                 fdDSP.fdfcn[idx].f_portProxy = NULL;
             }
         } else {
             // loop and find the sdata
             for (i = 0; i < MAX_MS_SHARED_FDS; i++) {
                 // find the slot to close.  have to match the
                 // socket data
                 if (fdDSP.fdfcn[idx].sessInfo[i].sdata == sdata) {
                     slotFound = true;

                     // decrement the demux count
                     fdDSP.fdfcn[idx].demuxCount--;

                     if (fdDSP.fdfcn[idx].demuxCount <= ZERO_FD_OWNER) {
                         fdDSP.fdfcn[idx].demuxCount = 0;
                     }

                     // found the spot.  now init it.
                     fdDSP.fdfcn[idx].sessInfo[i].sdata = 0;
                     fdDSP.fdfcn[idx].sessInfo[i].csrc = 0;
                     fdDSP.fdfcn[idx].sessInfo[i].mask = 0;
                 }
             }
         }
         if ((fdDSP.fdfcn[idx].demuxCount <= ZERO_FD_OWNER) && (!fdDSP.fdfcn[idx].f_portProxy))  {
             // no one sharing. mark the file descriptor as not active
             // fdDSP.fdfcn[idx].state = FD_INIT;
             SYSLOG(LOG_NOTICE | MS_SELECT,
                    "Socket marked inactive [idx=%d][sdata=%d][fd=%d]"
                    "[reserved=%d][count=%d]",
                    idx, sdata, fdDSP.fdfcn[idx].fd,
                    fdDSP.fdfcn[idx].reservedCount,
                    fdDSP.fdfcn[idx].demuxCount);
         }
     } else {
         SYSLOG(LOG_WARNING | MS_SELECT,
                "Slot not in use [idx=%d][sdata=%d][fd=%d][reserved=%d][count=%d]",
                idx, sdata, fdDSP.fdfcn[idx].fd, fdDSP.fdfcn[idx].reservedCount,
                fdDSP.fdfcn[idx].demuxCount);
     }

     if (slotFound == false) {
         SYSLOG(LOG_WARNING | MS_SELECT,
                "Slot not found [idx=%d][sdata=%d]", idx, sdata);
     }

   return slotFound;
 }

 /**
  * @brief This function releases the slot if no one is using it
  *
  * @description This function will also clear the fd entry if not in use.
  *              The correct order is to call selectFdClose prior to this
  *              function.
  *
  * @param[in] idx    : The FD table index
  * @param[in] sdata  : The FD specific data
  *
  * @return reserved count or MS_ERROR
  */
 int slm_selectFdRemove(int idx, int sdata, t_proxyHdl proxyHdl)
 {
     int retVal = MS_OK;
     int i;

     // lock the mutex
     (void)pthread_mutex_lock(&fdMutex);

     if (fdDSP.fdfcn[idx].inuse == TRUE) {
         // decrement the reserved count
         fdDSP.fdfcn[idx].reservedCount--;

         // normal case.  there is no one in this slot.  should
         // never be negative but check just in case
         if (fdDSP.fdfcn[idx].reservedCount <= ZERO_FD_OWNER) {
             // clear the file descriptor
             fdDSP.fdfcn[idx].inuse = FALSE;
             fdDSP.fdfcn[idx].fd = 0;
             fdDSP.fdfcn[idx].state = FD_INIT;
             fdDSP.fdfcn[idx].f_exec = 0;
             fdDSP.fdfcn[idx].f_demux = 0;
             fdDSP.fdfcn[idx].f_portProxy = 0;

             // remove any sub-slot data; in case close
             // was not called
             for (i = 0; i < MAX_MS_SHARED_FDS; i++) {
                 fdDSP.fdfcn[idx].sessInfo[i].sdata = 0;
                 fdDSP.fdfcn[idx].sessInfo[i].csrc = 0;
                 fdDSP.fdfcn[idx].sessInfo[i].mask = 0;
             }
             fdDSP.fdfcn[idx].proxyHdl = 0;

             // the demux count should be 0
             if (fdDSP.fdfcn[idx].demuxCount > ZERO_FD_OWNER) {
                 SYSLOG(LOG_WARNING | MS_SELECT,
                        "Demux Count is bad.  Zero it [idx=%d][count=%d]",
                        idx, fdDSP.fdfcn[idx].demuxCount);
                 fdDSP.fdfcn[idx].demuxCount = 0;
             }

             SYSLOG(LOG_NOTICE | MS_SELECT,
                    "Removed slot [idx=%d][reserved=%d][count=%d]",
                    idx, fdDSP.fdfcn[idx].reservedCount,
                    fdDSP.fdfcn[idx].demuxCount);
         } else {
             // someone else lives in this slot.
             if (-1!=proxyHdl) {
                 if (fdDSP.fdfcn[idx].proxyHdl==proxyHdl){
                     SYSLOG(LOG_NOTICE | MS_SELECT,
                            "Removed [idx=%d][reserved=%d][proxyHdl=%d][proxyf=%p]",
                            idx, fdDSP.fdfcn[idx].reservedCount,
                            fdDSP.fdfcn[idx].proxyHdl,
                            fdDSP.fdfcn[idx].f_portProxy);
                     fdDSP.fdfcn[idx].proxyHdl = 0;
                     fdDSP.fdfcn[idx].f_portProxy = NULL;
                 }
             } else {
                 // check if
                 // 1. reserved, init'ed but not closed.
                 for (i = 0; i < MAX_MS_SHARED_FDS; i++) {
                     // has our data been cleared
                     if (fdDSP.fdfcn[idx].sessInfo[i].sdata == sdata) {
                         // remove our sub-slot data
                         fdDSP.fdfcn[idx].sessInfo[i].sdata = 0;
                         fdDSP.fdfcn[idx].sessInfo[i].csrc = 0;
                         fdDSP.fdfcn[idx].sessInfo[i].mask = 0;
                         SYSLOG(LOG_NOTICE | MS_SELECT,
                                "Removed sub-slot [idx=%d][reserved=%d][count=%d]",
                                idx, fdDSP.fdfcn[idx].reservedCount,
                                fdDSP.fdfcn[idx].demuxCount);
                         break;
                     }
                 }
             }
         }

         // return the reserved count
         retVal = fdDSP.fdfcn[idx].reservedCount;
     } else {
         SYSLOG(LOG_ERR,
                "Trying to clear an unallocated file descriptor element [idx=%d]",
                idx);

         retVal = MS_ERROR;
     }

     // unlock mutex
     (void)pthread_mutex_unlock(&fdMutex);

     return retVal;
 }

 //==========================================================================;
 // Function:
 //   void slm_closeIPC(void)
 //
 // Description:
 //   This function closes the local socket.
 //
 // Parameters:
 //   None
 //
 // Returns:
 //   None
 //==========================================================================;
 void slm_closeIPC(void)
 {
     struct sockaddr_un addr;

     memset ( &addr, 0x00, sizeof(struct sockaddr_un) );

     // make an address
     addr.sun_family = AF_LOCAL;
     strncpy(addr.sun_path, RTP_SOCK, strlen(RTP_SOCK)+1);

     unlink(addr.sun_path);
 }

 //==========================================================================;
 // Function:
 //   int slm_readIPC(int fd, int udata)
 //
 // Description:
 //   This function reads the local socket.  No need to unmarshal the message.
 //   The message is simply a way to get the select thread to reinitialize its
 //   readset.  More than likely, a socket has been removed or added.
 //
 // Parameters:
 //   None
 //
 // Returns:
 //   MS_ERROR if you want select to clear it. other wise MS_OK
 //==========================================================================;
 int slm_readIPC(int fd, int udata)
 {
     (void) udata; // Unused Param
     int readlen;
     char msg[1];

     // read the IPC message (sent from mt thread )
     readlen = recv (fd, msg, 1, 0);
     SYSLOG(LOG_NOTICE | MS_SELECT,
            "[fd=%d] Select thread got message", fd);

     if (readlen == MS_ERROR) {
         SYSLOG (LOG_ERR, "local socket read error [error=%s]", strerror(errno));
         return MS_ERROR;
     }

     return MS_OK;
 }

 /**
  * @brief int slm_dummyRead_locked(int idx, int fd)
  *    This function reads the socket when there is no active session attached
  *    to it.
  *    In case that the socket read returns error, mark the socket as inactive.
  *
  * @param[in] idx    : The FD table index
  * @param[in] fd     : The FD of socket
  *
  * @return the data length from socket recv
  */
 int slm_dummyRead_locked(int idx, int fd)
 {
     int readlen;
     char msg[1500];
     static int dummyReadCnt = 0;

     readlen = recv(fd, msg, sizeof(msg), 0);
     if ( dummyReadCnt++%1000 == 0 ) {
         SYSLOG(LOG_DEBUG, "dummy read socket[fd=%d] for [idx=%d]",
                           fdDSP.fdfcn[idx].fd, idx);
     }

     if ( readlen <= 0 ) {
         fdDSP.fdfcn[idx].state = FD_INIT;
     }
     return readlen;
 }

 //==========================================================================;
 // Function:
 //   void slm_writeIPC(void)
 //
 // Description:
 //   This function writes to the local socket.  The message is simply a way to
 //   get the select thread to reinitialize its readset.  More than likely, a
 //   socket has been removed or added.
 //
 // Parameters:
 //   None
 //
 // Returns:
 //   None
 //==========================================================================;
 void slm_writeIPC(void)
 {
     int rc;
     char msg[1]="";

     rc = send(fdDSP.fdwrite, msg, 1, 0);
     if (rc == MS_ERROR) {
         SYSLOG (LOG_ERR, "local socket write error [error=%s]", strerror(errno));
     }
 }

