 //==========================================================================;
 // Function:
 //   int rtpsndrcv_readError (int streamId, int sock, int saved_errno)
 //
 // Description:
 //   This function handles error processing on socket read
 //
 // Parameters:
 //   streamId - The stream ID
 //   sock - The socket
 //   saved_errno - The errno
 //
 // Returns:
 //   -1 = hard error
 //   0  = a soft error (ICMP_UNREACHABLE) the far-end may be delayed by signaling
 //
 // Note:
 //  In ipg5/ipg6 phones where wifi is prevalent, MS frequently receives an
 //  'ICMP UNREACHABLE' (an rcvfrom error),
 //  at the begining of a call (e.g. 60 ms after ms_startRTPSessionTx and 90 ms after
 //  ms_startRTPSessionRx).
 //  this has caused 1-way audio problem.
 //  Code is changed return a normal status so that the caller will not take action to
 //  disable select-read
 //==========================================================================;
 static int rtpsndrcv_readError (int streamId, int sock, int saved_errno)
 {
     struct msghdr msg;
     char cmsgbuf[512];
     int retVal ;
     int rc = 0;

     // don't need to display every error....
     if ((++read_error % RECV_ERROR) == READ_ERROR_DISPLAY) {
         MS_LOG_SESSION(LOG_ERR, streamMgr.ops.getSessionId(streamId),
                        "[stream=%d][sock=%d] "
                        "receive error [last errno=%s][count=%d]",
                        streamId, sock,
                        strerror(saved_errno), read_error);
     }

     // First read more detailed error
     // but do not get original message.
     memset(&msg, 0, sizeof(struct msghdr));
     memset(&cmsgbuf, 0, sizeof(cmsgbuf));
     msg.msg_control = &cmsgbuf;
     msg.msg_controllen = sizeof(cmsgbuf);
     retVal = recvmsg(sock, &msg, MSG_ERRQUEUE);

     // special error handling for these types of errors
     if (transport_isIgnorableSocketError(saved_errno)) {
         bool sendICMPErrorNow = false;
         bool sendICMPError = false;
         bool sendICMPTTLExceeded = false;
         struct cmsghdr *cmsg;
         struct sockaddr TTLExceededRemoteHost;
         rc = MS_ICMP_UNREACHABLE_ERROR;     // a connection error count as a soft error
         // this fix a 1-way audio problem seen in wifi

         // Check for actual reason
         if (retVal != MS_ERROR) {
             // valid cmsg

             for (cmsg = CMSG_FIRSTHDR(&msg); cmsg; cmsg = CMSG_NXTHDR(&msg, cmsg)) {
                 // look for port unreachable ICMP error
                 if ((cmsg->cmsg_level == IPPROTO_IP) && (cmsg->cmsg_type == IP_RECVERR)) {
                     struct sock_extended_err *ee;

                     ee = (struct sock_extended_err *)CMSG_DATA(cmsg);
                     if (ee->ee_origin == SO_EE_ORIGIN_ICMP) {
                         // For TTL Exceeded send TTL Exceeded
                         // For other ICMP Error, for port unreachable send ICMP error
                         // immediately. Otherwise, let error threshold do
                         // it's job.

                         if ((ee->ee_type == ICMP_DEST_UNREACH ) &&
                             (ee->ee_code == ICMP_PORT_UNREACH)) {
                             // host responded with port unreachable
                             LOG(LOG_WARNING, "[sock=%d][errno=%s] -"
                                 " remote host sent ICMP-UNREACHABLE, a"
                                 " forced notification event ",
                                 sock, strerror(saved_errno));
                             // will force to send an event to all clients
                             sendICMPError = true;
                             sendICMPErrorNow = true;
                         } else if ((ee->ee_type == ICMP_TIME_EXCEEDED) &&
                                    (ee->ee_code == ICMP_EXC_TTL)) {
                             // host responded with TTL TIME EXCEEDED
                             LOG(LOG_DEBUG, "[sock=%d][errno=%s] -"
                                 " remote host sent ICMP_TIME_EXCEEDED, a"
                                 " forced notification event ",
                                 sock, strerror(saved_errno));
                             sendICMPTTLExceeded = true;
                             memcpy (&TTLExceededRemoteHost, SO_EE_OFFENDER(ee),
                                     sizeof(TTLExceededRemoteHost));
                         } else {
                             LOG(LOG_WARNING,
                                 "[sock=%d][errno=%s][icmpType=%d][icmpCode=%d] - "
                                 "recvfrom failed",
                                 sock, strerror(saved_errno),
                                 ee->ee_type, ee->ee_code);
                             sendICMPError = true;
                         }
                     } // end ICMP error
                 } // end IP protocol error
             } // end processing each cmsg
         }


         if (sendICMPTTLExceeded) {
             const t_sockaddr *addr = streamMgr.ops.getRxLocalAddress(streamId);
             if (addr) {
                 callbackMgr.ops.icmpTTLExceeded(streamMgr.ops.getSessionId(streamId),
                                                 &TTLExceededRemoteHost, addr->port);
             } else {
                  LOG(LOG_ERR, "Local address is NULL !");
                  return (MS_ERROR);
             }
         }

         if (sendICMPError) {
             const t_sockaddr *addr = streamMgr.ops.getRxRemoteAddress(streamId);
             // make sure remote address not null
             if ( addr != NULL ) {
                 // report the error to the client
                 rtpsndrcv_icmpError(streamId, &(addr->ip),
                                     addr->port, sendICMPErrorNow);
             } else {
                 LOG(LOG_ERR, "Remote address is NULL !");
             }
         } else {
             rc = MS_OK;
         }
     }
     else {
         if  (saved_errno == EAGAIN) {
             rc = MS_OK;
             LOG(LOG_WARNING, "EAGAIN occurs, [sock=%d] [errno=%d] - ignoring ",
                 sock, saved_errno);
         } else {
             rc = MS_ERROR;
             LOG(LOG_ERR, "a hard error occurs, [sock=%d] [errno=%d] - unknown error ",
                 sock, saved_errno);
         }
     }

     return rc;
 }

 /**
  * @brief Read the packet using recvfrom
  *
  * @param[in] sock The socket
  * @param[in] buf The allocated buffer
  * @param[in] bufSize The size of the allocated buffer
  * @param[out] peerIPPtr The remote IP pointer
  *
  * @return The number of bytes read
  */
 int rtpsndrcv_recvFrom(int sock, char* buf, int bufSize, t_peerIP* peerIPPtr)
 {
     int retVal = MS_OK;
     int peerIPlen = sizeof(t_peerIP);

     retVal = recvfrom(sock, buf, bufSize, 0, &peerIPPtr->peerAddr,
                       (socklen_t*) &peerIPlen);
     return retVal;
 }

 /**
  * @brief Read the packet with TOS
  *
  * @note Used for 1st rx packet or to prepare for a new
  *       stream stat
  *
  * @param[in] sock The socket
  * @param[in] buf The allocated buffer
  * @param[in] bufSize The size of the allocated buffer
  * @param[out] peerIPPtr The remote IP pointer
  * @param[out] tos_received The TOS from the packet
  *
