  * @param[in] buf The allocated buffer
  * @param[in] bufSize The size of the allocated buffer
  * @param[out] peerIPPtr The remote IP pointer
  *
  * @return The number of bytes read
  */
 int rtpsndrcv_readPacket(int sock, int streamId, char* buf, int bufSize,
                          t_peerIP* peerIPPtr)
 {
     int retVal = MS_OK;

     // check if TOS is enabled
     if (streamMgr.ops.getRxTosDisable(streamId)) {
         // read the packet
         retVal = rtpsndrcv_recvFrom(sock, buf, bufSize, peerIPPtr);
         if (retVal!=MS_ERROR) {
             int nBytes=retVal;
             retVal = rtpsndrcv_checkForStunTurn(sock, buf, nBytes, peerIPPtr);
         }
     } else {
         int tos_received = 0;

         // read the packet
         retVal = rtpsndrcv_recvFromWTos(sock, buf, bufSize, peerIPPtr, &tos_received);
         if (retVal!=MS_ERROR) {
             int nBytes=retVal;
             retVal = rtpsndrcv_checkForStunTurn(sock, buf, nBytes, peerIPPtr);
             if (retVal) {
                 // default to ipv4
                 bool ipv4 = (peerIPPtr->peerAddr.sa_family == AF_INET6) ? false : true;

                 streamMgr.ops.setRxTos(streamId, tos_received);

                 // there is no need to refresh tos value for each packet received
                 // if TOS is ever changed (via SGP), either the stream is hold-resumed
                 // or restarted with a new rtp session
                 // redirect to use recvfrom for rest packets, until rx is restarted or
                 // ms_getSessionPegs is issued option = do not receive TOS
                 sockm_setRecvTosEnable((ipv4 == true) ? INADDR_IPV4 : INADDR_IPV6, sock, 0);

                 // redirect to use recvfrom for rest packets.
                 streamMgr.ops.setRxTosDisable(streamId, 1);
             }
         }
     }
     return retVal;
 }

