 {
   int index;
   t_msReturnCodes retVal=MS_ERROR;

   index=ppxy_netPortProxyGetSlot();
   if (PORT_PROXY_UNDEFINED!=index) {
     t_sockaddr addr;
     portProxy[index].sock=sock;
     portProxy[index].externalHdl=externalHdl;
     if (MS_OK==sockm_getSocketAddr(sock, &addr)) {
       if (addr.port&0x1) { // rtcp
         rtcpMgr.ops.setPortProxyRx(sock, externalHdl);
       } else { //rtp
         selectMgr.ops.getFileDescriptorBlk(sock);
         selectMgr.ops.selectFdInit(selectMgr.ops.getFDIndex(sock),
                                    sock,
                                    externalHdl,
                                    NULL,
                                    NULL,
                                    ppxy_netPortProxyRxProcess);
         selectMgr.ops.writeIPC();
       }
       retVal = MS_OK;
     } else {
       MS_LOG_SESSION(LOG_ERROR, externalHdl, "could not find the socket");
       retVal = MS_ERROR;
     }
   } else {
     MS_LOG_SESSION(LOG_ERROR, externalHdl, "all instances exhausted");
   }
   return retVal;
 }

 static t_msReturnCodes ppxy_netPortProxyStop(int externalHdl)
 {
   int index = PORT_PROXY_UNDEFINED;
   int sock = 0;
   t_msReturnCodes retVal=MS_ERROR;
   t_sockaddr addr;

   index = ppxy_netPortProxyFindIndexFromExternalHdl(externalHdl);
   if( index == PORT_PROXY_UNDEFINED ) {
     LOG(LOG_ERROR, "reference [externalHdl=%d] not found", externalHdl);
     return MS_ERROR;
   }

   sock = portProxy[index].sock;
   if (sock>0){
     if (MS_OK==sockm_getSocketAddr(sock, &addr)) {
       if (addr.port&0x1) { // rtcp
         rtcpMgr.ops.removePortProxyRx(sock, externalHdl);
       } else { // rtp
         int fdIdx = selectMgr.ops.getFDIndex(portProxy[index].sock);
         selectMgr.ops.selectFdClose(fdIdx, -1, externalHdl);
         selectMgr.ops.writeIPC();
         selectMgr.ops.selectFdRemove(fdIdx, -1, externalHdl);
         sockm_closeSocket(sock);
       }
     }
   } else {
     MS_LOG_SESSION(LOG_ERROR, externalHdl, "cannot close [sock=%d]", sock);
   }

   ppxy_netPortProxyFreeSlot(index);
   retVal = MS_OK;

   return retVal;
 }

