TEST(TransportSocketErrorTest, TreatsNetworkErrorsAsIgnorable)
{
    const int errors[] = {
        ECONNREFUSED,
        EHOSTUNREACH,
        EHOSTDOWN,
        ENETUNREACH,
        ENONET,
        ENOPROTOOPT,
        EMSGSIZE,
        EPROTO,
        EOPNOTSUPP,
