TEST(TransportSocketErrorTest, RejectsLocalSocketErrors)
{
    const int errors[] = {
        EBADF,
        ENOTSOCK,
        EFAULT,
        ENOMEM,
    };

    for (const int errorCode : errors) {
        EXPECT_FALSE(transport_isIgnorableSocketError(errorCode)) << errorCode;
    }
}

