 int ppxy_netPortProxyCreateSession(t_sockaddr localSockAddr)
 {
     int sh, retVal = MS_OK;

     //allocate session block
     retVal = sessionMgr.ops.getSessionBlk();
     sh = retVal;
     if(sh == MS_ERROR) {
         LOG(LOG_ERR, "No available session block for creating"
                      "NetPortProxy Session [sh=%d]", sh);
