     }

     sessionMgr.ops.setSessionType(sh, SESSION_PROXY);

     LOG(LOG_NOTICE, "about to create session [addr=%s][port=%d][sh=%d]",
                     inet_ntoa(localSockAddr.ip._ipaddr.addr4), localSockAddr.port, sh);
     int sockfd = sockm_getInternetSocket(&localSockAddr);
     if(sockfd < 0) {
        LOG(LOG_ERR, "Could not get Net Port Proxy Socket");
        sessionMgr.ops.freeSessionBlk(sh);
        return MS_ERROR;
     }

     if (MS_OK != ppxy_netPortProxyStart(sockfd, sh)) {
         close(sockfd);
         sessionMgr.ops.freeSessionBlk(sh);
         sh=MS_ERROR;
     } else {
         ppxy_netPortProxySetupFunctions(sh);
