 static unsigned int ppxy_netPortProxyDrainErrorQueue(int sock)
 {
   unsigned int drained = 0;
   unsigned int attempts = 0;

   while ((drained < PORT_PROXY_ERRQUEUE_DRAIN_MAX) &&
          (attempts < PORT_PROXY_ERRQUEUE_DRAIN_MAX)) {
     char payload[1];
     char control[512];
     struct iovec iov;
     struct msghdr msg;
     ssize_t drainResult = 0;
     int drainErrno = 0;

     attempts++;

     memset(&msg, 0, sizeof(msg));
     memset(control, 0, sizeof(control));

     iov.iov_base = payload;
     iov.iov_len = sizeof(payload);

     msg.msg_iov = &iov;
     msg.msg_iovlen = 1;
     msg.msg_control = control;
     msg.msg_controllen = sizeof(control);

     drainResult = recvmsg(sock, &msg, MSG_ERRQUEUE | MSG_DONTWAIT);

     if (drainResult >= 0) {
       drained++;
       continue;
     }
     drainErrno = errno;

     if (drainErrno == EINTR) {
       continue;
     }

     if ((drainErrno == EAGAIN)
 #if EWOULDBLOCK != EAGAIN
         || (drainErrno == EWOULDBLOCK)
 #endif
       ) {
       break;
     }
     break;
   }

   return drained;
 }


 static int ppxy_netPortProxyRxProcess(int sock) {
   int bufSize = PORT_PROXY_PACKET_SIZE;
   char buf[PORT_PROXY_PACKET_SIZE];
   t_sockaddr peerSockAddr;
   int eagain_retry_count=0;
   t_peerIP peerIP;
   socklen_t peerIPlen = sizeof(t_peerIP);
   int retVal = 0;

   do {
     peerIPlen = sizeof(t_peerIP);

     retVal = recvfrom(sock, buf, bufSize, 0, &peerIP.peerAddr,
                       &peerIPlen);

     int recvErrno = (retVal == MS_ERROR) ? errno : 0;

     if (retVal >= 0) {
       int nBytes = retVal;
       if (ppxy_netPortProxyValidatePacket(&peerIP, buf, bufSize)){
         bool ipv4 = (peerIP.peerAddr.sa_family == AF_INET6) ? false : true;
         if (ipv4 == true) {
           peerSockAddr.ip.iptype = INADDR_IPV4;
           peerSockAddr.ip._ipaddr.addr4.s_addr = peerIP.peerIP.sin_addr.s_addr;
           peerSockAddr.port = peerIP.peerIP.sin_port;
         } else {
           peerSockAddr.ip.iptype = INADDR_IPV6;
           peerSockAddr.ip._ipaddr.addr6 = peerIP.peerIP6.sin6_addr;
           peerSockAddr.port = peerIP.peerIP6.sin6_port;
         }
         nppmgr_netPortProxyRxPktProcess(sock, &peerSockAddr, buf, nBytes);
       } else {
         LOG(LOG_ERR, "ppxy_validatePacket failed");
       }
       break;
     }

     if (recvErrno == EINTR) {
       continue;
     }

     if ((recvErrno == EAGAIN)
 #if EWOULDBLOCK != EAGAIN
     || (recvErrno == EWOULDBLOCK)
 #endif
         ) {
       if (eagain_retry_count < EAGAIN_RECFROM_RETRY_MAX) {
         usleep(5);
         eagain_retry_count++;
         continue;
       }

       retVal = MS_OK;
       break;
     }

     if (!transport_isIgnorableSocketError(recvErrno)) {
       errno = recvErrno;
       break;
     }

     (void)ppxy_netPortProxyDrainErrorQueue(sock);

     retVal = MS_OK;
     break;

   } while (true);

   // check if an error occurred
   return retVal;
 }

