  * @param[in] demuxf : The function that needs to be called when data
  *                     is available and demux needs to happen
  *
  * @return MS_OK or MS_ERROR
  */
 int slm_selectFdInit(int idx, int fd, int sdata, t_exec execf, t_demuxf demuxf, t_execPort portProxyf)
 {
     int retVal = MS_ERROR;
     int i = MAX_MS_SHARED_FDS;
     bool sameCaller = false;

     // lock the mutex
     (void)pthread_mutex_lock(&fdMutex);

     // check if the slot is inuse
     if (fdDSP.fdfcn[idx].inuse == TRUE) {
         // make sure the same caller didn't call again
         if ( portProxyf && (fdDSP.fdfcn[idx].proxyHdl == sdata)) {
             // return ok for same caller
             retVal = MS_OK;
             sameCaller = true;
         } else {
             for (i = 0; i < MAX_MS_SHARED_FDS; i++) {
                 // if this was called by same caller then do nothing
                 if (fdDSP.fdfcn[idx].sessInfo[i].sdata == sdata) {
                     // return ok for same caller
                     retVal = MS_OK;
                     sameCaller = true;
                     break;
                 }
             }
         }

         if (sameCaller == false) {
             if (portProxyf) {
                 fdDSP.fdfcn[idx].fd = fd;
                 fdDSP.fdfcn[idx].state = FD_ACTIVE;
                 fdDSP.fdfcn[idx].proxyHdl = sdata;
                 fdDSP.fdfcn[idx].f_portProxy = portProxyf;
                 retVal = MS_OK;
                 SYSLOG(LOG_NOTICE | MS_SELECT,
                        "[idx=%d][fd=%d][sdata=%d][reserved=%d][count=%d]"
                        "[func=%p][demuxfunc=%p][proxy func=%p]",
                        idx, fdDSP.fdfcn[idx].fd, sdata,
                        fdDSP.fdfcn[idx].reservedCount, fdDSP.fdfcn[idx].demuxCount,
                        fdDSP.fdfcn[idx].f_exec, fdDSP.fdfcn[idx].f_demux,
                        fdDSP.fdfcn[idx].f_portProxy);
             } else {
                 // make sure there is an open spot
                 if ((fdDSP.fdfcn[idx].demuxCount+1) < MAX_MS_SHARED_FDS) {
                     fdDSP.fdfcn[idx].fd = fd;
                     fdDSP.fdfcn[idx].state = FD_ACTIVE;

                     // loop and find a spot
                     for (i = 0; i < MAX_MS_SHARED_FDS; i++) {
                         // if the data is 0 then its open
                         if (fdDSP.fdfcn[idx].sessInfo[i].sdata == 0) {
                             // spot available; increment demux count
                             fdDSP.fdfcn[idx].demuxCount++;

                             // found a spot
                             fdDSP.fdfcn[idx].sessInfo[i].sdata = sdata;
                             fdDSP.fdfcn[idx].f_exec = execf;
                             fdDSP.fdfcn[idx].f_demux = demuxf;

                             retVal = MS_OK;
                             SYSLOG(LOG_NOTICE | MS_SELECT,
                                    "[idx=%d][fd=%d][sdata=%d][reserved=%d][count=%d]"
                                    "[func=%p][demuxfunc=%p][proxy func=%p]",
                                    idx, fdDSP.fdfcn[idx].fd, fdDSP.fdfcn[idx].sessInfo[i].sdata,
                                    fdDSP.fdfcn[idx].reservedCount, fdDSP.fdfcn[idx].demuxCount,
                                    fdDSP.fdfcn[idx].f_exec, fdDSP.fdfcn[idx].f_demux,
                                    fdDSP.fdfcn[idx].f_portProxy);
                             break;
                         }
                     }
                 }
             }
         }

         // did we find a spot
         if ((sameCaller == false) && (retVal == MS_ERROR)) {
             // we didn't find a spot
             SYSLOG(LOG_ERROR,
                    "No open fd sub-slot [idx=%d][fd=%d][sdata=%d]"
                    "[count=%d][func=%p]",
                    idx, fd, sdata, fdDSP.fdfcn[idx].demuxCount, execf);
         }
     } else {
         SYSLOG(LOG_ERR, "Unallocated file descriptor element "
                "[idx=%d][fd=%d][sdata=%d][reserved=%d][count=%d][func=%p]",
                idx, fd, sdata, fdDSP.fdfcn[idx].reservedCount,
                fdDSP.fdfcn[idx].demuxCount, execf);
     }

     // unlock the mutex
     (void)pthread_mutex_unlock(&fdMutex);

     return retVal;
 }

