                            "[stream=%d][sock=%d] "
                            "packet buffer allocation failed [count=%d]",
                            streamId, sock,
                            streamMgr.ops.getStreamPktBufAllocFailure(streamId));
         }

         // read the data out of the socket and drop it.
         bytes = recv(sock, fail_buff, FAILBUFF_SIZE, 0);

         if (bytes < 0) {
             rtpsndrcv_readError(streamId, sock, errno);
         }
     }

     do {
         // receive data in the buffer
         retVal = rtpsndrcv_recvFrom(sock, buf, bufSize, &peerIP);
         // Resource temporarily unavailable - sleep for 5 microsecs and retry
         if ((retVal == MS_ERROR) && (errno == EAGAIN) &&
             (eagain_retry_count < EAGAIN_RECFROM_RETRY_MAX)) {
             usleep(5);
             eagain_retry_count++;
         } else {
             break;
         }
     } while (TRUE);

     if (retVal!=MS_ERROR) {
         int nBytes = retVal;
         retVal=rtpsndrcv_checkForStunTurn(sock, buf, nBytes, &peerIP);
     }
     bytes = retVal;
     // check if an error occurred
     if ( (retVal != MS_ERROR) && bytes) {
         // (no rcvfrom error)
         bool validPacket = false;

         // filter out (multicast) packets sent by this IP itself
         // Unless it is from the Loopback Interface.  We need to allow those
         // through for
         // audio/video loopback testing.
         validPacket = rtpsndrcv_validatePacket(streamId, &peerIP, buf, bufSize);
         if (!validPacket) {
             // not valid packets - feedback
             // discard packet to avoid 'echo', but still need to release the buffer
             rtpmgr_notProcessPacket(buf,bufSize);
             return MS_OK;
         }

         if (rtpsndrcv_isFecPacket(streamId, buf)) {
             retVal = rtpsndrcv_checkEncryption(streamId, buf, &bytes, true);
             if (retVal != MS_ERROR) {
                 rtpsndrcv_addToFec(streamId, buf, bytes, bufSize, true);
             } else {
                 MS_LOG_SESSION(LOG_ERR, sessionId, "Error in decrypting FEC packet!!!");
             }
             rtpmgr_notProcessPacket(buf, bufSize);
             return retVal;
         }

         if (rtpsndrcv_isRTXPacket(streamId, buf)) {
             retVal = rtpsndrcv_checkEncryption(streamId, buf, &bytes, false);
             if (retVal != MS_ERROR) {
                 // TODO Feed into RTX receiver in MARI module
             } else {
                 MS_LOG_SESSION(LOG_ERR, sessionId, "Error in decrypting RTX packet!!!");
             }
             rtpmgr_notProcessPacket(buf, bufSize);
             return retVal;
         }
         // SRTP decryption.  We can use any streamId from this socket
         // to decrypt.  The key will be the same for all shared streams.
         retVal = rtpsndrcv_checkEncryption(streamId, buf, &bytes, false);

         // post-srtpunporotect
         if (retVal != MS_ERROR) {
             // packet is decrypted.  lets get the stream id from
             // the packet csrc.
             int packetId = rtpsndrcv_getStreamId(fdPtr, buf);

             // defaulting to the original stream id if we can't
             // find the real stream id from the fd table, i.e.
             // none of the positional csrc's matched
             streamId = (packetId == 0) ? streamId : packetId;

             // set some stream items
             rtpsndrcv_logStreamValues(streamId, bytes, sock, &peerIP);

             if (rtpsndrcv_netsim_isEnabled() &&
                 rtpsndrcv_networkSimulateRxTest(streamId, buf, bufSize, bytes)) {
                 return retVal;
             }

             retVal = rtpsndrcv_processRxPacket(streamId, sock, buf,
                                                bytes, bufSize);
         } else {
             // discard the packets due to the bad encryption
             rtpmgr_notProcessPacket(buf,bufSize);
             retVal = MS_OK;
         }
     } else { // recvfrom check
 #ifdef EXTRA_RTP_STATS
         streamMgr.ops.incRecvErrors(streamId);
 #endif
         // except ICMP_UNREACHABLE, a hard errormay cause the caller
         // to take some action
         // the existing code stops listen to this socket
         retVal = rtpsndrcv_readError(streamId, sock, errno);
         rtpmgr_notProcessPacket(buf, bufSize);
     }

     if (retVal == MS_ICMP_UNREACHABLE_ERROR) {
         retVal = MS_OK; // soft error; don't want to return -1
     }

     return (retVal);
 }

