static void sd_take_sample(unsigned long j, int user, unsigned long gap)
{
	struct pt_regs *regs = get_irq_regs();
	struct task_struct *p = current;
	unsigned int pcnt = sd_irq_pcnt();
	unsigned long pc = regs ? instruction_pointer(regs) : 0;
	struct sd_sample *s;

	if (gap > sd_max_gap)
		sd_max_gap = gap;
	sd_nsamples++;

	s = &sd_samples[sd_samples_head++ & (SD_NR_SAMPLES - 1)];
	s->j = j;
	s->pc = pc;
	s->lr = regs ? sd_lr(regs) : 0;
	s->pcnt = pcnt;
	s->pid = p->pid;
	s->user = user;

	sd_account_task(p, user, pcnt);
	sd_account_func(p->pid, user, pc);
}

static void sd_episode_begin(unsigned long j, unsigned long starve_j,
	unsigned int i, n;

	n = min(nmax, min_t(unsigned int, sd_nsamples, SD_NR_SAMPLES));
	for (i = n; i > 0; i--) {
