import re,glob,bisect
ts=re.compile(r'^\S+ \w{3} Nov 11 (\d\d):(\d\d):(\d\d\.\d+) \((\d+)-(\d+)\) (.*)$')
evs=[];marks=[]
for f in sorted(glob.glob('messages_2026*')):
    for ln,l in enumerate(open(f,errors='replace'),1):
        m=ts.match(l.rstrip())
        if not m: continue
        h,mi,s,pid,tid,msg=m.groups(); t=int(h)*3600+int(mi)*60+float(s)
        if 'CC_eventProc(event=14(CC_EV_USR_HOLD)' in msg: marks.append((t,'HOLD'))
        elif 'CC_eventProc(event=15(CC_EV_USR_RESUME)' in msg: marks.append((t,'RESUME'))
        elif 'ext sendto failed' in msg: evs.append((t,'sendto-ICMP',f,ln))
        elif 'POLL ERR happened on fd 39' in msg: evs.append((t,'POLLERR',f,ln))
marks.sort(); mt=[m[0] for m in marks]
from collections import Counter
hist=Counter()
for t,k,f,ln in evs:
    i=bisect.bisect_right(mt,t)-1
    if i<0: continue
    prev=marks[i]; dt=t-prev[0]
    if k=='sendto-ICMP': print('%s %s+%.3fs %s:%d'%(k,prev[1],dt,f,ln))
    hist[(prev[1], int(dt*10)/10.0 if dt<1 else ('1-2s' if dt<2 else '>2s'))]+=1
print('POLLERR+sendtoICMP timing after last HOLD/RESUME:')
for k in sorted(hist, key=lambda x:(x[0],str(x[1]))): print(' ',k,hist[k])
