+
+	s.pid = current->pid;
+	s.policy = current->policy;
+	memcpy(s.comm, current->comm, TASK_COMM_LEN);
+	s.comm[TASK_COMM_LEN - 1] = '\0';
+	s.raddr = inet->inet_daddr;
+	s.lport = inet->inet_num;
+	s.rport = ntohs(inet->inet_dport);
+	s.err_soft = READ_ONCE(sk->sk_err_soft);
+	s.state = sk->sk_state;
+	s.recverr = inet->recverr;
