+/* State of current's file descriptor @fd; IRQs disabled. */
+static void sd_fd_desc(char *buf, size_t len, unsigned long fd)
+{
+	struct files_struct *files = current->files;
+	struct socket *sock = NULL;
+	struct file *file;
+	struct sock *sk;
+	int err, n;
+
+	if (!files || fd > INT_MAX) {
+		scnprintf(buf, len, "fd%lu:?", fd);
+		return;
+	}
+	rcu_read_lock();
+	file = files_lookup_fd_rcu(files, (unsigned int)fd);
+	if (file)
+		sock = sock_from_file(file, &err);
+	sk = sock ? sock->sk : NULL;
+	if (!file) {
+		scnprintf(buf, len, "fd%lu:closed", fd);
+	} else if (!sk) {
+		scnprintf(buf, len, "fd%lu:%pD", fd, file);
+	} else {
+		n = scnprintf(buf, len,
+			      "fd%lu:sk fam%u type%u proto%u st%u err%d eq%u rq%u shut%#x",
+			      fd, sk->sk_family, sk->sk_type, sk->sk_protocol,
+			      sk->sk_state, READ_ONCE(sk->sk_err),
+			      skb_queue_len_lockless(&sk->sk_error_queue),
+			      skb_queue_len_lockless(&sk->sk_receive_queue),
+			      READ_ONCE(sk->sk_shutdown));
+		if ((sk->sk_family == AF_INET || sk->sk_family == AF_INET6) &&
+		    sk->sk_protocol == IPPROTO_UDP)
+			scnprintf(buf + n, len - n, " rdq%u port%u->%u recverr%u",
+				  skb_queue_len_lockless(&udp_sk(sk)->reader_queue),
+				  inet_sk(sk)->inet_num,
+				  ntohs(inet_sk(sk)->inet_dport),
+				  (unsigned int)inet_sk(sk)->recverr);
+	}
+	rcu_read_unlock();
