+	for (i = 0; i < SD_NR_SYS; i++) {
+		s = &sd_sys[i];
+		if (!s->hits) {
+			s->pid = p->pid;
+			s->nr = nr;
+			s->arg0 = arg0;
+			sd_sys_where(s, u);
+		} else if (s->pid != p->pid || s->nr != nr ||
+			   s->arg0 != arg0) {
