/* scheduling class by effective priority: I idle, D, F/R RT, C CFS */
static char sd_cls(const struct task_struct *p)
{
	if (is_idle_task(p))
		return 'I';
	if (dl_prio(p->prio))
		return 'D';
	if (rt_prio(p->prio))
		return p->policy == SCHED_FIFO ? 'F' : 'R';
	return 'C';
}

/* RT priority (1..99) of RT tasks, nice of the others */
static s8 sd_prio(const struct task_struct *p)
{
	if (rt_prio(p->prio) && !dl_prio(p->prio))
		return (s8)(MAX_RT_PRIO - 1 - p->prio);
	return (s8)PRIO_TO_NICE(p->static_prio);
}

static unsigned int sd_irq_pcnt(void)
{
