/* ------------------------------------------------------------------ */
/* syscall watch                                                      */
/* ------------------------------------------------------------------ */

static struct sd_watch *sd_watch_find(const struct task_struct *p)
{
	unsigned int i, n = READ_ONCE(sd_nwatch);

	for (i = 0; i < n; i++)
		if (sd_watch[i].task == p && sd_watch[i].pid == p->pid)
			return &sd_watch[i];
	return NULL;
}

/* IRQs disabled */
static void sd_watch_add(struct task_struct *p)
{
	unsigned int n = sd_nwatch;
	struct sd_watch *w;

	if (n >= SD_NR_WATCH || sd_watch_find(p))
		return;
	w = &sd_watch[n];
	memset(w, 0, sizeof(*w));
	w->task = p;
	w->pid = p->pid;
	w->tgid = p->tgid;
#ifdef TIF_SYSCALL_TRACEPOINT
	/* route the next syscalls of p through syscall_trace_enter/exit() */
	set_tsk_thread_flag(p, TIF_SYSCALL_TRACEPOINT);
#endif
	WRITE_ONCE(sd_nwatch, n + 1);
}

/* IRQs disabled */
static void sd_watch_rt_tasks(void)
{
	struct task_struct *g, *p;

	rcu_read_lock();
	for_each_process_thread(g, p) {
		if (p->mm && !(p->flags & PF_KTHREAD) &&
		    (rt_policy(p->policy) || dl_policy(p->policy)))
			sd_watch_add(p);
	}
	rcu_read_unlock();
}

