/* ------------------------------------------------------------------ */
/* starvation episodes and tick samples                               */
/* ------------------------------------------------------------------ */

static void sd_account_task(const struct task_struct *p, int user,
			    unsigned int pcnt)
{
	struct sd_task *t;
	int i;

	for (i = 0; i < SD_NR_TASKS; i++) {
		t = &sd_tasks[i];
		if (!t->hits) {
			t->pid = p->pid;
			t->tgid = p->tgid;
			t->cls = sd_cls(p);
			t->prio = sd_prio(p);
			memcpy(t->comm, p->comm, TASK_COMM_LEN);
			t->comm[TASK_COMM_LEN - 1] = '\0';
		} else if (t->pid != p->pid) {
			continue;
		}
		t->hits++;
		if (user)
			t->user++;
		if (pcnt)
			t->nonpreempt++;
		if (pcnt & SOFTIRQ_OFFSET)
			t->softirq++;
		return;
	}
	sd_tasks_other++;
}

static void sd_account_func(const struct task_struct *p, int user,
			    unsigned long pc)
{
	unsigned long key = pc, size, off;
	struct sd_func *f;
	int i;

	if (user)
		key = pc & ~0x3fUL;
	else if (kallsyms_lookup_size_offset(pc, &size, &off))
		key = pc - off;

	for (i = 0; i < SD_NR_FUNCS; i++) {
		f = &sd_funcs[i];
		if (!f->hits) {
			f->key = key;
			f->pid = p->pid;
			f->tgid = p->tgid;
			f->user = user;
		} else if (f->key != key || f->pid != p->pid ||
			   f->user != !!user) {
			continue;
		}
		f->hits++;
		return;
	}
	sd_funcs_other++;
}

static void sd_take_sample(u64 now, int user, unsigned long gap)
{
	struct pt_regs *regs = get_irq_regs();
	struct task_struct *p = current;
	unsigned int pcnt = sd_irq_pcnt();
	unsigned long pc = regs ? instruction_pointer(regs) : 0;
	struct sd_sample *s;

	if (gap > sd_max_gap)
		sd_max_gap = gap;
	sd_nsamples++;
	s = &sd_samples[sd_samples_head++ & (SD_NR_SAMPLES - 1)];
	s->ts = now;
	s->pc = pc;
	s->lr = regs ? sd_regs_lr(regs) : 0;
	s->pcnt = pcnt;
	s->pid = p->pid;
	s->tgid = p->tgid;
	s->user = user;
	sd_account_task(p, user, pcnt);
	sd_account_func(p, user, pc);
}

/* first episode of a stall: reset the stall statistics, watch RT tasks */
static void sd_stall_begin(u64 now)
{
	int cpu = smp_processor_id();
	int i, n = min_t(int, nr_irqs, SD_MAX_IRQS);

	sd_st_active = true;
	sd_st_episodes = 0;
	sd_st_onset = sd_ep_onset;
	sd_st_start = now;
	sd_st_switches0 = this_rq()->nr_switches;
	sd_st_cfs_slices = 0;
	memset(sd_st_cfs_rtpre, 0, sizeof(sd_st_cfs_rtpre));
	memset(sd_st_rt_run, 0, sizeof(sd_st_rt_run));
	sd_st_rt_sleeps = 0;
	sd_st_rt_preempted = 0;
	sd_nsamples = 0;
	sd_samples_head = 0;
	sd_funcs_other = 0;
	sd_tasks_other = 0;
	memset(sd_samples, 0, sizeof(sd_samples));
	memset(sd_funcs, 0, sizeof(sd_funcs));
	memset(sd_tasks, 0, sizeof(sd_tasks));
	for (i = 0; i < n; i++)
		sd_irq_snap[i] = kstat_irqs_cpu(i, cpu);
	for (i = 0; i < NR_SOFTIRQS; i++)
		sd_softirq_snap[i] = kstat_softirqs_cpu(i, cpu);
	sd_watch_reset(now);
	sd_watch_rt_tasks();
}

static void sd_episode_begin(unsigned long starve_j, unsigned long gap,
			     u64 now)
{
	u64 back = jiffies_to_nsecs(starve_j);

	sd_active = true;
	sd_episodes++;
	sd_ep_onset = now > back ? now - back : 0;
	sd_detect_gap = gap;
	sd_max_gap = 0;
	if (!sd_st_active)
		sd_stall_begin(now);
	sd_st_episodes++;
}

static void sd_lb_cpu_shares(const struct sd_agg *a)
{
	u64 total = sd_agg_total(a);

	sd_lb_pm("RT ", a->rt_us, total);
	sd_lb_pm(" CFS ", a->cfs_us, total);
	sd_lb_pm(" idle ", a->idle_us, total);
}

/* the GP kthread is active again */
static void sd_episode_end(unsigned long starve_j, u64 now)
{
	u64 back = now - min_t(u64, now, jiffies_to_nsecs(starve_j));
	const struct sd_agg_task *top;
	struct sd_agg *a = &sd_agg_b;
	struct sd_t on = sd_tms(sd_ep_onset);
	unsigned int i;

	sd_agg(a, sd_ep_onset, now);
	top = sd_agg_pick(a, NULL);
	sd_lb_reset();
	sd_lb("episode #%u ended: GP kthread starved %u ms from %lu.%03u (detect gap %lu, max tick gap %lu); CPU: ",
	      sd_episodes, sd_ms(back > sd_ep_onset ? back - sd_ep_onset : 0),
	      on.s, on.f, sd_detect_gap, sd_max_gap);
	if (top) {
		sd_lb("%d/%s ", top->pid, top->comm);
		sd_lb_cls(top->cls, top->prio);
		sd_lb_pm(" ", top->run_us, sd_agg_total(a));
		sd_lb(", ");
	}
	sd_lb_cpu_shares(a);
	for (i = 0; i < SD_NR_SK; i++)
		if (sd_sks[i].stuck)
			sd_lb("; udp :%u stuck for %u ms", sd_sks[i].lport,
			      sd_ms(now - sd_sks[i].since));
	sd_lb_flush('W');
	sd_active = false;
	sd_st_last_end = now;
	sd_skip_irq = true;
}

static void sd_stall_end(void)
{
	struct sd_t a = sd_tms(sd_st_onset), b = sd_tms(sd_st_last_end);

	pr_warn(SD "stall over: %u episode(s) between %lu.%03u and %lu.%03u; syscall watch stopped\n",
		sd_st_episodes, a.s, a.f, b.s, b.f);
	sd_st_active = false;
	WRITE_ONCE(sd_nwatch, 0);
	sd_skip_irq = true;
}

