static void sd_lb_sock(struct sock *sk)
{
	const struct inet_sock *inet;
	struct unix_address *addr;
	struct sock *peer;
	int len;

	switch (sk->sk_family) {
	case AF_INET:
	case AF_INET6:
		inet = inet_sk(sk);
		sd_lb("%s :%u", sk->sk_protocol == IPPROTO_UDP ? "udp" :
		      sk->sk_protocol == IPPROTO_TCP ? "tcp" : "inet",
		      inet->inet_num);
		if (sk->sk_family == AF_INET && inet->inet_dport)
			sd_lb(" -> %pI4:%u", &inet->inet_daddr,
			      ntohs(inet->inet_dport));
		sd_lb(" errq=%u sk_err=%d rq=%u",
		      skb_queue_len_lockless(&sk->sk_error_queue),
		      READ_ONCE(sk->sk_err),
		      skb_queue_len_lockless(&sk->sk_receive_queue));
		if (sk->sk_protocol == IPPROTO_UDP && sk->sk_type == SOCK_DGRAM)
			sd_lb("+%u", skb_queue_len_lockless(&udp_sk(sk)->reader_queue));
		if (sd_sk_want(sk))
			sd_lb(" recverr");
		break;
	case AF_UNIX:
		sd_lb("unix-%s", sk->sk_type == SOCK_DGRAM ? "dgram" :
		      sk->sk_type == SOCK_STREAM ? "stream" : "seqpacket");
		peer = READ_ONCE(unix_sk(sk)->peer);
		addr = peer ? READ_ONCE(unix_sk(peer)->addr) : NULL;
		len = addr ? addr->len - (int)offsetof(struct sockaddr_un, sun_path) : 0;
		if (len > 0 && addr->name->sun_path[0])
			sd_lb(" -> %.*s", len, addr->name->sun_path);
		else if (len > 1)
			sd_lb(" -> @%.*s", len - 1, addr->name->sun_path + 1);
		break;
	default:
		sd_lb("socket family %u type %u proto %u", sk->sk_family,
		      sk->sk_type, sk->sk_protocol);
		break;
	}
	if (sock_flag(sk, SOCK_DEAD))
		sd_lb(" closed");
}

/* "fd N: <what>" for file descriptor fd of thread pid */
static void sd_lb_fd(pid_t pid, unsigned long fd)
{
	struct files_struct *files;
	struct task_struct *p;
	struct socket *sock;
	struct file *file;
	int err;

	rcu_read_lock();
	p = find_task_by_pid_ns(pid, &init_pid_ns);
	files = p ? READ_ONCE(p->files) : NULL;
	file = files && fd < INT_MAX ?
		files_lookup_fd_rcu(files, (unsigned int)fd) : NULL;
	sd_lb("fd %lu: ", fd);
	if (!file) {
		sd_lb("-");
	} else {
		sock = sock_from_file(file, &err);
		if (sock && sock->sk)
			sd_lb_sock(sock->sk);
		else
			sd_lb("%pD", file);
	}
	rcu_read_unlock();
}

/* fd of sk in the file table of task pid, -1 if not found */
static int sd_sk_fd(pid_t pid, const struct sock *sk)
{
	struct files_struct *files;
	struct task_struct *p;
	struct fdtable *fdt;
	struct socket *sock;
	struct file *file;
	unsigned int fd;
	int ret = -1, err;

	if (pid <= 0)
		return -1;
	rcu_read_lock();
	p = find_task_by_pid_ns(pid, &init_pid_ns);
	files = p ? READ_ONCE(p->files) : NULL;
	if (files) {
		fdt = files_fdtable(files);
		for (fd = 0; fd < fdt->max_fds && fd < 4096; fd++) {
			file = rcu_dereference_raw(fdt->fd[fd]);
			if (!file)
				continue;
			sock = sock_from_file(file, &err);
			if (sock && sock->sk == sk) {
				ret = fd;
				break;
			}
		}
	}
	rcu_read_unlock();
	return ret;
}

static void sd_lb_errinfo(const struct sd_sev *e)
{
	switch (e->origin) {
	case SO_EE_ORIGIN_LOCAL:
		sd_lb("LOCAL");
		break;
	case SO_EE_ORIGIN_ICMP:
		sd_lb("ICMP %u/%u", e->itype, e->icode);
		break;
	case SO_EE_ORIGIN_ICMP6:
		sd_lb("ICMP6 %u/%u", e->itype, e->icode);
		break;
	default:
		sd_lb("origin %u", e->origin);
		break;
	}
	sd_lb(" errno %d", e->err);
	if (e->from)
		sd_lb(" from %pI4", &e->from);
	if (e->daddr || e->dport)
		sd_lb(" for %pI4:%u", &e->daddr, e->dport);
}

static void sd_lb_take(const struct sd_sev *e)
{
	sd_lb("%s() returned errno %d",
	      e->how < ARRAY_SIZE(sd_take_name) ? sd_take_name[e->how] : "?",
	      e->err);
}

/* best socket for the summary: stuck now (most hits), else longest stuck */
static struct sd_sk *sd_sk_worst(void)
{
	struct sd_sk *t, *best = NULL;
	unsigned int i;

	for (i = 0; i < SD_NR_SK; i++) {
		t = &sd_sks[i];
		if (!t->sk || (!t->stuck && !t->n_long))
			continue;
		if (!best || (t->stuck && !best->stuck))
			best = t;
		else if (t->stuck && best->stuck &&
			 t->n_poll + t->n_eagain > best->n_poll + best->n_eagain)
			best = t;
		else if (!t->stuck && !best->stuck &&
			 t->max_stuck_ns > best->max_stuck_ns)
			best = t;
	}
	return best;
}

/* most frequent syscall entry (of pid, if not 0) not printed yet */
static const struct sd_sys *sd_sys_pick(pid_t pid)
{
	int i, best = -1;

	for (i = 0; i < SD_NR_SYS; i++) {
		if (!sd_sys[i].n || sd_used_sys[i] ||
		    (pid && sd_sys[i].pid != pid))
			continue;
		if (best < 0 || sd_sys[i].n > sd_sys[best].n)
			best = i;
	}
	if (best < 0)
		return NULL;
	sd_used_sys[best] = true;
	return &sd_sys[best];
}

static void sd_lb_sys_ret(const struct sd_sys *s)
{
	sd_lb(" =");
	if (s->ok)
		sd_lb_pm(" ok ", s->ok, s->n);
	if (s->eagain)
		sd_lb_pm(" EAGAIN ", s->eagain, s->n);
	if (s->eintr)
		sd_lb_pm(" EINTR ", s->eintr, s->n);
	if (s->err) {
		sd_lb_pm(" error ", s->err, s->n);
		sd_lb(" (last %d)", s->last_err);
	}
	sd_lb(" avg %u us",
	      (u32)div64_u64(s->sum_ns, (u64)s->n * NSEC_PER_USEC));
}

static void sd_print_rcu_readers(struct rq *rq)
{
#ifdef CONFIG_PREEMPT_RCU
	struct task_struct *g, *p;
	int n = 0;

	sd_lb("SUMMARY: RCU readers preempted inside rcu_read_lock() (they block the grace period):");
	rcu_read_lock();
	for_each_process_thread(g, p) {
		if (!READ_ONCE(p->rcu_read_unlock_special.b.blocked))
			continue;
		if (n++ >= 4)
			continue;
		sd_lb(" %d/%s ", p->pid, p->comm);
		sd_lb_cls(sd_cls(p), sd_prio(p));
