static void sd_print_summary(struct task_struct *gpk, struct rq *rq, u64 now,
			     unsigned long gps, const struct sd_agg_task *hog)
{
	const struct sd_agg *a = &sd_agg_a;
	u64 total = sd_agg_total(a), span = a->nb ? a->t1 - a->t0 : 0;
	unsigned int i, k, pm_rt, pm_lim;
	const struct sd_sys *s;
	struct sd_sk *w;
	struct sd_sev h;
	struct sd_t t;
	int fd;

	sd_lb_reset();
	sd_lb("SUMMARY: ");
	if (gps) {
		u64 gp = jiffies_to_nsecs(jiffies - gps);

		t = sd_tms(now > gp ? now - gp : 0);
		sd_lb("RCU grace period pending for %u ms (since %lu.%03u)",
		      sd_ms(gp), t.s, t.f);
	} else {
		sd_lb("no RCU stall reported yet");
	}
	if (gpk)
		sd_lb("; GP kthread %d/%s state %c, no activity for %u ms",
		      gpk->pid, gpk->comm, task_state_to_char(gpk),
		      jiffies_to_msecs(sd_starve_j));
	if (sd_st_active) {
		t = sd_tms(sd_st_onset);
		sd_lb("; starving since %lu.%03u, %u episode(s)", t.s, t.f,
		      sd_st_episodes);
	}
	sd_lb_flush('E');

	sd_print_rcu_readers(rq);

	t = sd_tms(a->t0);
	sd_lb("SUMMARY: CPU during %u ms from %lu.%03u: ", sd_ms(span), t.s,
	      t.f);
	if (hog) {
		sd_lb("%d/%s ", hog->pid, hog->comm);
		sd_lb_cls(hog->cls, hog->prio);
		sd_lb_pm(" ", hog->run_us, total);
		sd_lb(" | ");
	}
	sd_lb_cpu_shares(a);
	sd_lb(" | GP kthread ran %llu us", a->gpk_us);
	sd_lb_flush('E');

	if (hog) {
		sd_lb("SUMMARY: %d/%s ran %u times/s for %u us each and went to sleep %u times/s",
		      hog->pid, hog->comm, sd_rate(hog->runs, span),
		      hog->runs ? hog->run_us / hog->runs : 0,
		      sd_rate(hog->sleeps, span));
		if (sd_st_active && sd_st_cfs_slices) {
			u64 pre = 0, fast = 0;

			for (i = 0; i < SD_NR_LOG2; i++) {
				pre += sd_st_cfs_rtpre[i];
				if (i < 2)
					fast += sd_st_cfs_rtpre[i];
			}
