			pm_rt = sd_pm(a->rt_us, total);
			pm_lim = sd_pm(sysctl_sched_rt_runtime,
				       sysctl_sched_rt_period);
			sd_lb("; RT throttling %s: RT %u.%u%% %s limit %u.%u%%",
			      rq->rt.rt_throttled ? "ACTIVE" : "inactive",
			      pm_rt / 10, pm_rt % 10, pm_rt < pm_lim ? "<" : ">=",
			      pm_lim / 10, pm_lim % 10);
		}
		sd_lb_flush('E');
	}

