		sd_lb("SUMMARY: %d/%s syscalls/s:", hog->pid, hog->comm);
		memset(sd_used_sys, 0, sizeof(sd_used_sys));
		for (k = 0; k < 5; k++) {
			s = sd_sys_pick(hog->pid);
			if (!s)
				break;
			sd_lb(" ");
			sd_lb_sysname(s->nr);
			if (sd_sys_has_fd(s->nr))
				sd_lb("(fd %lu)", s->a0);
			sd_lb(" %u", sd_rate(s->n, now - sd_watch_since));
			sd_lb_sys_ret(s);
			sd_lb(";");
