	fd = sd_sk_fd(w->tgid, w->sk);
	sd_lb("SUMMARY: udp :%u", w->lport);
	if (fd >= 0)
		sd_lb(" (fd %d of %d/%s)", fd, w->pid, w->comm);
	if (w->stuck) {
