		t = sd_tus(w->since);
		sd_lb(" STUCK for %u ms since %lu.%06u: errq=%u sk_err=%d, poll() POLLERR %u/s, recv() -EAGAIN %u/s",
		      sd_ms(d), t.s, t.f,
		      skb_queue_len_lockless(&w->sk->sk_error_queue),
		      READ_ONCE(w->sk->sk_err), sd_rate(w->n_poll, d),
		      sd_rate(w->n_eagain, d));
	} else {
