		      sd_ms(w->max_stuck_ns));
	}
	sd_lb_flush('E');

	sd_lb("SUMMARY: udp :%u", w->lport);
	if (w->stuck && skb_queue_len_lockless(&w->sk->sk_error_queue)) {
		memset(&h, 0, sizeof(h));
		sd_sev_errq_head(&h, w->sk);
		sd_lb(" stale entry: ");
		sd_lb_errinfo(&h);
		sd_lb(";");
	}
	if (w->last_take.ts) {
		t = sd_tus(w->last_take.ts);
		sd_lb(" sk_err last taken at %lu.%06u by %d/%s: ", t.s, t.f,
		      w->last_take.pid, w->last_take.comm);
		sd_lb_take(&w->last_take);
		sd_lb(", %u entr%s left queued;", w->last_take.errq,
		      w->last_take.errq == 1 ? "y" : "ies");
	}
	if (w->last_deq.ts) {
		t = sd_tus(w->last_deq.ts);
		sd_lb(" last MSG_ERRQUEUE read at %lu.%06u by %d/%s", t.s, t.f,
		      w->last_deq.pid, w->last_deq.comm);
	} else {
		sd_lb(" no MSG_ERRQUEUE read seen");
	}
	sd_lb_flush('E');

	if (hog && w->stuck && hog->cls != 'C' &&
	    (w->s_pid == hog->pid || w->pid == hog->pid)) {
		sd_lb("SUMMARY: => RT task %d/%s loops on udp :%u: poll() returns at once because of an error queue entry nobody reads, recv() returns -EAGAIN, its sleeps are microseconds; CFS tasks incl. the RCU GP kthread get no useful CPU",
		      hog->pid, hog->comm, w->lport);
		sd_lb_flush('E');
	}
}

static void sd_print_window(struct rq *rq, u64 now)
{
	const struct sd_agg *a = &sd_agg_a;
	u64 total = sd_agg_total(a), span = a->nb ? a->t1 - a->t0 : 0;
	u64 top_us = 0, busy = a->rt_us + a->cfs_us;
	const struct sd_agg_task *x;
	bool used[SD_AGG_TASKS];
	struct sd_t t0 = sd_tms(a->t0), t1 = sd_tms(a->t1);
	u64 rt_runtime = rq->rt.rt_runtime;
	unsigned int k;
	u32 pre = 0;

	memset(used, 0, sizeof(used));
	pr_info(SD "[1] CPU %lu.%03u..%lu.%03u (%u ms in %u buckets of 100 ms): %llu context switches (%u/s), %llu hard IRQs (%u/s), GP kthread ran %llu us in %u buckets\n",
		t0.s, t0.f, t1.s, t1.f, sd_ms(span), a->nb, a->sw,
		sd_rate(a->sw, span), a->irqs, sd_rate(a->irqs, span),
		a->gpk_us, a->gpk_nb);
	sd_lb("    ");
	sd_lb_cpu_shares(a);
	sd_lb("; per task (sum of the top 4 of each 100 ms; n: switched in, s: went to sleep):");
	sd_lb_flush('I');
	for (k = 0; k < 10; k++) {
		x = sd_agg_pick(a, used);
		if (!x)
			break;
		top_us += x->run_us;
		sd_lb("    %5d/%-15s ", x->pid, x->comm);
		sd_lb_cls(x->cls, x->prio);
		sd_lb_pm(" ", x->run_us, total);
		sd_lb(" n %u (%u/s, %u us each) s %u (%u/s)", x->runs,
		      sd_rate(x->runs, span), x->runs ? x->run_us / x->runs : 0,
		      x->sleeps, sd_rate(x->sleeps, span));
		sd_lb_flush('I');
	}
	if (busy > top_us) {
		sd_lb_pm("    all other tasks ", busy - top_us, total);
		sd_lb_flush('I');
	}
	if (sd_st_active) {
		for (k = 0; k < SD_NR_LOG2; k++)
			pre += sd_st_cfs_rtpre[k];
		t0 = sd_tms(sd_st_start);
		sd_lb("    since %lu.%03u: CFS slices %u, %u ended by RT preemption after:",
		      t0.s, t0.f, sd_st_cfs_slices, pre);
		sd_lb_hist(sd_st_cfs_rtpre);
		sd_lb_flush('I');
		sd_lb("    since %lu.%03u: RT runs %u (%u slept, %u preempted), length:",
		      t0.s, t0.f, sd_st_rt_sleeps + sd_st_rt_preempted,
		      sd_st_rt_sleeps, sd_st_rt_preempted);
		sd_lb_hist(sd_st_rt_run);
		sd_lb_flush('I');
	}
	sd_lb("    runqueue: %u tasks (CFS %u, RT %u), rt_throttled=%d rt_time=%llu us rt_runtime=%lld us, sched_rt_runtime/period=%d/%u us, %llu switches since boot",
	      rq->nr_running, rq->cfs.h_nr_running, rq->rt.rt_nr_running,
	      rq->rt.rt_throttled, div_u64(rq->rt.rt_time, NSEC_PER_USEC),
	      rt_runtime == RUNTIME_INF ? -1LL :
			(s64)div_u64(rt_runtime, NSEC_PER_USEC),
	      sysctl_sched_rt_runtime, sysctl_sched_rt_period,
	      rq->nr_switches);
	sd_lb_flush('I');
}

static void sd_print_sys(u64 now)
{
	u64 span = now - sd_watch_since;
	struct sd_t t = sd_tms(sd_watch_since);
	const struct sd_sys *s;
	unsigned int k;

	if (!sd_sys_used) {
		pr_info(SD "[3] syscalls: none recorded (%u task(s) watched)\n",
			READ_ONCE(sd_nwatch));
		return;
	}
	pr_info(SD "[3] syscalls of %u watched RT task(s) since %lu.%03u (%u ms), most frequent first; time <10us/<100us/<1ms/>=1ms\n",
		READ_ONCE(sd_nwatch), t.s, t.f, sd_ms(span));
	memset(sd_used_sys, 0, sizeof(sd_used_sys));
	for (k = 0; k < 20; k++) {
		s = sd_sys_pick(0);
		if (!s)
			break;
		sd_lb("    %d ", s->pid);
		sd_lb_sysname(s->nr);
		if (sd_sys_has_fd(s->nr))
			sd_lb("(fd %lu)", s->a0);
		sd_lb(" x%u %u/s", s->n, sd_rate(s->n, span));
		sd_lb_sys_ret(s);
		sd_lb(" max %u us | time %u/%u/%u/%u", s->max_us, s->dur[0],
		      s->dur[1], s->dur[2], s->dur[3]);
#ifdef CONFIG_ARM
		if (s->nr == 168)	/* poll */
			sd_lb(" | nfds %lu timeout %ld", s->a1, (long)s->a2);
#endif
		if (s->req_us)
			sd_lb(" | sleep request %u us", s->req_us);
		sd_lb_flush('I');
		if (!sd_sys_has_fd(s->nr) && !s->site.pc)
			continue;
		sd_lb("       ");
		if (sd_sys_has_fd(s->nr)) {
			sd_lb_fd(s->pid, s->a0);
			sd_lb(" |");
		}
		sd_umm_get(s->tgid);
		sd_lb_usite(&s->site);
		sd_lb_flush('I');
	}
	sd_umm_put();
	if (sd_sys_lost)
		pr_info(SD "    (%u calls not recorded: table full)\n",
			sd_sys_lost);
}

static void sd_print_sev(const struct sd_sev *e)
{
	struct sd_t t = sd_tus(e->ts);

	sd_lb("    [%5lu.%06u] #%u :%u %-7s ", t.s, t.f, e->slot, e->lport,
	      e->type < ARRAY_SIZE(sd_sev_name) ? sd_sev_name[e->type] : "?");
	switch (e->type) {
	case SEV_ENQ:
	case SEV_NOMEM:
	case SEV_DEQ:
		sd_lb_errinfo(e);
		sd_lb(" -> errq %u sk_err %u", e->errq, e->sk_err);
		break;
	case SEV_TAKE:
		sd_lb_take(e);
		sd_lb(" -> errq %u sk_err %u%s", e->errq, e->sk_err,
		      e->errq ? " (entries left: POLLERR stays until MSG_ERRQUEUE)" : "");
		break;
	case SEV_STUCK:
		sd_lb("%s with errq %u sk_err %u, entry: ",
		      e->how ? "recv -EAGAIN" : "poll POLLERR", e->errq,
		      e->sk_err);
		sd_lb_errinfo(e);
		break;
	case SEV_UNSTUCK:
		sd_lb("after %u ms: POLLERR x%u, recv -EAGAIN x%u",
		      sd_ms(e->dur), e->n_poll, e->n_eagain);
		break;
	}
	if (e->task) {
		sd_lb(" by %d/%s", e->pid, e->comm);
		sd_umm_get(e->tgid);
		sd_lb_usite(&e->site);
	} else if (e->type == SEV_ENQ || e->type == SEV_NOMEM) {
		sd_lb(" (softirq)");
	}
	sd_lb_flush('I');
}

static void sd_print_socks(u64 now, unsigned int max_events)
{
	unsigned int i, k, n, nsel = 0, sel = 0;
	const struct sd_sev *e;
	struct sd_sev h;
	struct sd_sk *t;
	struct sd_t ts;
	int fd;

	pr_info(SD "[4] UDP sockets with IP_RECVERR. POLLERR stays set while the error queue (errq) is not empty, also with sk_err=0; recv() then returns -EAGAIN until recvmsg(MSG_ERRQUEUE) removes the entry\n");
	for (i = 0; i < SD_NR_SK; i++) {
		t = &sd_sks[i];
		if (!t->sk)
			continue;
		if (!t->stuck && !t->n_long &&
		    (nsel >= 4 || now - t->last_ns > 30 * NSEC_PER_SEC))
			continue;
		sel |= 1U << i;
		nsel++;
		fd = sd_sk_fd(t->tgid, t->sk);
		sd_lb("    #%u ", i);
		sd_lb_sock(t->sk);
		if (fd >= 0)
			sd_lb(" | fd %d of %d/%s", fd, t->pid, t->comm);
		else if (t->pid)
			sd_lb(" | last used by %d/%s", t->pid, t->comm);
		sd_lb_flush('I');
		sd_lb("       queued %u (dropped %u), MSG_ERRQUEUE reads %u | sk_err taken by recv %u send %u SO_ERROR %u, %u of them left entries queued | POLLERR/EAGAIN with stale errq %u/%u | stuck periods %u short %u long, longest %u ms",
		      t->enq, t->nomem, t->deq, t->take[SD_TAKE_RECV],
		      t->take[SD_TAKE_SEND], t->take[SD_TAKE_SOERR], t->take_q,
		      t->obs_poll, t->obs_eagain, t->n_short, t->n_long,
		      sd_ms(t->max_stuck_ns));
		sd_lb_flush('I');
		if (t->stuck) {
			ts = sd_tus(t->since);
			sd_lb("       STUCK for %u ms since %lu.%06u: POLLERR x%u (%u/s), recv -EAGAIN x%u (%u/s), first seen by %d/%s",
			      sd_ms(now - t->since), ts.s, ts.f, t->n_poll,
			      sd_rate(t->n_poll, now - t->since), t->n_eagain,
			      sd_rate(t->n_eagain, now - t->since), t->s_pid,
			      t->s_comm);
			sd_umm_get(t->s_tgid);
			sd_lb_usite(&t->s_site);
			sd_lb_flush('I');
		}
		if (skb_queue_len_lockless(&t->sk->sk_error_queue)) {
			memset(&h, 0, sizeof(h));
			sd_sev_errq_head(&h, t->sk);
			sd_lb("       first queued entry: ");
			sd_lb_errinfo(&h);
			sd_lb_flush('I');
		}
	}
	if (!sel) {
		pr_info(SD "    none tracked\n");
		return;
	}

	/* last @max_events events of the sockets shown, oldest first */
	n = min_t(unsigned int, sd_sev_head, SD_NR_SEV);
	for (i = 1, k = 0; i <= n && k < max_events; i++) {
		e = &sd_sev[(sd_sev_head - i) & (SD_NR_SEV - 1)];
		if (sel & (1U << e->slot))
			k++;
	}
	pr_info(SD "    last %u error queue events of these sockets (#slot :port):\n",
		k);
	for (i = i - 1; i > 0; i--) {
		e = &sd_sev[(sd_sev_head - i) & (SD_NR_SEV - 1)];
		if (sel & (1U << e->slot))
			sd_print_sev(e);
	}
	sd_umm_put();
}

/* one line of CPU history from an aggregate */
static void sd_print_agg_line(const struct sd_agg *a, bool fine)
{
	const struct sd_agg_task *x;
	bool used[SD_AGG_TASKS];
	u64 total = sd_agg_total(a);
	struct sd_t t = sd_tms(a->t0);
	unsigned int k;

	memset(used, 0, sizeof(used));
	if (fine)
		sd_lb("  %5lu.%03u", t.s, t.f);
	else
		sd_lb("  %5lu", t.s);
	sd_lb(" sw %5llu irq %5llu | ", a->sw, a->irqs);
	sd_lb_cpu_shares(a);
	sd_lb(" gpk %llu us", a->gpk_us);
	for (k = 0; k < 3; k++) {
		x = sd_agg_pick(a, used);
		if (!x)
			break;
		sd_lb(" | %d/%s ", x->pid, x->comm);
		sd_lb_cls(x->cls, x->prio);
		sd_lb_pm(" ", x->run_us, total);
		sd_lb(" n%u s%u", x->runs, x->sleeps);
	}
	sd_lb_flush('I');
}

/* one line per second of [from, to) */
static void sd_print_secs(u64 from, u64 to)
{
	u64 s;
	u32 rem;

	div_u64_rem(from, NSEC_PER_SEC, &rem);
	for (s = from - rem; s < to; s += NSEC_PER_SEC) {
		sd_agg(&sd_agg_b, s, s + NSEC_PER_SEC);
		if (sd_agg_b.nb)
			sd_print_agg_line(&sd_agg_b, false);
	}
}

/* one line per 100 ms bucket of [from, to) */
static void sd_print_fine(u64 from, u64 to)
{
	unsigned int i, n = sd_hb_count();
	const struct sd_hb *b;

	for (i = 0; i < n; i++) {
		b = sd_hb_at(i);
		if (!b->t0 || b->t0 + SD_HB_NS <= from || b->t0 >= to)
			continue;
		memset(&sd_agg_b, 0, sizeof(sd_agg_b));
		sd_agg_bucket(&sd_agg_b, b);
		sd_print_agg_line(&sd_agg_b, true);
	}
}

static void sd_print_task(const char *tag, struct task_struct *p,
			  struct rq *rq)
{
	char cls = sd_cls(p);

	sd_lb("    %s %d(%d)/%s ", tag, p->pid, p->tgid, p->comm);
	sd_lb_cls(cls, sd_prio(p));
	sd_lb(" %c on_rq=%d ran %lld ms ago, exec %llu ms, csw %lu/%lu",
	      task_state_to_char(p), p->on_rq,
	      div_s64((s64)(rq->clock_task - p->se.exec_start), NSEC_PER_MSEC),
	      div_u64(p->se.sum_exec_runtime, NSEC_PER_MSEC),
	      p->nvcsw, p->nivcsw);
	if (cls == 'C')
		sd_lb(" vrun%+lld us",
		      div_s64((s64)(p->se.vruntime - rq->cfs.min_vruntime),
			      NSEC_PER_USEC));
#ifdef CONFIG_PREEMPT_RCU
	if (READ_ONCE(p->rcu_read_unlock_special.b.blocked))
		sd_lb(" [preempted RCU reader: blocks the grace period]");
	else if (READ_ONCE(p->rcu_read_lock_nesting) > 0)
		sd_lb(" [inside rcu_read_lock()]");
#endif
	sd_lb_flush('I');
}

static void sd_print_gpk(struct task_struct *gpk, struct rq *rq)
{
	struct task_struct *lt = NULL, *ct = NULL;
	struct sched_entity *se, *left = NULL;
	const struct sd_gpkrun *g;
	struct rb_node *nd;
	bool found = false;
	unsigned int i;
	struct sd_t t;
	int cnt = 0;

	pr_info(SD "[7] RCU GP kthread\n");
	if (!gpk) {
		pr_info(SD "    unknown\n");
		return;
	}
	sd_print_task("gpk", gpk, rq);
	nd = rb_first_cached(&rq->cfs.tasks_timeline);
	if (nd)
		left = rb_entry(nd, struct sched_entity, run_node);
	for (; nd && cnt < 1024; nd = rb_next(nd), cnt++)
		if (rb_entry(nd, struct sched_entity, run_node) == &gpk->se)
			found = true;
	if (left && entity_is_task(left))
		lt = container_of(left, struct task_struct, se);
	se = rq->cfs.curr;
	if (se && entity_is_task(se))
		ct = container_of(se, struct task_struct, se);
	sd_lb("    CFS runqueue: %u tasks, %d in the tree, GP kthread %s; current %d/%s, leftmost %d/%s vrun%+lld us",
	      rq->cfs.nr_running, cnt, found ? "in the tree" : "NOT in the tree",
	      ct ? ct->pid : -1, ct ? ct->comm : "-",
	      lt ? lt->pid : -1, lt ? lt->comm : "-",
	      left ? div_s64((s64)(left->vruntime - rq->cfs.min_vruntime),
			     NSEC_PER_USEC) : 0LL);
	sd_lb_flush('I');
	pr_info(SD "    its last runs (oldest first):\n");
	for (i = SD_NR_GPKRUN; i > 0; i--) {
		g = &sd_gpkrun[(sd_gpkrun_head - i) & (SD_NR_GPKRUN - 1)];
		if (!g->in)
			continue;
		t = sd_tus(g->in);
		sd_lb("    [%5lu.%06u] ran %u us, left %s, next %d/%s", t.s,
		      t.f, sd_us(g->out - g->in),
		      g->how == 'R' ? "preempted" : "to sleep",
		      g->next_pid, g->next_comm);
		sd_lb_flush('I');
	}
	if (sd_gpk_in) {
		t = sd_tus(sd_gpk_in);
		pr_info(SD "    on the CPU since [%5lu.%06u]\n", t.s, t.f);
	}
}

static void sd_print_samples(void)
{
	bool used[SD_NR_FUNCS];
	const struct sd_sample *s;
	const struct sd_task *t;
	const struct sd_func *f;
	unsigned int i, k, n;
	struct sd_t ts;
	int best;

	pr_info(SD "[8] tick samples while starving: %u (user: in user space, nonpreempt: preemption/BH disabled)\n",
		sd_nsamples);
	memset(used, 0, sizeof(used));
	for (k = 0; k < SD_NR_TASKS; k++) {
		best = -1;
		for (i = 0; i < SD_NR_TASKS; i++)
			if (sd_tasks[i].hits && !used[i] &&
			    (best < 0 || sd_tasks[i].hits > sd_tasks[best].hits))
				best = i;
		if (best < 0)
			break;
		used[best] = true;
		t = &sd_tasks[best];
		sd_lb("    %d(%d)/%s ", t->pid, t->tgid, t->comm);
		sd_lb_cls(t->cls, t->prio);
		sd_lb(": %u ticks, user %u, nonpreempt %u, softirq %u",
		      t->hits, t->user, t->nonpreempt, t->softirq);
		sd_lb_flush('I');
	}
	if (sd_tasks_other)
		pr_info(SD "    other tasks: %u ticks\n", sd_tasks_other);

	memset(used, 0, sizeof(used));
	for (k = 0; k < 16; k++) {
		best = -1;
		for (i = 0; i < SD_NR_FUNCS; i++)
			if (sd_funcs[i].hits && !used[i] &&
			    (best < 0 || sd_funcs[i].hits > sd_funcs[best].hits))
				best = i;
		if (best < 0)
			break;
		used[best] = true;
		f = &sd_funcs[best];
		if (!f->user) {
			sd_lb("    %u ticks pid %d %pS", f->hits, f->pid,
			      (void *)f->key);
		} else {
			sd_umm_get(f->tgid);
			sd_lb("    %u ticks pid %d user ", f->hits, f->pid);
			sd_lb_uaddr(f->key);
			sd_lb(" (64 bytes)");
		}
		sd_lb_flush('I');
	}
	if (sd_funcs_other)
		pr_info(SD "    other code: %u ticks\n", sd_funcs_other);

	n = min_t(unsigned int, sd_nsamples, SD_NR_SAMPLES);
	n = min_t(unsigned int, n, 12);
	for (i = n; i > 0; i--) {
		s = &sd_samples[(sd_samples_head - i) & (SD_NR_SAMPLES - 1)];
		ts = sd_tms(s->ts);
		if (s->user) {
			sd_umm_get(s->tgid);
			sd_lb("    [%5lu.%03u] %d user pc ", ts.s, ts.f, s->pid);
			sd_lb_uaddr(s->pc);
			sd_lb(" lr ");
			sd_lb_uaddr(s->lr);
		} else {
			sd_lb("    [%5lu.%03u] %d kernel pc %pS lr %pS pcnt %#x",
			      ts.s, ts.f, s->pid, (void *)s->pc, (void *)s->lr,
			      s->pcnt);
		}
		sd_lb_flush('I');
	}
	sd_umm_put();
}

static void sd_print_irqs(u64 now)
{
	int cpu = smp_processor_id();
	int i, n = min_t(int, nr_irqs, SD_MAX_IRQS);
	struct task_struct *ks = per_cpu(ksoftirqd, cpu);
	u64 span = now - sd_st_start;
	const struct sd_longirq *l;
	struct irqaction *action;
	struct irq_desc *desc;
	unsigned int d;
	struct sd_t t;

	if (sd_st_active) {
		sd_lb("[9] IRQs/s since detection (%u ms):", sd_ms(span));
		for (i = 0; i < n; i++) {
			d = kstat_irqs_cpu(i, cpu) - sd_irq_snap[i];
			if (!d)
				continue;
			desc = irq_to_desc(i);
			action = desc ? READ_ONCE(desc->action) : NULL;
			sd_lb(" %s(%d) %u", action && action->name ?
			      action->name : "?", i, sd_rate(d, span));
		}
		sd_lb_flush('I');
		sd_lb("    softirqs/s:");
		for (i = 0; i < NR_SOFTIRQS; i++) {
			d = kstat_softirqs_cpu(i, cpu) - sd_softirq_snap[i];
			if (d)
				sd_lb(" %s %u", softirq_to_name[i],
				      sd_rate(d, span));
		}
		sd_lb(", pending %#x", (unsigned int)local_softirq_pending());
		if (ks)
			sd_lb(", ksoftirqd %c ran %lld ms ago",
			      task_state_to_char(ks),
			      div_s64((s64)(this_rq()->clock_task -
					    ks->se.exec_start), NSEC_PER_MSEC));
		sd_lb_flush('I');
	} else {
		pr_info(SD "[9] IRQs: no stall active\n");
	}
	if (!sd_irq_max.dur) {
		pr_info(SD "    no hard IRQ handler ran 2 ms or longer since boot\n");
		return;
	}
	t = sd_tus(sd_irq_max.ts);
	pr_info(SD "    longest hard IRQ handler since boot: irq %u %ps %llu us at %lu.%06u\n",
		sd_irq_max.irq, sd_irq_max.handler,
		div_u64(sd_irq_max.dur, NSEC_PER_USEC), t.s, t.f);
	for (i = SD_NR_LONGIRQ; i > 0; i--) {
		l = &sd_longirq[(sd_longirq_head - i) & (SD_NR_LONGIRQ - 1)];
		if (!l->ts)
			continue;
		t = sd_tus(l->ts);
		pr_info(SD "    hard IRQ >= 2 ms: irq %u %ps %llu us at %lu.%06u\n",
			l->irq, l->handler, div_u64(l->dur, NSEC_PER_USEC),
			t.s, t.f);
	}
}

static void sd_print_switches(unsigned int nmax)
{
	const struct sd_switch *s;
	unsigned int i;
	struct sd_t t;

	pr_info(SD "[10] last %u context switches (oldest first; R: preempted, S/D/I: went to sleep):\n",
		nmax);
	for (i = nmax; i > 0; i--) {
		s = &sd_sw[(sd_sw_head - i) & (SD_NR_SWITCH - 1)];
		if (!s->ts)
			continue;
		t = sd_tus(s->ts);
		sd_lb("    [%5lu.%06u] %d/%s ", t.s, t.f, s->prev_pid,
		      s->prev_comm);
		sd_lb_cls(s->prev_cls, s->prev_prio);
		sd_lb(" %c -> %d/%s ", s->prev_state, s->next_pid, s->next_comm);
		sd_lb_cls(s->next_cls, s->next_prio);
		sd_lb_flush('I');
	}
}

static void sd_print_tasks(struct rq *rq, bool full)
{
	struct task_struct *g, *p, *cur = current;
	int max_run = full ? 16 : 12, max_ran = full ? 12 : 0;
	int nrun = 0, nran = 0, hidden = 0;
	u64 now = rq->clock_task;

	pr_info(SD "[11] runnable tasks%s:\n",
		full ? ", then tasks that ran in the last 2 s" : "");
	rcu_read_lock();
	for_each_process_thread(g, p) {
		if (!task_on_rq_queued(p) && p != cur)
			continue;
		if (nrun++ >= max_run) {
			hidden++;
			continue;
		}
		sd_print_task("run", p, rq);
	}
	for_each_process_thread(g, p) {
		if (task_on_rq_queued(p) || p == cur)
			continue;
		if (!p->se.exec_start || now - p->se.exec_start > 2 * NSEC_PER_SEC)
			continue;
		if (nran++ >= max_ran) {
			hidden++;
			continue;
		}
		sd_print_task("ran", p, rq);
	}
	rcu_read_unlock();
	if (hidden)
		pr_info(SD "    (%d more not shown)\n", hidden);
}

static void sd_print_rt_tasks(void)
{
	struct task_struct *g, *p;
	int n = 0;

	sd_lb("    RT tasks:");
	rcu_read_lock();
	for_each_process_thread(g, p) {
		if (!rt_policy(p->policy) && !dl_policy(p->policy))
			continue;
		sd_lb(" %d/%s/%c%u", p->pid, p->comm,
		      p->policy == SCHED_FIFO ? 'F' :
		      p->policy == SCHED_RR ? 'R' : 'D', p->rt_priority);
		if (sd_llen > 400)
			sd_lb_flush('I');
		if (++n >= 128)
			break;
	}
	rcu_read_unlock();
	if (sd_llen)
		sd_lb_flush('I');
}

static void sd_print_stack(pid_t pid)
{
	struct task_struct *p;

	if (pid <= 0)
		return;
	rcu_read_lock();
	p = find_task_by_pid_ns(pid, &init_pid_ns);
	if (p && p != current) {
		pr_info(SD "    kernel stack of %d/%s:\n", p->pid, p->comm);
		sched_show_task(p);
	}
	rcu_read_unlock();
}

