 /* ------------------------------------------------------------------ */
 /* helpers                                                            */
 /* ------------------------------------------------------------------ */

 struct sd_t {
 	unsigned long	s;
 	unsigned int	f;
 };

 /* seconds and milliseconds of a local_clock() value */
 static struct sd_t sd_tms(u64 ns)
 {
 	struct sd_t t;
 	u32 rem;

 	t.s = (unsigned long)div_u64_rem(ns, NSEC_PER_SEC, &rem);
 	t.f = rem / NSEC_PER_MSEC;
 	return t;
 }

 /* seconds and microseconds of a local_clock() value */
 static struct sd_t sd_tus(u64 ns)
 {
 	struct sd_t t;
 	u32 rem;

 	t.s = (unsigned long)div_u64_rem(ns, NSEC_PER_SEC, &rem);
 	t.f = rem / NSEC_PER_USEC;
 	return t;
 }

 static u32 sd_ms(u64 ns)
 {
 	return (u32)div_u64(ns, NSEC_PER_MSEC);
 }

 static u32 sd_us(u64 ns)
 {
 	return (u32)div_u64(ns, NSEC_PER_USEC);
 }

 /* events per second */
 static u32 sd_rate(u64 n, u64 ns)
 {
 	if (!ns)
 		return 0;
 	return (u32)div64_u64(n * NSEC_PER_SEC, ns);
 }

 /* part of total, per mille */
 static unsigned int sd_pm(u64 part, u64 total)
 {
 	if (!total)
 		return 0;
 	if (part > total)
 		part = total;
 	return (unsigned int)div64_u64(part * 1000, total);
 }

 static u8 sd_clip8(unsigned int v)
 {
 	return v > U8_MAX ? U8_MAX : v;
 }

 /* log2 length class: <8us, <16us, ... <2ms, >=2ms */
 static unsigned int sd_lb2(u64 ns)
 {
 	u64 lim = 8 * NSEC_PER_USEC;
 	unsigned int i;

 	for (i = 0; i < SD_NR_LOG2 - 1; i++, lim <<= 1)
 		if (ns < lim)
 			return i;
 	return SD_NR_LOG2 - 1;
 }

 /* scheduling class by effective priority: I idle, D, F/R RT, C CFS */
 static char sd_cls(const struct task_struct *p)
 {
 	if (is_idle_task(p))
 		return 'I';
 	if (dl_prio(p->prio))
 		return 'D';
 	if (rt_prio(p->prio))
 		return p->policy == SCHED_FIFO ? 'F' : 'R';
 	return 'C';
 }

 /* RT priority (1..99) of RT tasks, nice of the others */
 static s8 sd_prio(const struct task_struct *p)
 {
 	if (rt_prio(p->prio) && !dl_prio(p->prio))
 		return (s8)(MAX_RT_PRIO - 1 - p->prio);
 	return (s8)PRIO_TO_NICE(p->static_prio);
 }

 static unsigned int sd_irq_pcnt(void)
 {
 	unsigned int pcnt = preempt_count();

 	/* drop the HARDIRQ_OFFSET of the tick itself */
 	if (pcnt & HARDIRQ_MASK)
 		pcnt -= HARDIRQ_OFFSET;
 	return pcnt;
 }

