 /* line buffer, report context only */
 static void sd_lb_reset(void)
 {
 	sd_llen = 0;
 	sd_lbuf[0] = '\0';
 }

 static __printf(1, 2) void sd_lb(const char *fmt, ...)
 {
 	va_list ap;

 	va_start(ap, fmt);
 	sd_llen += vscnprintf(sd_lbuf + sd_llen, sizeof(sd_lbuf) - sd_llen,
 			      fmt, ap);
