 /*
  * Resolve user addresses of process @tgid as <file>+0x<offset>.  Report
  * context only: interrupts are disabled on this UP system, so the process
  * cannot exit meanwhile; mmap_read_trylock() keeps the VMAs stable.  No mm
  * reference is taken because mmput() must not run with IRQs disabled.
  */
 static void sd_umm_put(void)
 {
 	if (sd_umm)
 		mmap_read_unlock(sd_umm);
 	sd_umm = NULL;
 	sd_umm_tgid = 0;
 }

 static void sd_umm_get(pid_t tgid)
 {
 	struct task_struct *p;
 	struct mm_struct *mm = NULL;

 	if (tgid == sd_umm_tgid)
 		return;
 	sd_umm_put();
 	sd_umm_tgid = tgid;
 	if (tgid <= 0)
 		return;
 	rcu_read_lock();
 	p = find_task_by_pid_ns(tgid, &init_pid_ns);
 	if (p && !(p->flags & PF_KTHREAD))
 		mm = READ_ONCE(p->mm);
 	if (mm && !mmap_read_trylock(mm))
 		mm = NULL;
 	rcu_read_unlock();
 	sd_umm = mm;
 }

 static void sd_lb_uaddr(unsigned long addr)
 {
 	struct vm_area_struct *vma;

 	if (!addr) {
 		sd_lb("-");
 		return;
 	}
 	if (sd_umm) {
 		vma = find_vma(sd_umm, addr);
 		if (vma && vma->vm_start <= addr && vma->vm_file) {
 			sd_lb("%pD+0x%lx", vma->vm_file, addr - vma->vm_start +
 			      (vma->vm_pgoff << PAGE_SHIFT));
 			return;
 		}
 	}
 	sd_lb("0x%08lx", addr);
 }

 /* " in <function> <- <caller>", or " pc <pc> lr <lr>" without a frame */
 static void sd_lb_usite(const struct sd_usite *u)
 {
 	if (u->fn) {
 		sd_lb(" in ");
 		sd_lb_uaddr(u->fn);
 		sd_lb(" <- ");
 		sd_lb_uaddr(u->ra);
 	} else if (u->pc) {
 		sd_lb(" pc ");
 		sd_lb_uaddr(u->pc);
 		sd_lb(" lr ");
 		sd_lb_uaddr(u->lr);
 	}
 }

 /*
  * User call site of current, which must have entered the kernel from user
  * space (process context).  ms is built with APCS frames: fp points at the
  * saved pc of the innermost ms function and fp-4 holds its saved lr.  libc
  * below usually leaves fp alone; values outside the main executable's text
  * are dropped, so a reused fp cannot produce bogus call sites.
  */
 static void sd_usite_get(struct sd_usite *u)
 {
 	struct mm_struct *mm = current->mm;
 	struct pt_regs *regs;
 #ifdef CONFIG_ARM
 	unsigned long fr[2];
 #endif

 	memset(u, 0, sizeof(*u));
 	if (!mm || (current->flags & PF_KTHREAD) || !in_task())
 		return;
 	regs = task_pt_regs(current);
 	u->pc = instruction_pointer(regs);
 #ifdef CONFIG_ARM
 	u->lr = regs->ARM_lr;
 	if (regs->ARM_fp >= 4 && !(regs->ARM_fp & 3) &&
 	    !copy_from_user_nofault(fr, (const void __user *)(regs->ARM_fp - 4),
 				    sizeof(fr)) &&
 	    fr[1] >= mm->start_code && fr[1] < mm->end_code) {
 		u->fn = fr[1];
 		if (fr[0] >= mm->start_code && fr[0] < mm->end_code)
 			u->ra = fr[0];
 	}
 #endif
 }

