 static unsigned int sd_hb_count(void)
 {
 	return sd_hb_head < SD_NR_HB ? sd_hb_head : SD_NR_HB;
 }

 /* i-th oldest closed bucket */
 static const struct sd_hb *sd_hb_at(unsigned int i)
 {
 	return &sd_hb[(sd_hb_head - sd_hb_count() + i) % SD_NR_HB];
 }

 /* entry of p in the open bucket; NULL if the table is full */
 static struct sd_wt *sd_wt_get(const struct task_struct *p)
 {
 	u8 *slot = &sd_pidx[p->pid & (SD_NR_PIDX - 1)];
 	unsigned int i = *slot;
 	struct sd_wt *e;

 	if (i < sd_wt_n && sd_wt[i].pid == p->pid)
 		goto found;
 	for (i = 0; i < sd_wt_n; i++)
 		if (sd_wt[i].pid == p->pid)
 			goto found;
 	if (sd_wt_n >= SD_NR_WT)
 		return NULL;
 	i = sd_wt_n++;
 	e = &sd_wt[i];
 	e->pid = p->pid;
 	e->run_ns = 0;
 	e->runs = 0;
 	e->sleeps = 0;
 	memcpy(e->comm, p->comm, TASK_COMM_LEN);
 	e->comm[TASK_COMM_LEN - 1] = '\0';
 found:
 	*slot = i;
 	e = &sd_wt[i];
 	e->cls = sd_cls(p);
 	e->prio = sd_prio(p);
 	return e;
 }

 /* p ran for @delta ns inside the open bucket */
 static void sd_charge(const struct task_struct *p, u64 delta)
 {
 	struct sd_wt *e;
 	u32 d;

 	if (!delta)
 		return;
 	d = delta > SD_HB_NS ? (u32)SD_HB_NS : (u32)delta;
 	switch (sd_cls(p)) {
 	case 'I':
 		sd_open.idle_ns += d;
 		break;
 	case 'C':
 		sd_open.cfs_ns += d;
 		break;
 	default:
 		sd_open.rt_ns += d;
 		break;
 	}
 	if (p == sd_gpk)
 		sd_open.gpk_ns += d;
 	e = sd_wt_get(p);
 	if (e)
 		e->run_ns += d;
 }

 /* close the open bucket [sd_hb_end - SD_HB_NS, sd_hb_end) */
 static void sd_hb_close(void)
 {
 	struct sd_hb *b = &sd_hb[sd_hb_head % SD_NR_HB];
 	unsigned long irqs = kstat_cpu_irqs_sum(smp_processor_id());
 	unsigned int i, k;
 	int best;

 	b->t0 = sd_hb_end - SD_HB_NS;
 	b->sw = sd_open.sw;
 	b->irqs = (u32)(irqs - sd_open.irqs0);
 	b->rt_us = sd_open.rt_ns / NSEC_PER_USEC;
 	b->cfs_us = sd_open.cfs_ns / NSEC_PER_USEC;
 	b->idle_us = sd_open.idle_ns / NSEC_PER_USEC;
 	b->gpk_us = sd_open.gpk_ns / NSEC_PER_USEC;
 	b->ntasks = sd_wt_n;
 	b->ntop = 0;
 	for (k = 0; k < SD_HB_TOP; k++) {
 		best = -1;
 		for (i = 0; i < sd_wt_n; i++) {
 			if (sd_wt[i].pid < 0 || sd_wt[i].cls == 'I' ||
 			    !sd_wt[i].run_ns)
 				continue;
 			if (best < 0 || sd_wt[i].run_ns > sd_wt[best].run_ns)
 				best = i;
 		}
 		if (best < 0)
 			break;
 		b->top[k].pid = sd_wt[best].pid;
 		b->top[k].run_us = sd_wt[best].run_ns / NSEC_PER_USEC;
 		b->top[k].runs = sd_wt[best].runs;
 		b->top[k].sleeps = sd_wt[best].sleeps;
 		b->top[k].cls = sd_wt[best].cls;
 		b->top[k].prio = sd_wt[best].prio;
 		memcpy(b->top[k].comm, sd_wt[best].comm, TASK_COMM_LEN);
 		b->ntop++;
 		sd_wt[best].pid = -1;		/* taken */
 	}
 	sd_hb_head++;

 	memset(&sd_open, 0, sizeof(sd_open));
 	sd_open.irqs0 = irqs;
 	sd_wt_n = 0;
 }

 /* @running has been on the CPU since sd_acct_ts: account up to @now */
 static void sd_acct(u64 now, const struct task_struct *running)
 {
 	u32 rem;

 	if (unlikely(!sd_hb_end)) {
 		div_u64_rem(now, (u32)SD_HB_NS, &rem);
 		sd_hb_end = now - rem + SD_HB_NS;
 		sd_acct_ts = now;
 		sd_open.irqs0 = kstat_cpu_irqs_sum(smp_processor_id());
 		return;
 	}
 	if (unlikely(now <= sd_acct_ts))
 		return;
 	if (unlikely(now >= sd_hb_end + (u64)SD_NR_HB * SD_HB_NS)) {
 		/* very long gap (NO_HZ idle): close the open bucket, skip ahead */
 		sd_charge(running, sd_hb_end - sd_acct_ts);
 		sd_hb_close();
 		div_u64_rem(now, (u32)SD_HB_NS, &rem);
 		sd_hb_end = now - rem + SD_HB_NS;
 		sd_acct_ts = sd_hb_end - SD_HB_NS;
 	}
 	while (now >= sd_hb_end) {
 		sd_charge(running, sd_hb_end - sd_acct_ts);
 		sd_acct_ts = sd_hb_end;
 		sd_hb_close();
 		sd_hb_end += SD_HB_NS;
 	}
 	sd_charge(running, now - sd_acct_ts);
 	sd_acct_ts = now;
 }

 static void sd_agg_task_add(struct sd_agg *a, const struct sd_hb_task *t)
 {
 	struct sd_agg_task *x;
 	unsigned int i;

 	for (i = 0; i < a->nt; i++)
 		if (a->t[i].pid == t->pid)
 			break;
 	if (i == a->nt) {
 		if (a->nt >= SD_AGG_TASKS) {
 			a->rest_us += t->run_us;
 			return;
 		}
 		a->nt++;
 		x = &a->t[i];
 		memset(x, 0, sizeof(*x));
 		x->pid = t->pid;
 		memcpy(x->comm, t->comm, TASK_COMM_LEN);
 	}
 	x = &a->t[i];
 	x->run_us += t->run_us;
 	x->runs += t->runs;
 	x->sleeps += t->sleeps;
 	x->cls = t->cls;
 	x->prio = t->prio;
 }

 static void sd_agg_bucket(struct sd_agg *a, const struct sd_hb *b)
 {
 	unsigned int k;

 	if (!a->nb)
 		a->t0 = b->t0;
 	a->t1 = b->t0 + SD_HB_NS;
 	a->nb++;
 	a->sw += b->sw;
 	a->irqs += b->irqs;
 	a->rt_us += b->rt_us;
 	a->cfs_us += b->cfs_us;
 	a->idle_us += b->idle_us;
 	a->gpk_us += b->gpk_us;
 	if (b->gpk_us)
 		a->gpk_nb++;
 	for (k = 0; k < b->ntop; k++)
 		sd_agg_task_add(a, &b->top[k]);
 }

 /* merge the closed buckets that overlap [from, to) */
 static void sd_agg(struct sd_agg *a, u64 from, u64 to)
 {
 	unsigned int i, n = sd_hb_count();
 	const struct sd_hb *b;

 	memset(a, 0, sizeof(*a));
 	for (i = 0; i < n; i++) {
 		b = sd_hb_at(i);
 		if (!b->t0 || b->t0 + SD_HB_NS <= from || b->t0 >= to)
 			continue;
 		sd_agg_bucket(a, b);
 	}
 }

 static u64 sd_agg_total(const struct sd_agg *a)
 {
 	return a->rt_us + a->cfs_us + a->idle_us;
 }

 /* busiest task not yet in @used (may be NULL), marks it used */
 static const struct sd_agg_task *sd_agg_pick(const struct sd_agg *a,
 					     bool *used)
 {
 	int i, best = -1;

 	for (i = 0; i < a->nt; i++) {
 		if ((used && used[i]) || a->t[i].cls == 'I')
 			continue;
 		if (best < 0 || a->t[i].run_us > a->t[best].run_us)
 			best = i;
 	}
 	if (best < 0)
 		return NULL;
 	if (used)
 		used[best] = true;
 	return &a->t[best];
 }

