 /* Called from __schedule() with the rq lock held and IRQs disabled. */
 void notrace starve_dbg_switch(bool preempt, struct task_struct *prev,
 			       struct task_struct *next)
 {
 	struct sd_switch *s;
 	struct sd_wt *e;
 	char pcls, ncls;
 	bool sleep;
 	u64 now, ran;

 	if (!READ_ONCE(sd_enable))
 		return;
 	now = local_clock();
 	ran = sd_last_sw && now > sd_last_sw ? now - sd_last_sw : 0;
 	pcls = sd_cls(prev);
 	ncls = sd_cls(next);
 	sleep = !preempt && pcls != 'I' && !task_on_rq_queued(prev);

 	sd_acct(now, prev);
 	sd_open.sw++;
 	e = sd_wt_get(prev);
 	if (e && sleep && e->sleeps < U16_MAX)
 		e->sleeps++;
 	e = sd_wt_get(next);
 	if (e && e->runs < U16_MAX)
 		e->runs++;

 	if (sd_st_active) {
 		if (pcls == 'C') {
 			sd_st_cfs_slices++;
 			if (preempt && ncls != 'C' && ncls != 'I')
 				sd_st_cfs_rtpre[sd_lb2(ran)]++;
 		} else if (pcls != 'I') {
 			sd_st_rt_run[sd_lb2(ran)]++;
 			if (sleep)
 				sd_st_rt_sleeps++;
 			else
 				sd_st_rt_preempted++;
 		}
 	}

 	s = &sd_sw[sd_sw_head++ & (SD_NR_SWITCH - 1)];
 	s->ts = now;
 	s->prev_pid = prev->pid;
 	s->next_pid = next->pid;
 	s->prev_cls = pcls;
 	s->next_cls = ncls;
 	s->prev_prio = sd_prio(prev);
 	s->next_prio = sd_prio(next);
 	s->prev_state = preempt ? 'R' : task_state_to_char(prev);
 	s->preempt = preempt;
 	memcpy(s->prev_comm, prev->comm, TASK_COMM_LEN);
 	memcpy(s->next_comm, next->comm, TASK_COMM_LEN);
 	s->prev_comm[TASK_COMM_LEN - 1] = '\0';
 	s->next_comm[TASK_COMM_LEN - 1] = '\0';

 	if (prev == sd_gpk && sd_gpk_in) {
 		struct sd_gpkrun *g =
 			&sd_gpkrun[sd_gpkrun_head++ & (SD_NR_GPKRUN - 1)];

 		g->in = sd_gpk_in;
 		g->out = now;
 		g->how = s->prev_state;
 		g->next_pid = next->pid;
 		memcpy(g->next_comm, s->next_comm, TASK_COMM_LEN);
 		sd_gpk_in = 0;
 	}
 	if (next == sd_gpk)
 		sd_gpk_in = now;
 	sd_last_sw = now;
 }

 /* Called from __handle_irq_event_percpu() after each action handler. */
 void notrace starve_dbg_irq(unsigned int irq, void *handler, u64 t0)
 {
 	struct sd_longirq *l;
 	u64 dur;

 	/* this handler printed a report: its duration is ours, not the driver's */
 	if (unlikely(sd_skip_irq)) {
 		sd_skip_irq = false;
 		return;
 	}
 	dur = local_clock() - t0;
 	if (likely(dur < SD_LONGIRQ_NS))
 		return;

 	l = &sd_longirq[sd_longirq_head++ & (SD_NR_LONGIRQ - 1)];
 	l->ts = t0;
 	l->dur = dur;
 	l->handler = handler;
 	l->irq = irq;
 	if (dur > sd_irq_max.dur)
 		sd_irq_max = *l;
 }

