 static bool sd_sk_want(const struct sock *sk)
 {
 	if (sk->sk_type != SOCK_DGRAM || sk->sk_protocol != IPPROTO_UDP ||
 	    (sk->sk_family != AF_INET && sk->sk_family != AF_INET6) ||
 	    !inet_sk(sk)->inet_num)
 		return false;
 	if (inet_sk(sk)->recverr)
 		return true;
 #if IS_ENABLED(CONFIG_IPV6)
 	if (sk->sk_family == AF_INET6) {
 		const struct ipv6_pinfo *np = inet6_sk(sk);

 		return np && np->recverr;
 	}
 #endif
 	return false;
 }

 /* event from a task that entered the kernel from user space */
 static void sd_sev_task(struct sd_sev *e)
 {
 	if (!in_task() || !current->mm || (current->flags & PF_KTHREAD))
 		return;
 	e->task = true;
 	e->pid = current->pid;
 	e->tgid = current->tgid;
 	memcpy(e->comm, current->comm, TASK_COMM_LEN);
 	e->comm[TASK_COMM_LEN - 1] = '\0';
 	sd_usite_get(&e->site);
 }

 /* origin, type/code, errno and addresses of an error queue skb */
 static void sd_sev_skb(struct sd_sev *e, const struct sock *sk,
 		       const struct sk_buff *skb)
 {
 	const struct sock_exterr_skb *serr = SKB_EXT_ERR(skb);

 	e->origin = serr->ee.ee_origin;
 	e->itype = serr->ee.ee_type;
 	e->icode = serr->ee.ee_code;
 	e->err = (s16)serr->ee.ee_errno;
 	if (sk->sk_family == AF_INET &&
 	    (e->origin == SO_EE_ORIGIN_ICMP || e->origin == SO_EE_ORIGIN_LOCAL)) {
 		if (e->origin == SO_EE_ORIGIN_ICMP)
 			e->from = ip_hdr(skb)->saddr;
 		memcpy(&e->daddr, skb_network_header(skb) + serr->addr_offset,
 		       sizeof(e->daddr));
 		e->dport = ntohs(serr->port);
 	}
 }

 /* first entry of the error queue, IRQs disabled */
 static void sd_sev_errq_head(struct sd_sev *e, struct sock *sk)
 {
 	struct sk_buff_head *q = &sk->sk_error_queue;
 	struct sk_buff *skb;

 	spin_lock(&q->lock);
 	skb = skb_peek(q);
 	if (skb)
 		sd_sev_skb(e, sk, skb);
 	spin_unlock(&q->lock);
 }

 static void sd_sev_push(const struct sd_sev *e)
 {
 	sd_sev[sd_sev_head++ & (SD_NR_SEV - 1)] = *e;
 }

 static struct sd_sk *sd_sk_find(const struct sock *sk)
 {
 	unsigned int i;

 	for (i = 0; i < SD_NR_SK; i++)
 		if (sd_sks[i].sk == sk)
 			return &sd_sks[i];
 	return NULL;
 }

 /*
  * Slot of sk, IRQs disabled.  A new slot takes a reference on sk.  The socket
  * of a reused slot is returned in *put; the caller releases it with
  * sock_put() after re-enabling interrupts.
  */
 static struct sd_sk *sd_sk_get(struct sock *sk, struct sock **put)
 {
 	struct sd_sk *t = sd_sk_find(sk), *v = NULL;
 	unsigned int i;

 	if (t)
 		return t;
 	for (i = 0; i < SD_NR_SK; i++) {
 		t = &sd_sks[i];
 		if (!t->sk) {
 			v = t;
 			break;
 		}
 		if (!t->stuck && (!v || t->last_ns < v->last_ns))
 			v = t;
 	}
 	if (!v || !refcount_inc_not_zero(&sk->sk_refcnt))
 		return NULL;
 	*put = v->sk;
 	memset(v, 0, sizeof(*v));
 	v->sk = sk;
 	v->lport = inet_sk(sk)->inet_num;
 	v->family = sk->sk_family;
 	return v;
 }

 /* remember the task using the socket, IRQs disabled */
 static void sd_sk_user(struct sd_sk *t)
 {
 	if (!in_task() || !current->mm || (current->flags & PF_KTHREAD))
 		return;

