 /* enqueue (ret 0) or drop (ret -ENOMEM) of an error queue entry */
 void starve_dbg_errq_enq(struct sock *sk, const struct sk_buff *skb, int ret)
 {
 	struct sock *put = NULL;
 	unsigned long flags;
 	struct sd_sev e;
 	struct sd_sk *t;

 	if (!READ_ONCE(sd_enable) || !sd_sk_want(sk))
 		return;
 	memset(&e, 0, sizeof(e));
 	e.type = ret ? SEV_NOMEM : SEV_ENQ;
 	e.lport = inet_sk(sk)->inet_num;
 	sd_sev_skb(&e, sk, skb);
 	sd_sev_task(&e);
 	local_irq_save(flags);
 	e.ts = local_clock();
 	t = sd_sk_get(sk, &put);
 	if (t) {
 		e.slot = t - sd_sks;
 		sd_sk_unstuck(t, e.ts);
 		if (ret)
 			t->nomem++;
 		else
 			t->enq++;
 		e.errq = sd_clip8(skb_queue_len_lockless(&sk->sk_error_queue) +
 				  (ret ? 0 : 1));
 		/* the ICMP error handlers set sk_err right after queueing */
 		if (e.origin == SO_EE_ORIGIN_ICMP ||
 		    e.origin == SO_EE_ORIGIN_ICMP6)
 			e.sk_err = sd_clip8(e.err);
 		else
 			e.sk_err = sd_clip8(READ_ONCE(sk->sk_err));
 		t->last_ns = e.ts;
 		if (e.task)
 			sd_sk_user(t);
 		sd_sev_push(&e);
 		t->last_enq = e;
 	}
 	local_irq_restore(flags);
 	if (put)
 		sock_put(put);
 }

 /* recvmsg(MSG_ERRQUEUE) dequeued skb */
 void starve_dbg_errq_deq(struct sock *sk, const struct sk_buff *skb)
 {
 	struct sock *put = NULL;
 	unsigned long flags;
 	struct sd_sev e;
 	struct sd_sk *t;

 	if (!READ_ONCE(sd_enable) || !sd_sk_want(sk))
 		return;
 	memset(&e, 0, sizeof(e));
 	e.type = SEV_DEQ;
 	e.lport = inet_sk(sk)->inet_num;
 	sd_sev_skb(&e, sk, skb);
 	sd_sev_task(&e);
 	local_irq_save(flags);
 	e.ts = local_clock();
 	t = sd_sk_get(sk, &put);
 	if (t) {
 		e.slot = t - sd_sks;
 		sd_sk_unstuck(t, e.ts);
 		t->deq++;
 		e.errq = sd_clip8(skb_queue_len_lockless(&sk->sk_error_queue));
 		e.sk_err = sd_clip8(READ_ONCE(sk->sk_err));
 		t->last_ns = e.ts;
 		sd_sk_user(t);
 		sd_sev_push(&e);
 		t->last_deq = e;
 	}
 	local_irq_restore(flags);
 	if (put)
 		sock_put(put);
 }

 /* sk_err (errno @err) was just consumed by recv/send/SO_ERROR */
 void starve_dbg_sk_take(struct sock *sk, int err, enum starve_dbg_take how)
 {
 	struct sock *put = NULL;
 	unsigned long flags;
 	struct sd_sev e;
 	struct sd_sk *t;

 	if (!READ_ONCE(sd_enable) || !sd_sk_want(sk))
 		return;
 	memset(&e, 0, sizeof(e));
 	e.type = SEV_TAKE;
 	e.how = how;
 	e.err = err;
 	e.lport = inet_sk(sk)->inet_num;
 	sd_sev_task(&e);
 	local_irq_save(flags);
 	e.ts = local_clock();
 	t = sd_sk_get(sk, &put);
 	if (t) {
 		e.slot = t - sd_sks;
 		sd_sk_unstuck(t, e.ts);
 		if (how <= SD_TAKE_SOERR)
 			t->take[how]++;
 		e.errq = sd_clip8(skb_queue_len_lockless(&sk->sk_error_queue));
 		e.sk_err = sd_clip8(READ_ONCE(sk->sk_err));
 		if (e.errq)
 			t->take_q++;
 		t->last_ns = e.ts;
 		sd_sk_user(t);
 		sd_sev_push(&e);
 		t->last_take = e;
 	}
 	local_irq_restore(flags);
 	if (put)
 		sock_put(put);
 }

 /* from the tick: one line when a socket stays stuck for 1 s */
 static void sd_sk_tick(u64 now)
 {
 	struct sd_sk *t;
 	struct sd_t ts;
 	unsigned int i;

 	for (i = 0; i < SD_NR_SK; i++) {
 		t = &sd_sks[i];
 		if (!t->stuck || t->warned || now - t->since < SD_STUCK_WARN_NS)
 			continue;
 		t->warned = true;
 		ts = sd_tus(t->since);
 		pr_warn(SD "socket #%u udp :%u stuck since %5lu.%06u (%u ms): errq=%u sk_err=0, POLLERR x%u, recv -EAGAIN x%u, first seen by %d/%s\n",
 			i, t->lport, ts.s, ts.f, sd_ms(now - t->since),
 			skb_queue_len_lockless(&t->sk->sk_error_queue),
 			t->n_poll, t->n_eagain, t->s_pid, t->s_comm);
 		sd_skip_irq = true;
 	}
 }

