 /*
  * Interrupts must be disabled: called from the tick, from the RCU stall code
  * (both hard IRQ) or from the "dump" parameter.  @gps: jiffies at the start
  * of the stalled grace period, 0 if none.
  */
 static void sd_report(struct task_struct *gpk, const char *why, bool full,
 		      unsigned long gps)
 {
 	struct rq *rq = this_rq();
 	time64_t wall = ktime_get_real_seconds();
 	const struct sd_agg_task *hog;
 	u64 now = local_clock(), win0 = 0, last, on, from, to;
 	struct sd_t t = sd_tms(now);
 	pid_t hog_pid;

 	/* window: the stalled grace period, else the stall, else 3 s */
 	if (gps) {
 		u64 gp = jiffies_to_nsecs(jiffies - gps);

 		win0 = now > gp ? now - gp : 1;
 	}
 	if (sd_st_active && (!win0 || sd_st_onset < win0))
 		win0 = sd_st_onset;
 	if (!win0)
 		win0 = now - min_t(u64, now, 3ULL * NSEC_PER_SEC);
 	sd_agg(&sd_agg_a, win0, now);
 	hog = sd_agg_pick(&sd_agg_a, NULL);
 	hog_pid = hog ? hog->pid : 0;

 	sd_lb_reset();
 	sd_umm_put();
 	pr_err(SD "======== %s report at %ptT UTC, uptime %lu.%03u ========\n",
 	       why, &wall, t.s, t.f);
 	sd_print_summary(gpk, rq, now, gps, hog);
 	last = now - min_t(u64, now, NSEC_PER_SEC);

 	if (!full) {
 		pr_info(SD "[5] CPU per 100 ms, last 3 s (n: switched in, s: went to sleep):\n");
 		sd_print_fine(now - min_t(u64, now, 3ULL * NSEC_PER_SEC), now);
 		sd_print_socks(now, 16);
 		sd_print_switches(32);
 		sd_print_tasks(rq, false);
 		goto out;
 	}

 	sd_print_window(rq, now);
 	sd_print_sys(now);
 	sd_print_socks(now, 40);
 	pr_info(SD "[4] CPU per second, last 60 s (n: switched in, s: went to sleep):\n");
 	sd_print_secs(now - min_t(u64, now, 60ULL * NSEC_PER_SEC), now);
 	from = last;
 	if (sd_st_active) {
 		on = sd_st_onset;
 		to = min_t(u64, on + NSEC_PER_SEC, last);
 		t = sd_tms(on);
 		pr_info(SD "[5] CPU per 100 ms around the starvation onset at %lu.%03u:\n",
 			t.s, t.f);
 		sd_print_fine(on - min_t(u64, on, 2ULL * NSEC_PER_SEC), to);
 		from = to;
 	}
 	pr_info(SD "[5] CPU per 100 ms, last second:\n");
 	sd_print_fine(from, now);
 	sd_print_gpk(gpk, rq);
 	sd_print_samples();
 	sd_print_irqs(now);
 	sd_print_switches(48);
 	sd_print_tasks(rq, true);
 	sd_print_rt_tasks();
 	sd_print_stack(hog_pid);
 out:
 	sd_umm_put();
 	pr_err(SD "======== end of %s report ========\n", why);
 	sd_skip_irq = true;
 }

