 /* ARM EABI syscalls whose first argument is a file descriptor */
 static bool sd_sys_has_fd(int nr)
 {
 #ifdef CONFIG_ARM
 	switch (nr) {
 	case 3: case 4: case 6: case 19: case 54: case 55: case 118:
 	case 140: case 145: case 146: case 148: case 180: case 181:
 	case 197: case 221: case 251: case 252: case 282: case 283:
 	case 285: case 286: case 287: case 289: case 290: case 291:
 	case 292: case 293: case 294: case 295: case 296: case 297:
 	case 346: case 365: case 366: case 374: case 417:
 		return true;
 	}
 #endif
 	return false;
 }

 static u32 sd_ts_to_us(s64 sec, s64 nsec)
 {
 	if (sec < 0 || nsec < 0 || nsec >= NSEC_PER_SEC)
 		return 0;
 	if (sec >= 4000)
 		return U32_MAX;
 	return (u32)sec * USEC_PER_SEC + (u32)nsec / NSEC_PER_USEC;
 }

 /* relative sleep requested by a nanosleep-type syscall in us, 0: none */
 static u32 sd_sleep_req_us(int nr, struct pt_regs *regs)
 {
 #ifdef CONFIG_ARM
 	struct { s32 sec; s32 nsec; } t32;
 	struct { s64 sec; s64 nsec; } t64;
 	const void __user *u;

 	switch (nr) {
 	case 162:		/* nanosleep(old_timespec32 *) */
 		u = (const void __user *)regs->ARM_r0;
 		break;
 	case 265:		/* clock_nanosleep(clk, flags, old_timespec32 *) */
 	case 407:		/* clock_nanosleep_time64(clk, flags, timespec64 *) */
 		if (regs->ARM_r1 & TIMER_ABSTIME)
 			return 0;
 		u = (const void __user *)regs->ARM_r2;
 		break;
 	default:
 		return 0;
 	}
 	if (nr == 407) {
 		if (copy_from_user_nofault(&t64, u, sizeof(t64)))
 			return 0;
 		return sd_ts_to_us(t64.sec, t64.nsec);
 	}
 	if (copy_from_user_nofault(&t32, u, sizeof(t32)))
 		return 0;
 	return sd_ts_to_us(t32.sec, t32.nsec);
 #else
 	return 0;
 #endif
 }

 static struct sd_sys *sd_sys_slot(const struct sd_watch *w, unsigned long a0)
 {
 	unsigned int h, i;
 	struct sd_sys *s;

 	h = (unsigned int)w->pid * 31 + (unsigned int)w->in_nr * 7 +
 	    (unsigned int)a0 * 13 + (unsigned int)(w->in_site.fn >> 2);
 	for (i = 0; i < SD_NR_SYS; i++) {
 		s = &sd_sys[(h + i) & (SD_NR_SYS - 1)];
 		if (!s->n) {
 			if (sd_sys_used >= SD_SYS_FILL)
 				return NULL;
 			sd_sys_used++;
 			memset(s, 0, sizeof(*s));
 			s->pid = w->pid;
 			s->tgid = w->tgid;
 			s->nr = w->in_nr;
 			s->a0 = a0;
 			s->site = w->in_site;
 			return s;
 		}
 		if (s->pid == w->pid && s->nr == w->in_nr && s->a0 == a0 &&
 		    s->site.fn == w->in_site.fn)
 			return s;
 	}
 	return NULL;
 }

 /* IRQs disabled */
 static void sd_sys_account(const struct sd_watch *w, long ret, u64 dur)
 {
 	unsigned long a0 = sd_sys_has_fd(w->in_nr) ? w->in_a0 : 0;
 	struct sd_sys *s = sd_sys_slot(w, a0);
 	u32 us;

 	if (!s) {
 		sd_sys_lost++;
 		return;
 	}
 	s->n++;
 	if (ret >= 0) {
 		s->ok++;
 	} else if (ret == -EAGAIN) {
 		s->eagain++;
 	} else if (ret == -EINTR) {
 		s->eintr++;
 	} else {
 		s->err++;
 		s->last_err = (int)-ret;
 	}
 	us = sd_us(dur);
 	s->dur[us < 10 ? 0 : us < 100 ? 1 : us < 1000 ? 2 : 3]++;
 	if (us > s->max_us)
 		s->max_us = us;
 	s->sum_ns += dur;
 	s->a1 = w->in_a1;
 	s->a2 = w->in_a2;
 	s->req_us = w->in_req_us;
 }

 /* Called from syscall_trace_enter() once the syscall number is final. */
 void starve_dbg_sys_enter(struct pt_regs *regs, int scno)
 {
 	struct sd_usite site;
 	struct sd_watch *w;
 	unsigned long flags;
 	u32 req;

 	if (likely(!READ_ONCE(sd_nwatch)) || !sd_watch_find(current))
 		return;
 	sd_usite_get(&site);
 	req = sd_sleep_req_us(scno, regs);
 	local_irq_save(flags);
 	w = sd_watch_find(current);
 	if (w) {
 		w->in_nr = scno;
 #ifdef CONFIG_ARM
 		w->in_a0 = regs->ARM_r0;
 		w->in_a1 = regs->ARM_r1;
 		w->in_a2 = regs->ARM_r2;
 #endif
 		w->in_req_us = req;
 		w->in_site = site;
 		w->in_ts = local_clock();
 	}
 	local_irq_restore(flags);
 }

 /* Called from syscall_trace_exit(); the return value is in regs. */
 void starve_dbg_sys_exit(struct pt_regs *regs)
 {
 	struct sd_watch *w;
 	unsigned long flags;

 	if (likely(!READ_ONCE(sd_nwatch)))
 		return;
 	local_irq_save(flags);
 	w = sd_watch_find(current);
 	if (w && w->in_ts) {
 		sd_sys_account(w, (long)regs_return_value(regs),
 			       local_clock() - w->in_ts);
 		w->in_ts = 0;
 	}
 	local_irq_restore(flags);
 }

