 /*
  * Interrupts must be disabled: called from the tick, from the RCU stall code
  * (both hard IRQ) or from the "dump" parameter.  @gps: jiffies at the start
  * of the stalled grace period, 0 if none.
  */
 static void sd_report(struct task_struct *gpk, const char *why, bool full,
 		      unsigned long gps)
 {
 	struct rq *rq = this_rq();
 	time64_t wall = ktime_get_real_seconds();
 	const struct sd_agg_task *hog;
 	u64 now = local_clock(), win0 = 0, last, on, to;
 	struct sd_t t = sd_tms(now);
 	pid_t hog_pid;

 	/* window: the stalled grace period, else the stall, else 3 s */
 	if (gps) {
 		u64 gp = jiffies_to_nsecs(jiffies - gps);

 		win0 = now > gp ? now - gp : 1;
 	}
 	if (sd_st_active && (!win0 || sd_st_onset < win0))
 		win0 = sd_st_onset;
 	if (!win0)
 		win0 = now - min_t(u64, now, 3ULL * NSEC_PER_SEC);
 	sd_agg(&sd_agg_a, win0, now);
 	hog = sd_agg_pick(&sd_agg_a, NULL);
 	hog_pid = hog ? hog->pid : 0;

 	sd_lb_reset();
 	sd_umm_put();
 	pr_err(SD "======== %s report at %ptT UTC, uptime %lu.%03u ========\n",
 	       why, &wall, t.s, t.f);
 	sd_print_summary(gpk, rq, now, gps, hog);
 	last = now - min_t(u64, now, NSEC_PER_SEC);

 	if (!full) {
 		pr_info(SD "[5] CPU per 100 ms, last 3 s (n: switched in, s: went to sleep):\n");
 		sd_print_fine(now - min_t(u64, now, 3ULL * NSEC_PER_SEC), now);
 		sd_print_socks(now, 16);
 		sd_print_switches(32);
 		sd_print_tasks(rq, false);
 		goto out;
 	}

 	sd_print_window(rq, now);
 	sd_print_sys(now);
 	sd_print_socks(now, 40);
 	pr_info(SD "[4] CPU per second, last 60 s (n: switched in, s: went to sleep):\n");
 	sd_print_secs(now - min_t(u64, now, 60ULL * NSEC_PER_SEC), now);
 	if (sd_st_active) {
 		on = sd_st_onset;
 		/* stop before the last second, which is printed below */
 		to = min_t(u64, on + NSEC_PER_SEC, last);
 		t = sd_tms(on);
 		pr_info(SD "[5] CPU per 100 ms around the starvation onset at %lu.%03u:\n",
 			t.s, t.f);
 		sd_print_fine(on - min_t(u64, on, 2ULL * NSEC_PER_SEC), to);
 	}
 	pr_info(SD "[5] CPU per 100 ms, last second:\n");
 	sd_print_fine(last, now);
 	sd_print_gpk(gpk, rq);
 	sd_print_samples();
 	sd_print_irqs(now);
 	sd_print_switches(48);
 	sd_print_tasks(rq, true);
 	sd_print_rt_tasks();
 	sd_print_stack(hog_pid);
 out:
 	sd_umm_put();
 	pr_err(SD "======== end of %s report ========\n", why);
 	sd_skip_irq = true;
 }

 /*
  * Called on every tick from rcu_sched_clock_irq().  @starve_j is how long
  * the GP kthread has not shown activity while a grace period is in
  * progress (0 if no grace period is in progress).
  */
 void notrace starve_dbg_tick(int user, unsigned long starve_j,
 			     struct task_struct *gpk)
 {
 	unsigned long j = jiffies;
 	unsigned long gap = j - sd_prev_tick_j;
 	unsigned int thresh_ms = READ_ONCE(sd_thresh_ms);
 	unsigned int interval_s = READ_ONCE(sd_early_interval_s);
 	u64 now;

 	sd_prev_tick_j = j;
 	sd_gpk = gpk;
 	sd_starve_j = starve_j;
 	if (!READ_ONCE(sd_enable))
 		return;
 	now = local_clock();
 	sd_acct(now, current);
 	if (sd_nstuck)
 		sd_sk_tick(now);
 	if (!gpk)
 		return;

 	if (starve_j < msecs_to_jiffies(max(thresh_ms, 100U))) {
 		if (sd_active)
 			sd_episode_end(starve_j, now);
 		else if (sd_st_active && now - sd_st_last_end > SD_STALL_GAP_NS)
 			sd_stall_end();
 		return;
 	}

 	if (sd_active) {
 		sd_take_sample(now, user, gap);
 		return;
 	}

 	sd_episode_begin(starve_j, gap, now);
 	sd_take_sample(now, user, 0);
 	if (!sd_early_printed ||
 	    time_after(j, sd_early_j + (unsigned long)interval_s * HZ)) {
 		sd_early_printed = true;
 		sd_early_j = j;
 		sd_report(gpk, "early", false, 0);
 	}
 }

 /* Called from the RCU CPU stall code right before panic_on_rcu_stall(). */
 void starve_dbg_report(struct task_struct *gpk, const char *why,
 		       unsigned long gp_start)
 {
 	if (READ_ONCE(sd_enable))
 		sd_report(gpk, why, true, gp_start);
 }

