 /* echo 1 > /sys/module/starve_dbg/parameters/dump: full report now */
 static int sd_dump_set(const char *val, const struct kernel_param *kp)
 {
 	unsigned long flags;

 	if (system_state != SYSTEM_RUNNING)
 		return 0;
 	local_irq_save(flags);
 	sd_report(READ_ONCE(sd_gpk), "manual", true, 0);
 	local_irq_restore(flags);
 	return 0;
 }

 static const struct kernel_param_ops sd_dump_ops = {
 	.set	= sd_dump_set,
 };
 module_param_cb(dump, &sd_dump_ops, NULL, 0200);

 /* echo <tid> > /sys/module/starve_dbg/parameters/watch_pid: record syscalls */
 static int sd_watch_set(const char *val, const struct kernel_param *kp)
 {
 	struct task_struct *p;
 	unsigned long flags;
 	int pid, ret;

 	ret = kstrtoint(val, 0, &pid);
 	if (ret)
 		return ret;
 	ret = -ESRCH;
 	local_irq_save(flags);
 	rcu_read_lock();
 	p = find_task_by_pid_ns(pid, &init_pid_ns);
 	if (p && p->mm && !(p->flags & PF_KTHREAD)) {
 		if (!sd_nwatch)
 			sd_watch_reset(local_clock());
 		sd_watch_add(p);
 		ret = 0;
 	}
 	rcu_read_unlock();
 	local_irq_restore(flags);
 	return ret;
 }

 static const struct kernel_param_ops sd_watch_ops = {
 	.set	= sd_watch_set,
 };
 module_param_cb(watch_pid, &sd_watch_ops, NULL, 0200);

