 /*
  * The summary: what stalls, who has the CPU, how it behaves, what it does
  * and, if any, the socket that keeps it busy.  KERN_ERR, so it also reaches
  * the console.  sd_agg_a holds the window.
  */
 static void sd_print_summary(struct task_struct *gpk, struct rq *rq, u64 now,
 			     unsigned long gps, const struct sd_agg_task *hog)
 {
 	const struct sd_agg *a = &sd_agg_a;
 	u64 total = sd_agg_total(a), span = a->nb ? a->t1 - a->t0 : 0;
 	unsigned int i, k, pm_rt, pm_lim;
 	const struct sd_sys *s;
 	struct sd_sk *w;
 	struct sd_sev h;
 	struct sd_t t;
 	int fd;

 	sd_lb_reset();
 	sd_lb("SUMMARY: ");
 	if (gps) {
 		u64 gp = jiffies_to_nsecs(jiffies - gps);

 		t = sd_tms(now > gp ? now - gp : 0);
 		sd_lb("RCU grace period pending for %u ms (since %lu.%03u)",
 		      sd_ms(gp), t.s, t.f);
 	} else {
 		sd_lb("no RCU stall reported yet");
 	}
 	if (gpk)
 		sd_lb("; GP kthread %d/%s state %c, no activity for %u ms",
 		      gpk->pid, gpk->comm, task_state_to_char(gpk),
 		      jiffies_to_msecs(sd_starve_j));
 	if (sd_st_active) {
 		t = sd_tms(sd_st_onset);
 		sd_lb("; starving since %lu.%03u, %u episode(s)", t.s, t.f,
 		      sd_st_episodes);
 	}
 	sd_lb_flush('E');

 	sd_print_rcu_readers(rq);

 	t = sd_tms(a->t0);
 	sd_lb("SUMMARY: CPU during %u ms from %lu.%03u: ", sd_ms(span), t.s,
 	      t.f);
 	if (hog) {
 		sd_lb("%d/%s ", hog->pid, hog->comm);
 		sd_lb_cls(hog->cls, hog->prio);
 		sd_lb_pm(" ", hog->run_us, total);
 		sd_lb(" | ");
 	}
 	sd_lb_cpu_shares(a);
 	sd_lb(" | GP kthread ran %llu us", a->gpk_us);
 	sd_lb_flush('E');

 	if (hog) {
 		sd_lb("SUMMARY: %d/%s ran %u times/s for %u us each and went to sleep %u times/s",
 		      hog->pid, hog->comm, sd_rate(hog->runs, span),
 		      hog->runs ? hog->run_us / hog->runs : 0,
 		      sd_rate(hog->sleeps, span));
 		if (sd_st_active && sd_st_cfs_slices) {
 			u64 pre = 0, fast = 0;

 			for (i = 0; i < SD_NR_LOG2; i++) {
 				pre += sd_st_cfs_rtpre[i];
 				if (i < 2)
 					fast += sd_st_cfs_rtpre[i];
 			}
 			sd_lb("; CFS got %u slices/s, ",
 			      sd_rate(sd_st_cfs_slices, now - sd_st_start));
 			sd_lb_pm("", pre, sd_st_cfs_slices);
 			sd_lb(" ended by RT preemption, ");
 			sd_lb_pm("", fast, pre);
 			sd_lb(" of them within 16 us");
 		}
 		if (sysctl_sched_rt_runtime < 0) {
 			sd_lb("; RT throttling disabled");
 		} else {
 			pm_rt = sd_pm(a->rt_us, total);
 			pm_lim = sd_pm(sysctl_sched_rt_runtime,
 				       sysctl_sched_rt_period);
 			sd_lb("; RT throttling %s: RT %u.%u%% %s limit %u.%u%%",
 			      rq->rt.rt_throttled ? "ACTIVE" : "inactive",
 			      pm_rt / 10, pm_rt % 10, pm_rt < pm_lim ? "<" : ">=",
 			      pm_lim / 10, pm_lim % 10);
 		}
 		sd_lb_flush('E');
 	}

 	if (hog && sd_sys_used) {
 		sd_lb("SUMMARY: %d/%s syscalls/s:", hog->pid, hog->comm);
 		memset(sd_used_sys, 0, sizeof(sd_used_sys));
 		for (k = 0; k < 5; k++) {
 			s = sd_sys_pick(hog->pid);
 			if (!s)
 				break;
 			sd_lb(" ");
 			sd_lb_sysname(s->nr);
 			if (sd_sys_has_fd(s->nr))
 				sd_lb("(fd %lu)", s->a0);
 			sd_lb(" %u", sd_rate(s->n, now - sd_watch_since));
 			sd_lb_sys_ret(s);
 			sd_lb(";");
 		}
 		sd_lb_flush('E');
 	}

 	w = sd_sk_worst();
 	if (!w)
 		return;
 	fd = sd_sk_fd(w->tgid, w->sk);
 	sd_lb("SUMMARY: udp :%u", w->lport);
 	if (fd >= 0)
 		sd_lb(" (fd %d of %d/%s)", fd, w->pid, w->comm);
 	if (w->stuck) {
 		u64 d = now - w->since;

 		t = sd_tus(w->since);
 		sd_lb(" STUCK for %u ms since %lu.%06u: errq=%u sk_err=%d, poll() POLLERR %u/s, recv() -EAGAIN %u/s",
 		      sd_ms(d), t.s, t.f,
 		      skb_queue_len_lockless(&w->sk->sk_error_queue),
 		      READ_ONCE(w->sk->sk_err), sd_rate(w->n_poll, d),
 		      sd_rate(w->n_eagain, d));
 	} else {
 		sd_lb(" was stuck %u time(s), longest %u ms", w->n_long,
 		      sd_ms(w->max_stuck_ns));
 	}
 	sd_lb_flush('E');

 	sd_lb("SUMMARY: udp :%u", w->lport);
 	if (w->stuck && skb_queue_len_lockless(&w->sk->sk_error_queue)) {
 		memset(&h, 0, sizeof(h));
 		sd_sev_errq_head(&h, w->sk);
 		sd_lb(" stale entry: ");
 		sd_lb_errinfo(&h);
 		sd_lb(";");
 	}
 	if (w->last_take.ts) {
 		t = sd_tus(w->last_take.ts);
 		sd_lb(" sk_err last taken at %lu.%06u by %d/%s: ", t.s, t.f,
 		      w->last_take.pid, w->last_take.comm);
 		sd_lb_take(&w->last_take);
 		sd_lb(", %u entr%s left queued;", w->last_take.errq,
 		      w->last_take.errq == 1 ? "y" : "ies");
 	}
 	if (w->last_deq.ts) {
 		t = sd_tus(w->last_deq.ts);
 		sd_lb(" last MSG_ERRQUEUE read at %lu.%06u by %d/%s", t.s, t.f,
 		      w->last_deq.pid, w->last_deq.comm);
 	} else {
 		sd_lb(" no MSG_ERRQUEUE read seen");
 	}
 	sd_lb_flush('E');

 	if (hog && w->stuck && hog->cls != 'C' &&
 	    (w->s_pid == hog->pid || w->pid == hog->pid)) {
 		sd_lb("SUMMARY: => RT task %d/%s loops on udp :%u: poll() returns at once because of an error queue entry nobody reads, recv() returns -EAGAIN, its sleeps are microseconds; CFS tasks incl. the RCU GP kthread get no useful CPU",
 		      hog->pid, hog->comm, w->lport);
 		sd_lb_flush('E');
 	}
 }

