 	unsigned int i, k, n, nsel = 0, sel = 0;
 	const struct sd_sev *e;
 	struct sd_sev h;
 	struct sd_sk *t;
 	struct sd_t ts;
 	int fd;

 	pr_info(SD "[3] UDP sockets with IP_RECVERR. POLLERR stays set while the error queue (errq) is not empty, also with sk_err=0; recv() then returns -EAGAIN until recvmsg(MSG_ERRQUEUE) removes the entry\n");
