 /* syscall name from sys_call_table, without the "sys_" prefix */
 static void sd_lb_sysname(int nr)
 {
 	int pos = sd_llen;

 #ifdef CONFIG_ARM
 	if (nr >= 0 && nr < NR_syscalls) {
 		sd_lb("%ps", (void *)sys_call_table[nr]);
 		if (sd_llen - pos > 4 && !strncmp(sd_lbuf + pos, "sys_", 4)) {
 			memmove(sd_lbuf + pos, sd_lbuf + pos + 4,
 				sd_llen - pos - 4 + 1);
 			sd_llen -= 4;
