 static bool sd_sk_want(const struct sock *sk)
 {
 	if (sk->sk_type != SOCK_DGRAM || sk->sk_protocol != IPPROTO_UDP ||
 	    (sk->sk_family != AF_INET && sk->sk_family != AF_INET6) ||
 	    !inet_sk(sk)->inet_num)
 		return false;
 	if (inet_sk(sk)->recverr)
 		return true;
 #if IS_ENABLED(CONFIG_IPV6)
 	if (sk->sk_family == AF_INET6) {
 		const struct ipv6_pinfo *np = inet6_sk(sk);

 		return np && np->recverr;
 	}
 #endif
 	return false;
 }

 /* event from a task that entered the kernel from user space */
 static void sd_sev_task(struct sd_sev *e)
 {
 	if (!in_task() || !current->mm || (current->flags & PF_KTHREAD))
 		return;
 	e->task = true;
 	e->pid = current->pid;
 	e->tgid = current->tgid;
 	memcpy(e->comm, current->comm, TASK_COMM_LEN);
 	e->comm[TASK_COMM_LEN - 1] = '\0';
 	sd_usite_get(&e->site);
 }

 /* origin, type/code, errno and addresses of an error queue skb */
 static void sd_sev_skb(struct sd_sev *e, const struct sock *sk,
 		       const struct sk_buff *skb)
 {
 	const struct sock_exterr_skb *serr = SKB_EXT_ERR(skb);

 	e->origin = serr->ee.ee_origin;
 	e->itype = serr->ee.ee_type;
 	e->icode = serr->ee.ee_code;
 	e->err = (s16)serr->ee.ee_errno;
 	if (sk->sk_family == AF_INET &&
 	    (e->origin == SO_EE_ORIGIN_ICMP || e->origin == SO_EE_ORIGIN_LOCAL)) {
 		if (e->origin == SO_EE_ORIGIN_ICMP)
 			e->from = ip_hdr(skb)->saddr;
 		memcpy(&e->daddr, skb_network_header(skb) + serr->addr_offset,
 		       sizeof(e->daddr));
 		e->dport = ntohs(serr->port);
 	}
 }

 /* first entry of the error queue, IRQs disabled */
 static void sd_sev_errq_head(struct sd_sev *e, struct sock *sk)
 {
 	struct sk_buff_head *q = &sk->sk_error_queue;
 	struct sk_buff *skb;

 	spin_lock(&q->lock);
 	skb = skb_peek(q);
 	if (skb)
 		sd_sev_skb(e, sk, skb);
 	spin_unlock(&q->lock);
 }

 static void sd_sev_push(const struct sd_sev *e)
 {
 	sd_sev[sd_sev_head++ & (SD_NR_SEV - 1)] = *e;
 }

 static struct sd_sk *sd_sk_find(const struct sock *sk)
 {
 	unsigned int i;

 	for (i = 0; i < SD_NR_SK; i++)
 		if (sd_sks[i].sk == sk)
 			return &sd_sks[i];
 	return NULL;
 }

 /*
  * Slot of sk, IRQs disabled.  A new slot takes a reference on sk.  The socket
  * of a reused slot is returned in *put; the caller releases it with
  * sock_put() after re-enabling interrupts.
  */
 static struct sd_sk *sd_sk_get(struct sock *sk, struct sock **put)
 {
 	struct sd_sk *t = sd_sk_find(sk), *v = NULL;
 	unsigned int i;

 	if (t)
 		return t;
 	for (i = 0; i < SD_NR_SK; i++) {
 		t = &sd_sks[i];
 		if (!t->sk || sock_flag(t->sk, SOCK_DEAD)) {
 			v = t;
 			break;
 		}
 		if (!t->stuck && (!v || t->last_ns < v->last_ns))
 			v = t;
 	}
 	if (!v || !refcount_inc_not_zero(&sk->sk_refcnt))
 		return NULL;
 	if (v->stuck && sd_nstuck)
 		sd_nstuck--;
 	*put = v->sk;
 	memset(v, 0, sizeof(*v));
 	v->sk = sk;
 	v->lport = inet_sk(sk)->inet_num;
 	v->family = sk->sk_family;
 	return v;
 }

 /* remember the task using the socket, IRQs disabled */
 static void sd_sk_user(struct sd_sk *t)
 {
 	if (!in_task() || !current->mm || (current->flags & PF_KTHREAD))
 		return;
 	t->pid = current->pid;
 	t->tgid = current->tgid;
 	memcpy(t->comm, current->comm, TASK_COMM_LEN);
 	t->comm[TASK_COMM_LEN - 1] = '\0';
 }

 /* the error queue or sk_err changed: end a stuck period, IRQs disabled */
 static void sd_sk_unstuck(struct sd_sk *t, u64 now)
 {
 	struct sd_sev e;
 	u64 dur;

 	if (!t->stuck)
 		return;
 	dur = now > t->since ? now - t->since : 0;
 	if (dur > t->max_stuck_ns)
 		t->max_stuck_ns = dur;
 	if (t->logged) {
 		memset(&e, 0, sizeof(e));
 		e.ts = now;
 		e.type = SEV_UNSTUCK;
 		e.slot = t - sd_sks;
 		e.lport = t->lport;
 		e.dur = dur;
 		e.n_poll = t->n_poll;
 		e.n_eagain = t->n_eagain;
 		sd_sev_push(&e);
 	} else {
 		t->n_short++;
 	}
 	t->stuck = false;
 	t->logged = false;
 	t->warned = false;
 	if (sd_nstuck)
 		sd_nstuck--;
 }

 /* one more POLLERR (how 0) or -EAGAIN (how 1) while stuck, IRQs disabled */
 static void sd_sk_count(struct sd_sk *t, int how, u64 now)
 {
 	struct sd_sev e;

 	if (how)
 		t->n_eagain++;
 	else
 		t->n_poll++;
 	if (t->logged || now - t->since < SD_STUCK_LOG_NS)
 		return;
 	/* stuck for 20 ms: not the short normal case, log where it began */
 	memset(&e, 0, sizeof(e));
 	e.ts = t->since;
 	e.type = SEV_STUCK;
 	e.slot = t - sd_sks;
 	e.lport = t->lport;
 	e.how = t->how;
 	e.errq = sd_clip8(skb_queue_len_lockless(&t->sk->sk_error_queue));
 	e.sk_err = sd_clip8(READ_ONCE(t->sk->sk_err));
 	sd_sev_errq_head(&e, t->sk);
 	if (t->s_pid) {
 		e.task = true;
 		e.pid = t->s_pid;
 		e.tgid = t->s_tgid;
 		memcpy(e.comm, t->s_comm, TASK_COMM_LEN);
 		e.site = t->s_site;
 	}
 	sd_sev_push(&e);
 	t->logged = true;
 	t->n_long++;
 }

 /*
  * udp_poll() returns EPOLLERR (how 0) or a UDP receive returns -EAGAIN
  * (how 1).  With sk_err == 0 and a non-empty error queue nothing but
  * recvmsg(MSG_ERRQUEUE) will clear POLLERR: the socket is "stuck".
  */
 static void sd_sk_observe(struct sock *sk, int how)
 {
 	struct sock *put = NULL;
 	struct sd_usite site;
 	unsigned long flags;
 	struct sd_sk *t;
 	u64 now;

 	if (READ_ONCE(sk->sk_err) ||
 	    skb_queue_empty_lockless(&sk->sk_error_queue) ||
 	    !READ_ONCE(sd_enable) || !sd_sk_want(sk))
 		return;

 	local_irq_save(flags);
 	t = sd_sk_find(sk);
 	if (t && t->stuck) {
 		if (how)
 			t->obs_eagain++;
 		else
 			t->obs_poll++;
 		sd_sk_count(t, how, local_clock());
 		local_irq_restore(flags);
 		return;
 	}
 	local_irq_restore(flags);

 	sd_usite_get(&site);
 	local_irq_save(flags);
 	now = local_clock();
 	t = sd_sk_get(sk, &put);
 	if (t) {
 		if (how)
 			t->obs_eagain++;
 		else
 			t->obs_poll++;
 		t->last_ns = now;
 		sd_sk_user(t);
 		if (!t->stuck && !READ_ONCE(sk->sk_err) &&
 		    !skb_queue_empty_lockless(&sk->sk_error_queue)) {
 			t->stuck = true;
 			t->logged = false;
 			t->warned = false;
 			t->how = how;
 			t->since = now;
 			t->n_poll = 0;
 			t->n_eagain = 0;
 			t->s_pid = 0;
 			if (in_task() && current->mm) {
 				t->s_pid = current->pid;
 				t->s_tgid = current->tgid;
 				memcpy(t->s_comm, current->comm, TASK_COMM_LEN);
 				t->s_comm[TASK_COMM_LEN - 1] = '\0';
 				t->s_site = site;
 			}
 			sd_nstuck++;
 		}
 		if (t->stuck)
 			sd_sk_count(t, how, now);
 	}
 	local_irq_restore(flags);
 	if (put)
 		sock_put(put);
 }

 void starve_dbg_udp_pollerr(struct sock *sk)
 {
 	sd_sk_observe(sk, 0);
 }

 void starve_dbg_udp_eagain(struct sock *sk)
 {
 	sd_sk_observe(sk, 1);
 }

 /* enqueue (ret 0) or drop (ret -ENOMEM) of an error queue entry */
 void starve_dbg_errq_enq(struct sock *sk, const struct sk_buff *skb, int ret)
 {
 	struct sock *put = NULL;
 	unsigned long flags;
 	struct sd_sev e;
 	struct sd_sk *t;

 	if (!READ_ONCE(sd_enable) || !sd_sk_want(sk))
 		return;
 	memset(&e, 0, sizeof(e));
 	e.type = ret ? SEV_NOMEM : SEV_ENQ;
 	e.lport = inet_sk(sk)->inet_num;
 	sd_sev_skb(&e, sk, skb);
 	sd_sev_task(&e);
 	local_irq_save(flags);
 	e.ts = local_clock();
 	t = sd_sk_get(sk, &put);
 	if (t) {
 		e.slot = t - sd_sks;
 		sd_sk_unstuck(t, e.ts);
 		if (ret)
 			t->nomem++;
 		else
 			t->enq++;
 		e.errq = sd_clip8(skb_queue_len_lockless(&sk->sk_error_queue) +
 				  (ret ? 0 : 1));
 		/* the ICMP error handlers set sk_err right after queueing */
 		if (e.origin == SO_EE_ORIGIN_ICMP ||
 		    e.origin == SO_EE_ORIGIN_ICMP6)
 			e.sk_err = sd_clip8(e.err);
 		else
 			e.sk_err = sd_clip8(READ_ONCE(sk->sk_err));
 		t->last_ns = e.ts;
 		if (e.task)
 			sd_sk_user(t);
 		sd_sev_push(&e);
 		t->last_enq = e;
 	}
 	local_irq_restore(flags);
 	if (put)
 		sock_put(put);
 }

 /* recvmsg(MSG_ERRQUEUE) dequeued skb */
 void starve_dbg_errq_deq(struct sock *sk, const struct sk_buff *skb)
 {
 	struct sock *put = NULL;
 	unsigned long flags;
 	struct sd_sev e;
 	struct sd_sk *t;

 	if (!READ_ONCE(sd_enable) || !sd_sk_want(sk))
 		return;
 	memset(&e, 0, sizeof(e));
 	e.type = SEV_DEQ;
 	e.lport = inet_sk(sk)->inet_num;
 	sd_sev_skb(&e, sk, skb);
 	sd_sev_task(&e);
 	local_irq_save(flags);
 	e.ts = local_clock();
 	t = sd_sk_get(sk, &put);
 	if (t) {
