 	e->sleeps = 0;
 	memcpy(e->comm, p->comm, TASK_COMM_LEN);
 	e->comm[TASK_COMM_LEN - 1] = '\0';
 found:
 	*slot = i;
 	e = &sd_wt[i];
 	e->cls = sd_cls(p);
 	e->prio = sd_prio(p);
