 /* p ran for @delta ns inside the open bucket */
 static void sd_charge(const struct task_struct *p, u64 delta)
 {
 	struct sd_wt *e;
 	u32 d;

 	if (!delta)
 		return;
 	d = delta > SD_HB_NS ? (u32)SD_HB_NS : (u32)delta;
 	switch (sd_cls(p)) {
 	case 'I':
 		sd_open.idle_ns += d;
 		break;
 	case 'C':
 		sd_open.cfs_ns += d;
 		break;
 	default:
 		sd_open.rt_ns += d;
 		break;
 	}
 	if (p == sd_gpk)
 		sd_open.gpk_ns += d;
 	e = sd_wt_get(p);
 	if (e)
 		e->run_ns += d;
