 static int ppxy_netPortProxyTxPkt(int sh, const void *data, int dataLen,
                       t_sockaddr remoteSockAddr, int ttl)
 {
   int rc;
   int sockfd;
   struct sockaddr_storage dest_addr;
   int old_ttl;
   pthread_mutex_t socketMutex;

   if (NULL==data) {
     MS_LOG_SESSION(LOG_ERR, sh, "null data pointer");
     return -1;
   }

   if (ttl < 0) {
     MS_LOG_SESSION(LOG_ERR, sh, "TTL=%d, can not be < 0", ttl);
     return -1;
   }

   if(remoteSockAddr.ip.iptype == INADDR_IPV6) {
     struct sockaddr_in6 * tmp = (struct sockaddr_in6 *)&dest_addr;
     tmp->sin6_family = AF_INET6;
     tmp->sin6_addr = remoteSockAddr.ip._ipaddr.addr6;
     tmp->sin6_port = htons(remoteSockAddr.port);
   } else if(remoteSockAddr.ip.iptype == INADDR_IPV4) {
     struct sockaddr_in * tmp = (struct sockaddr_in *)&dest_addr;
     tmp->sin_family = AF_INET;
     tmp->sin_addr = remoteSockAddr.ip._ipaddr.addr4;
     tmp->sin_port = htons(remoteSockAddr.port);
   } else {
     MS_LOG_SESSION(LOG_ERR, sh, "invalid send address");
     return -1;
   }

   sockfd = ppxy_netPortProxyFindSockFromExternalHdl(sh);
   if(sockfd < 0) {
     MS_LOG_SESSION(LOG_ERR, sh, "socket not initialized");
     return -1;
   }
   MS_LOG_SESSION(LOG_NOTICE, sh, "[sock=%d][remote addr=%s][destPort=%d]",
          sockfd, inet_ntoa(remoteSockAddr.ip._ipaddr.addr4), remoteSockAddr.port);
   /*
    * If stunTrace pkt, adjust the TTL before sending and restore it afterwards
    */
   if (ttl > 0) {
       if(remoteSockAddr.ip.iptype == INADDR_IPV6) {
         MS_LOG_SESSION(LOG_ERR, sh, "stunTrace not supported on IPV6");
         return -1;
       }
       if (sockm_getInternetSocketMutex(sockfd, &socketMutex) == MS_ERROR) {
           MS_LOG_SESSION(LOG_ERR, sh, "Unable to get Mutex for sockfd=%d", sockfd);
           return -1;
       }
       pthread_mutex_lock(&socketMutex);
       if ((sockm_getTtl(INADDR_IPV4,sockfd,&old_ttl)) == MS_ERROR) {
           pthread_mutex_unlock(&socketMutex);
           return -1;
       }
       MS_LOG_SESSION(LOG_DEBUG, sh, "stunTrace old_ttl=%d, new_ttl=%d", old_ttl,ttl);
       if ((sockm_setTtl(INADDR_IPV4,sockfd,ttl)) == MS_ERROR) {
           pthread_mutex_unlock(&socketMutex);
           return -1;
       }
       rc = sendto(sockfd, data, dataLen, 0,
                   (struct sockaddr*)&dest_addr, sizeof(dest_addr));
      if (rc <=0) {
            MS_LOG_SESSION(LOG_ERR, sh,
                    "[sock=%d]""[errno=%d]"
                    " sendto failed",
                    sockfd, errno);
            // Don't return without resetting ttl
      }
      if ((sockm_setTtl(INADDR_IPV4,sockfd,old_ttl)) == MS_ERROR) {
          pthread_mutex_unlock(&socketMutex);
          return -1;
      }

      pthread_mutex_unlock(&socketMutex);
      MS_LOG_SESSION(LOG_DEBUG, sh, "Sent stunTrace pkt, rc=%d, ttl=%d,"
               "[remote addr=%s][destPort=%d] ", rc, ttl,
               inet_ntoa(remoteSockAddr.ip._ipaddr.addr4), remoteSockAddr.port);
   } else {
     rc = sendto(sockfd, data, dataLen, 0,
                 (struct sockaddr*)&dest_addr, sizeof(dest_addr));
   }
   if(rc < 0) {
     MS_LOG_SESSION(LOG_ERR, sh, "could not send Proxy Pkt errno = %s", strerror(errno));
   }

   return rc;
 }

