  *
  * @description This function searches for an open spot in the session
  *              array.  It will initialize the data structure based on
  *              if there are multiple owners of the socket.
  *
  * @param[in] idx    : The FD table index
  * @param[in] fd     : The socket fd
  * @param[in] sdata  : The FD specific data
  * @param[in] execf  : The function that needs to be called when data
  *                     is available
  * @param[in] demuxf : The function that needs to be called when data
  *                     is available and demux needs to happen
  *
  * @return MS_OK or MS_ERROR
  */
 int slm_selectFdInit(int idx, int fd, int sdata, t_exec execf, t_demuxf demuxf, t_execPort portProxyf)
 {
     int retVal = MS_ERROR;
     int i = MAX_MS_SHARED_FDS;
     bool sameCaller = false;

     // lock the mutex
     (void)pthread_mutex_lock(&fdMutex);

     // check if the slot is inuse
     if (fdDSP.fdfcn[idx].inuse == TRUE) {
         // make sure the same caller didn't call again
         if ( portProxyf && (fdDSP.fdfcn[idx].proxyHdl == sdata)) {
             // return ok for same caller
             retVal = MS_OK;
             sameCaller = true;
         } else {
             for (i = 0; i < MAX_MS_SHARED_FDS; i++) {
                 // if this was called by same caller then do nothing
                 if (fdDSP.fdfcn[idx].sessInfo[i].sdata == sdata) {
                     // return ok for same caller
                     retVal = MS_OK;
                     sameCaller = true;
                     break;
                 }
             }
         }

         if (sameCaller == false) {
             if (portProxyf) {
                 fdDSP.fdfcn[idx].fd = fd;
                 fdDSP.fdfcn[idx].state = FD_ACTIVE;
                 fdDSP.fdfcn[idx].proxyHdl = sdata;
                 fdDSP.fdfcn[idx].f_portProxy = portProxyf;
                 retVal = MS_OK;
                 SYSLOG(LOG_NOTICE | MS_SELECT,
                        "[idx=%d][fd=%d][sdata=%d][reserved=%d][count=%d]"
                        "[func=%p][demuxfunc=%p][proxy func=%p]",
                        idx, fdDSP.fdfcn[idx].fd, sdata,
                        fdDSP.fdfcn[idx].reservedCount, fdDSP.fdfcn[idx].demuxCount,
                        fdDSP.fdfcn[idx].f_exec, fdDSP.fdfcn[idx].f_demux,
                        fdDSP.fdfcn[idx].f_portProxy);
             } else {
                 // make sure there is an open spot
                 if ((fdDSP.fdfcn[idx].demuxCount+1) < MAX_MS_SHARED_FDS) {
                     fdDSP.fdfcn[idx].fd = fd;
                     fdDSP.fdfcn[idx].state = FD_ACTIVE;

                     // loop and find a spot
                     for (i = 0; i < MAX_MS_SHARED_FDS; i++) {
                         // if the data is 0 then its open
                         if (fdDSP.fdfcn[idx].sessInfo[i].sdata == 0) {
                             // spot available; increment demux count
                             fdDSP.fdfcn[idx].demuxCount++;

                             // found a spot
                             fdDSP.fdfcn[idx].sessInfo[i].sdata = sdata;
                             fdDSP.fdfcn[idx].f_exec = execf;
                             fdDSP.fdfcn[idx].f_demux = demuxf;

                             retVal = MS_OK;
                             SYSLOG(LOG_NOTICE | MS_SELECT,
                                    "[idx=%d][fd=%d][sdata=%d][reserved=%d][count=%d]"
                                    "[func=%p][demuxfunc=%p][proxy func=%p]",
                                    idx, fdDSP.fdfcn[idx].fd, fdDSP.fdfcn[idx].sessInfo[i].sdata,
                                    fdDSP.fdfcn[idx].reservedCount, fdDSP.fdfcn[idx].demuxCount,
                                    fdDSP.fdfcn[idx].f_exec, fdDSP.fdfcn[idx].f_demux,
                                    fdDSP.fdfcn[idx].f_portProxy);
                             break;
                         }
                     }
                 }
             }
         }

         // did we find a spot
         if ((sameCaller == false) && (retVal == MS_ERROR)) {
             // we didn't find a spot
             SYSLOG(LOG_ERROR,
                    "No open fd sub-slot [idx=%d][fd=%d][sdata=%d]"
                    "[count=%d][func=%p]",
                    idx, fd, sdata, fdDSP.fdfcn[idx].demuxCount, execf);
         }
     } else {
         SYSLOG(LOG_ERR, "Unallocated file descriptor element "
                "[idx=%d][fd=%d][sdata=%d][reserved=%d][count=%d][func=%p]",
                idx, fd, sdata, fdDSP.fdfcn[idx].reservedCount,
                fdDSP.fdfcn[idx].demuxCount, execf);
     }

     // unlock the mutex
     (void)pthread_mutex_unlock(&fdMutex);

     return retVal;
 }

 //==========================================================================;
 // Function:
 //   void slm_createClientSocket (void)
 //
 // Description:
 //   This function creates the client socket.
 //
 // Parameters:
 //   idx - The file descriptor index
 //
 // Returns:
 //   None
 //==========================================================================;
 void slm_createClientSocket(void)
 {
     int sock;
     struct sockaddr_un addr;
     struct sockaddr_un* addrPtr = &addr;

     memset ( &addr, 0x00, sizeof(struct sockaddr) );

     // create IPC to send requests, a local socket
     sock = socket(PF_LOCAL, SOCK_DGRAM, 0);

     // make an address
     addr.sun_family = AF_LOCAL;
     strncpy(addr.sun_path, RTP_SOCK, strlen(RTP_SOCK)+1);

     // connect (the socket) to the address
     if (connect(sock, (struct sockaddr*)addrPtr, sizeof(struct sockaddr_un)) < 0) {
         SYSLOG (LOG_ERR, "Client socket connect error %m");
         if(close(sock)!=0){
             SYSLOG(LOG_WARNING,"close socket %d error,errno:%d",sock,errno);
         }
     } else {
         fdDSP.fdwrite = sock;
         SYSLOG(LOG_NOTICE | MS_SELECT,
                "Client socket created [sock=%d]", sock);
     }
 }

 /**
  * @brief This function is a mutex protect version of slm_selectFdClose_locked
  *
  * @description Mutex protect slm_selctFdClose_locked
  *
  * @param[in] idx    : The FD table index
  * @param[in] sdata  : The FD specific data
  *
  * @return true if slot was found, false otherwise
  */
 bool slm_selectFdClose(int idx, int sdata, t_proxyHdl proxyHdl)
 {
   bool slotFound = false;

   (void)pthread_mutex_lock(&fdMutex);

   slotFound = slm_selectFdClose_locked(idx, sdata, proxyHdl);

   (void)pthread_mutex_unlock(&fdMutex);

   return slotFound;
 }

 /**
  * @brief This function marks the file descriptor as not active
  *
  * @description This function decrements the counter first.  If there
  *              are more than 1 owners left, the function does nothing.
  *              If there is only 1 owner then need to stop demuxing.  If
  *              there are no more owners then mark the fd as not active.
  *              After this function call selectFdRemove.
  *
  * @param[in] idx    : The FD table index
  * @param[in] sdata  : The FD specific data
  *
  * @return true if slot was found, false otherwise
  */
 static bool slm_selectFdClose_locked(int idx, int sdata, t_proxyHdl proxyHdl)
 {
   int i;
   bool slotFound = false;

     if (fdDSP.fdfcn[idx].inuse == TRUE) {
         if (-1!=proxyHdl) {
             if (fdDSP.fdfcn[idx].proxyHdl==proxyHdl) {
                 slotFound = true;
                 fdDSP.fdfcn[idx].proxyHdl = 0;
                 fdDSP.fdfcn[idx].f_portProxy = NULL;
             }
         } else {
             // loop and find the sdata
             for (i = 0; i < MAX_MS_SHARED_FDS; i++) {
                 // find the slot to close.  have to match the
                 // socket data
                 if (fdDSP.fdfcn[idx].sessInfo[i].sdata == sdata) {
                     slotFound = true;

                     // decrement the demux count
                     fdDSP.fdfcn[idx].demuxCount--;

                     if (fdDSP.fdfcn[idx].demuxCount <= ZERO_FD_OWNER) {
                         fdDSP.fdfcn[idx].demuxCount = 0;
                     }

                     // found the spot.  now init it.
                     fdDSP.fdfcn[idx].sessInfo[i].sdata = 0;
                     fdDSP.fdfcn[idx].sessInfo[i].csrc = 0;
                     fdDSP.fdfcn[idx].sessInfo[i].mask = 0;
                 }
             }
         }
         if ((fdDSP.fdfcn[idx].demuxCount <= ZERO_FD_OWNER) && (!fdDSP.fdfcn[idx].f_portProxy))  {
             // no one sharing. mark the file descriptor as not active
             // fdDSP.fdfcn[idx].state = FD_INIT;
             SYSLOG(LOG_NOTICE | MS_SELECT,
                    "Socket marked inactive [idx=%d][sdata=%d][fd=%d]"
                    "[reserved=%d][count=%d]",
                    idx, sdata, fdDSP.fdfcn[idx].fd,
                    fdDSP.fdfcn[idx].reservedCount,
                    fdDSP.fdfcn[idx].demuxCount);
         }
     } else {
         SYSLOG(LOG_WARNING | MS_SELECT,
                "Slot not in use [idx=%d][sdata=%d][fd=%d][reserved=%d][count=%d]",
                idx, sdata, fdDSP.fdfcn[idx].fd, fdDSP.fdfcn[idx].reservedCount,
                fdDSP.fdfcn[idx].demuxCount);
     }

     if (slotFound == false) {
         SYSLOG(LOG_WARNING | MS_SELECT,
                "Slot not found [idx=%d][sdata=%d]", idx, sdata);
     }

   return slotFound;
 }

