 //==========================================================================;
 // Function:
 //   int slm_createServerSocket(void)
 //
 // Description:
 //   This function creates a local socket.  The local socket is used to get the
 //   select thread out of the select.  This will bind and connect the socket.
 //
 // Parameters:
 //   None
 //
 // Returns:
 //   The local socket or MS_ERROR
 //==========================================================================;
 int slm_createServerSocket(void)
 {
     int sock = MS_ERROR;
     struct sockaddr_un addr;
     struct sockaddr_un* addrPtr = &addr;

     memset ( &addr, 0x00, sizeof(struct sockaddr_un) );

     // create IPC to receive requests, a local socket, which is selectable
     sock = socket( PF_LOCAL, SOCK_DGRAM, 0);

     // make an address
     addr.sun_family = AF_LOCAL;
     strncpy(addr.sun_path, RTP_SOCK, strlen(RTP_SOCK)+1);

     unlink(addr.sun_path);

     // bind the socket to the address
     if (bind(sock, (struct sockaddr *)addrPtr, sizeof(struct sockaddr_un)) < 0) {
         SYSLOG (LOG_ERR, "select thread-  bind error %m");
         if(close(sock) != 0){
             SYSLOG(LOG_WARNING,"close socket %d error,errno:%d",sock,errno);
         }
         sock = MS_ERROR;
     }

     SYSLOG (LOG_NOTICE | MS_SELECT,
             "Server socket created [sock=%d]", sock);
     return sock;
 }


 //==========================================================================;
 // Function:
 //   int slm_selectRead(void)
 //
 // Description:
 //   This function implements a select to read several file descriptors.
 //
 // Parameters:
 //   None
 //
 // Returns:
 //   The number of valid file descriptors, 0, or MS_ERROR;
 //==========================================================================;
 int slm_selectRead(void)
 {
     int idx, num = MS_ERROR, retval = MS_OK;

     int i = 0 ;
     int currentPollLen = 0;
     // clear all readset
     struct pollfd pollfdArry[MAX_MS_SELECT_FDS];
 	for(;i < MAX_MS_SELECT_FDS ;i++){
         pollfdArry[i].fd = -1;
     }
     //FD_ZERO(&readset);
     // compose the readset
     for (idx = 0; idx < MAX_MS_SELECT_FDS; idx++) {
         if (fdDSP.fdfcn[idx].fd) {
             // make sure the file descriptor is active
             if (fdDSP.fdfcn[idx].state == FD_ACTIVE) {
                 pollfdArry[currentPollLen].fd = fdDSP.fdfcn[idx].fd;
                 pollfdArry[currentPollLen].events = POLLIN;
 		currentPollLen++;
             }
         }
     }

     // select to wait for any file-read complete
     num = poll(pollfdArry, currentPollLen,-1);
     // select completes with an error
     if (num < 0) {
         // don't log ever one.
         if ((fdDSP.selecterr++ % 100) == 1) {
             SYSLOG(LOG_ERR, "select error : %s", strerror(errno));
             usleep(5);
         }
     } else if (num == 0) {
         // this shouldn't ever happen.
         SYSLOG(LOG_ERR, "select timeout");
     } else {
         // select completes without error
         // match all file descriptors and service them

         // add mutex to protect fdDSP from being modified
         (void)pthread_mutex_lock(&fdMutex);

         for (idx = 0; idx < MAX_MS_SELECT_FDS; idx++) {
             // check if valid fd
             if (fdDSP.fdfcn[idx].fd && fdDSP.fdfcn[idx].state == FD_ACTIVE) {
                 // is the fd set
                 int index = findIndexOfPollArray(fdDSP.fdfcn[idx].fd,pollfdArry,currentPollLen);
                 if (index == -1) {
                     SYSLOG(LOG_DEBUG,"not found the fd %d from pollArray",fdDSP.fdfcn[idx].fd);
                     continue;
                 }
                 if ((pollfdArry[index].revents & (POLLERR))||(pollfdArry[index].revents & (POLLIN)) ){
                     int i;
                     if (pollfdArry[index].revents & (POLLERR) ){
                         SYSLOG(LOG_WARNING,"POLL ERR happened on fd %d",fdDSP.fdfcn[idx].fd);
                     }
                     // find the sub-slot.  this needs to be executed
                     // for single or multiple owners of a socket
                     for (i = 0; i < MAX_MS_SHARED_FDS; i++) {
                         if (fdDSP.fdfcn[idx].sessInfo[i].sdata) {
                             break;
                         }
                     }

                     // check if we found one
                     if (i < MAX_MS_SHARED_FDS) {
                         // if only 1 owner
                         if (fdDSP.fdfcn[idx].demuxCount == SINGLE_FD_OWNER) {
                             // verify the function is valid
                             if (fdDSP.fdfcn[idx].f_exec != NULL) {
                                 // make the call to the function
                                 retval = fdDSP.fdfcn[idx].f_exec(fdDSP.fdfcn[idx].fd,
                                                                  fdDSP.fdfcn[idx].sessInfo[i].sdata);
                             }
                         } else {
                             // verify the function is valid
                             if (fdDSP.fdfcn[idx].f_demux != NULL) {
                                 // make the call to the demux function
                                 retval = fdDSP.fdfcn[idx].f_demux(fdDSP.fdfcn[idx].fd,
                                                                   &fdDSP.fdfcn[idx].sessInfo[0]);
                             }
                         }
                         if (retval == MS_ERROR) {
                             // ICMP_UNREACHABLE (retVal = 0) escapes from this stop-action
                             // the existing code stops listen to this socket
                             SYSLOG(LOG_ERR,"removing file descriptor from select [idx=%d][fd=%d]",
                                    idx,fdDSP.fdfcn[idx].fd);
                             slm_selectFdClose_locked(idx, fdDSP.fdfcn[idx].sessInfo[i].sdata, -1);
                         }
                     } else {
                         if (fdDSP.fdfcn[idx].f_portProxy != NULL) {
                             // make the call to the proxy function
                             retval = fdDSP.fdfcn[idx].f_portProxy(fdDSP.fdfcn[idx].fd);
                             if (retval == MS_ERROR) {
                                 // ICMP_UNREACHABLE (retVal = 0) escapes from this stop-action
                                 // the existing code stops listen to this socket
                                 SYSLOG(LOG_ERR,"removing file descriptor from select [idx=%d][fd=%d]"
                                        "[proxyHdl=%d]", idx,fdDSP.fdfcn[idx].fd, fdDSP.fdfcn[idx].proxyHdl);
                                 slm_selectFdClose_locked(idx, 0, fdDSP.fdfcn[idx].proxyHdl);
                             }
                         } else {
                             (void)slm_dummyRead_locked(idx, fdDSP.fdfcn[idx].fd);
                         }
                     }
                 }
             }
         } // end for

         (void)pthread_mutex_unlock(&fdMutex);
     }
     return num;
 }

 //==========================================================================;
 // Function:
 //   void slm_selectThread(void)
 //
 // Description:
 //   This function implements the select thread.  It will read the select readset.
 //
 // Parameters:
 //   None
 //
 // Returns:
 //   None
 //==========================================================================;
 void slm_selectThread(void)
 {
     int fd, rv;
     int retVal;
     int select_slot;
     struct sched_param param = { .sched_priority = MEDIA_SELECT_PRIORITY };

     SYSLOG(LOG_NOTICE | MS_SELECT, "Select thread starting...");

     // name the thread
     rv = prctl(PR_SET_NAME, (unsigned long) "ms_selectThread", 0, 0, 0);
     if (rv == -1) {
         SYSLOG(LOG_NOTICE | MS_INIT,"Can't set thread name");
     }

     // create the local socket
     fd = slm_createServerSocket();

     // check for error in create
     if (fd == MS_ERROR) {
         SYSLOG(LOG_ERR, "Can't create local socket for select thread");
     } else {
         // tell whoever is waiting that this thread has started
         sem_post(&semSelectThread);

         // get a slot for the select manager
         select_slot = slm_getFileDescriptorBlk(fd);

         // check for error
         if (select_slot == MS_ERROR) {
             SYSLOG(LOG_ERR,
                    "No available file descriptor blocks for select thread");
             if(close(fd) != 0){
                 SYSLOG(LOG_WARNING,"close socket %d error",fd);
             }
         } else {
             // initialize the local socket in the fd blk
             retVal = slm_selectFdInit(select_slot, fd, 1, slm_readIPC, NULL, NULL);

             if (retVal != MS_ERROR) {
                 // set the scheduling policy to realtime roundrobin
                 if (sched_setscheduler(0, SCHED_RR, &param) == -1) {
                     SYSLOG(LOG_ERR, "Can't set scheduling policy - %m");
                     setpriority(PRIO_PROCESS,0,TID_SELECT_RTPRX);
                 }

                 // loop forever.  handling all reads
                 while (1) {
                     slm_selectRead();
                 }
             } else {
                 SYSLOG(LOG_ERR, "Select thread not started - init error");
                 slm_closeIPC();
                 if(close(fd)!=0){
                     SYSLOG(LOG_WARNING,"close socket %d error,errno:%d",fd,errno);
                 }
             }
         }
     }
 }

