     void TearDown() override
     {
         if (registeredSessionClose != nullptr) {
             EXPECT_EQ(MS_OK,
                       registeredSessionClose(registeredSessionHandle));
             socket_ = -1;
         }

         if (socket_ >= 0) {
             close(socket_);
         }
     }

     sockaddr_in reserveAndReleaseDestination() const
     {
         const int temporarySocket = socket(AF_INET, SOCK_DGRAM, 0);
         EXPECT_GE(temporarySocket, 0);

         sockaddr_in destination = {};
         destination.sin_family = AF_INET;
         destination.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
         destination.sin_port = 0;
         EXPECT_EQ(0, bind(temporarySocket,
                           reinterpret_cast<sockaddr*>(&destination),
                           sizeof(destination)));

