    while drained < DRAIN_MAX and attempts < DRAIN_MAX:
        attempts += 1
        try:
            s.recvmsg(1, 512, socket.MSG_ERRQUEUE | socket.MSG_DONTWAIT); drained += 1
        except InterruptedError:
            continue
        except OSError:
