 static void sd_ts(u64 ns, unsigned long *sec, unsigned long *usec)
 {
 	*usec = do_div(ns, NSEC_PER_SEC) / NSEC_PER_USEC;
 	*sec = (unsigned long)ns;
 }

 static unsigned int sd_j2ms(unsigned long j)
 {
 	return jiffies_to_msecs(j - INITIAL_JIFFIES);
 }

 static unsigned long sd_lr(struct pt_regs *regs)
 {
 #ifdef CONFIG_ARM
 	return regs->ARM_lr;
 #else
 	return 0;
 #endif
 }

 static unsigned int sd_irq_pcnt(void)
 {
 	unsigned int pcnt = preempt_count();

 	/* drop the HARDIRQ_OFFSET of the tick itself */
 	if (pcnt & HARDIRQ_MASK)
 		pcnt -= HARDIRQ_OFFSET;
 	return pcnt;
 }

