 /* Caller holds mmap_read_trylock(mm). Returns a static buffer. */
 static const char *sd_uaddr_str(struct mm_struct *mm, unsigned long addr)
 {
 	struct vm_area_struct *vma = find_vma(mm, addr);

 	if (!vma || vma->vm_start > addr)
 		return "[no vma]";
 	if (!vma->vm_file) {
 		snprintf(sd_ubuf, sizeof(sd_ubuf), "[anon %08lx-%08lx]",
 			 vma->vm_start, vma->vm_end);
 		return sd_ubuf;
 	}
 	snprintf(sd_ubuf, sizeof(sd_ubuf), "%pD+0x%lx", vma->vm_file,
 		 addr - vma->vm_start + (vma->vm_pgoff << PAGE_SHIFT));
 	return sd_ubuf;
 }

 /* User-mode context of current: PC/LR mapping + code pointers on the stack. */
 static void sd_dump_user(struct pt_regs *regs)
 {
 	struct mm_struct *mm = current->mm;
 	unsigned long pc = instruction_pointer(regs);
 	unsigned long lr = sd_lr(regs);
 	unsigned long sp = user_stack_pointer(regs);
 	bool have_stack;
 	int i, shown = 0;

 	if (!mm)
 		return;
 	have_stack = !copy_from_user_nofault(sd_uwords, (void __user *)sp,
 					     sizeof(sd_uwords));
 	if (!mmap_read_trylock(mm)) {
 		pr_info(SD " user pc=%08lx lr=%08lx sp=%08lx (mmap_lock busy)\n",
 			pc, lr, sp);
 		return;
 	}
 	pr_info(SD " user pc %08lx %s\n", pc, sd_uaddr_str(mm, pc));
 	pr_info(SD " user lr %08lx %s\n", lr, sd_uaddr_str(mm, lr));
 	if (!have_stack)
 		pr_info(SD " user sp %08lx not readable\n", sp);
 	for (i = 0; have_stack && i < SD_USTACK_WORDS && shown < 12; i++) {
 		unsigned long w = sd_uwords[i];
 		struct vm_area_struct *vma = find_vma(mm, w);

 		if (!vma || vma->vm_start > w || !(vma->vm_flags & VM_EXEC) ||
 		    !vma->vm_file)
 			continue;
 		pr_info(SD " user [sp+%03x] %08lx %s\n",
 			i * (int)sizeof(unsigned long), w, sd_uaddr_str(mm, w));
 		shown++;
 	}
 	mmap_read_unlock(mm);
 }

