 static void sd_print_gpk(struct task_struct *gpk, struct rq *rq, u64 now)
 {
 	struct sched_entity *se, *left = NULL;
 	struct task_struct *lt = NULL, *ct = NULL;
 	struct rb_node *n;
 	bool found = false;
 	int cnt = 0;

 	if (!gpk) {
 		pr_info(SD " GP kthread unknown\n");
 		return;
 	}
 	sd_print_task("gpk", gpk, rq, now);

 	n = rb_first_cached(&rq->cfs.tasks_timeline);
 	if (n)
 		left = rb_entry(n, struct sched_entity, run_node);
 	for (; n && cnt < 1024; n = rb_next(n), cnt++)
 		if (rb_entry(n, struct sched_entity, run_node) == &gpk->se)
 			found = true;
 	if (left && entity_is_task(left))
 		lt = container_of(left, struct task_struct, se);
 	se = rq->cfs.curr;
 	if (se && entity_is_task(se))
 		ct = container_of(se, struct task_struct, se);
 	pr_info(SD " cfs nr_running=%u h_nr_running=%u tree=%d gpk_in_tree=%d curr=%d/%s leftmost=%d/%s vrun%+lldus\n",
 		rq->cfs.nr_running, rq->cfs.h_nr_running, cnt, found,
 		ct ? ct->pid : -1, ct ? ct->comm : "-",
 		lt ? lt->pid : -1, lt ? lt->comm : "-",
 		left ? div_s64((s64)(left->vruntime - rq->cfs.min_vruntime),
 			       NSEC_PER_USEC) : 0LL);
 	if (sd_gpk_out.ts)
 		sd_print_switch(" gpk last switched out:", &sd_gpk_out);
 	if (sd_gpk_in_ts) {
 		unsigned long sec, usec;

 		sd_ts(sd_gpk_in_ts, &sec, &usec);
 		pr_info(SD " gpk last switched in: [%5lu.%06lu]\n", sec, usec);
 	}
 }

 static void sd_print_hist(int max_tasks, int max_funcs)
 {
 	struct mm_struct *mm = current->mm;
 	const struct sd_task *t;
 	const struct sd_func *f;
 	int i, k, best;

 	memset(sd_used, 0, sizeof(sd_used));
 	for (k = 0; k < max_tasks; k++) {
 		best = -1;
 		for (i = 0; i < SD_NR_TASKS; i++) {
 			if (!sd_tasks[i].hits || sd_used[i])
 				continue;
 			if (best < 0 || sd_tasks[i].hits > sd_tasks[best].hits)
 				best = i;
 		}
 		if (best < 0)
 			break;
 		sd_used[best] = true;
 		t = &sd_tasks[best];
 		pr_err(SD " top task %d(%d) %s pol=%u prio=%d: %u/%u ticks user=%u nonpreempt=%u softirq=%u\n",
 		       t->pid, t->tgid, t->comm, t->policy, t->prio, t->hits,
 		       sd_nsamples, t->user, t->nonpreempt, t->softirq);
 	}
 	if (sd_tasks_other)
 		pr_info(SD " top task <others>: %u ticks\n", sd_tasks_other);

 	if (mm && !mmap_read_trylock(mm))
 		mm = NULL;
 	memset(sd_used, 0, sizeof(sd_used));
 	for (k = 0; k < max_funcs; k++) {
 		best = -1;
 		for (i = 0; i < SD_NR_FUNCS; i++) {
 			if (!sd_funcs[i].hits || sd_used[i])
 				continue;
 			if (best < 0 || sd_funcs[i].hits > sd_funcs[best].hits)
 				best = i;
 		}
 		if (best < 0)
 			break;
 		sd_used[best] = true;
 		f = &sd_funcs[best];
 		if (!f->user)
 			pr_info(SD " top pc %u ticks pid %d %pS\n",
 				f->hits, f->pid, (void *)f->key);
 		else if (mm && f->pid == current->pid)
 			pr_info(SD " top pc %u ticks pid %d user %08lx %s\n",
 				f->hits, f->pid, f->key, sd_uaddr_str(mm, f->key));
 		else
 			pr_info(SD " top pc %u ticks pid %d user %08lx\n",
 				f->hits, f->pid, f->key);
 	}
 	if (mm)
 		mmap_read_unlock(mm);
 	if (sd_funcs_other)
 		pr_info(SD " top pc <others>: %u ticks\n", sd_funcs_other);
 }

 static void sd_print_samples(unsigned int nmax)
 {
 	unsigned int i, n;

 	n = min(nmax, min_t(unsigned int, sd_nsamples, SD_NR_SAMPLES));
 	for (i = n; i > 0; i--) {
 		const struct sd_sample *s =
 			&sd_samples[(sd_samples_head - i) & (SD_NR_SAMPLES - 1)];

 		if (s->user)
