 static void sd_print_deltas(int max_irqs)
 {
 	int cpu = smp_processor_id();
 	int i, n = min_t(int, nr_irqs, SD_MAX_IRQS);
 	int shown = 0, hidden = 0, len = 0;
 	struct task_struct *ks = per_cpu(ksoftirqd, cpu);

 	pr_info(SD " deltas over %u ms since detection:\n",
 		jiffies_to_msecs(jiffies - sd_start_j));
 	for (i = 0; i < n; i++) {
 		unsigned int d = kstat_irqs_cpu(i, cpu) - sd_irq_snap[i];
 		struct irq_desc *desc;
 		struct irqaction *action;

 		if (!d)
 			continue;
 		if (shown >= max_irqs) {
 			hidden++;
 			continue;
 		}
 		shown++;
 		desc = irq_to_desc(i);
 		action = desc ? READ_ONCE(desc->action) : NULL;
 		pr_info(SD "  irq %d hw %lu %s +%u\n", i,
 			desc ? desc->irq_data.hwirq : 0UL,
 			action && action->name ? action->name : "-", d);
 	}
 	if (hidden)
 		pr_info(SD "  (%d more irqs)\n", hidden);

 	for (i = 0; i < NR_SOFTIRQS; i++)
 		len += scnprintf(sd_line + len, sizeof(sd_line) - len, " %s+%u",
 				 softirq_to_name[i],
 				 kstat_softirqs_cpu(i, cpu) - sd_softirq_snap[i]);
 	pr_info(SD "  softirq%s pending=%#x\n", sd_line,
 		(unsigned int)local_softirq_pending());

 	len = 0;
 	for (i = 0; i < SD_CNT_NR; i++)
 		len += scnprintf(sd_line + len, sizeof(sd_line) - len, " %s+%lu",
 				 sd_cnt_names[i], sd_cnt[i] - sd_cnt_snap[i]);
 	pr_info(SD "  counters%s\n", sd_line);

 	if (ks)
 		pr_info(SD "  ksoftirqd/%d %c on_rq=%d ago=%lldms\n", cpu,
 			task_state_to_char(ks), ks->on_rq,
 			div_s64((s64)(this_rq()->clock_task - ks->se.exec_start),
 				NSEC_PER_MSEC));
 }

 static void sd_print_longirqs(void)
 {
 	unsigned long sec, usec;
 	unsigned int i;

 	if (sd_irq_max.dur) {
 		sd_ts(sd_irq_max.ts, &sec, &usec);
 		pr_info(SD " longest hardirq since boot: [%5lu.%06lu] irq %u %ps %llu us\n",
 			sec, usec, sd_irq_max.irq, sd_irq_max.handler,
 			div_u64(sd_irq_max.dur, NSEC_PER_USEC));
 	}
 	for (i = SD_NR_LONGIRQ; i > 0; i--) {
 		const struct sd_longirq *l =
 			&sd_longirq[(sd_longirq_head - i) & (SD_NR_LONGIRQ - 1)];

 		if (!l->ts)
 			continue;
 		sd_ts(l->ts, &sec, &usec);
 		pr_info(SD "  long hardirq [%5lu.%06lu] irq %u %ps %llu us\n",
 			sec, usec, l->irq, l->handler,
 			div_u64(l->dur, NSEC_PER_USEC));
 	}
 }

 static void sd_print_tasks(struct rq *rq, u64 now, u64 window_ns, bool full)
 {
 	struct task_struct *g, *p, *cur = current;
 	int max_ran = full ? 24 : 12;
 	int nrun = 0, nran = 0, nstack = 0, hidden = 0;

 	rcu_read_lock();
 	for_each_process_thread(g, p) {
 		if (!task_on_rq_queued(p) && p != cur)
 			continue;
 		if (nrun++ >= 16) {
 			hidden++;
 			continue;
 		}
 		sd_print_task("run", p, rq, now);
 		/* other runnable RT tasks: show where they are */
 		if (p != cur && rt_task(p) && nstack < 3) {
 			nstack++;
 			sched_show_task(p);
 		}
 	}
 	for_each_process_thread(g, p) {
 		if (task_on_rq_queued(p) || p == cur)
 			continue;
 		if (!p->se.exec_start || now - p->se.exec_start > window_ns)
 			continue;
 		if (nran++ >= max_ran) {
 			hidden++;
 			continue;
 		}
 		sd_print_task("ran", p, rq, now);
 	}
 	rcu_read_unlock();
 	if (hidden)
 		pr_info(SD " (%d more runnable/recently-run tasks not shown)\n",
 			hidden);
 }

 static void sd_print_rt_tasks(void)
 {
 	struct task_struct *g, *p;
 	int len = 0, n = 0;

 	rcu_read_lock();
 	for_each_process_thread(g, p) {
 		if (!rt_policy(p->policy) && !dl_policy(p->policy))
 			continue;
 		len += scnprintf(sd_line + len, sizeof(sd_line) - len,
 				 " %d/%s/%c%u", p->pid, p->comm,
 				 p->policy == SCHED_FIFO ? 'F' :
 				 p->policy == SCHED_RR ? 'R' : 'D',
 				 p->rt_priority);
 		if (len > 150) {
 			pr_info(SD " rt:%s\n", sd_line);
 			len = 0;
 		}
 		if (++n >= 128)
 			goto out;
 	}
 out:
 	rcu_read_unlock();
 	if (len)
 		pr_info(SD " rt:%s\n", sd_line);
 	pr_info(SD " rt/dl tasks: %d%s\n", n, n >= 128 ? "+" : "");
 }

 static void sd_print_notes(void)
 {
 	unsigned long sec, usec;
 	unsigned int i;

 	for (i = SD_NR_NOTES; i > 0; i--) {
 		const struct sd_note *n =
 			&sd_notes[(sd_notes_head - i) & (SD_NR_NOTES - 1)];

 		if (!n->ts)
 			continue;
 		sd_ts(n->ts, &sec, &usec);
 		pr_info(SD " note [%5lu.%06lu] %d/%s %s %#lx %ld\n", sec, usec,
 			n->pid, n->comm, n->tag, (unsigned long)n->a, n->b);
 	}
 }

 /* Must be called from the tick (hard IRQ, interrupts disabled). */
 static void sd_report(struct task_struct *gpk, const char *why, bool full)
 {
 	struct rq *rq = this_rq();
 	struct pt_regs *regs = get_irq_regs();
 	struct task_struct *cur = current;
 	unsigned long j = jiffies;
 	unsigned long starve = sd_active ? j - sd_gpa : 0;
 	u64 now = rq->clock_task;
 	u64 window_ns = (u64)jiffies_to_msecs(starve) * NSEC_PER_MSEC;
 	u64 rt_runtime = rq->rt.rt_runtime;
 	time64_t wall = ktime_get_real_seconds();

 	pr_err(SD "==== %s at %ptT UTC: GP kthread not run for %u ms (since uptime %u ms); cur %d(%d) %s pol=%u prio=%d pcnt=%#x %s ====\n",
 	       why, &wall, jiffies_to_msecs(starve), sd_j2ms(sd_gpa), cur->pid,
 	       cur->tgid, cur->comm, cur->policy, cur->prio, sd_irq_pcnt(),
 	       !regs ? "no-regs" : user_mode(regs) ? "user" : "kernel");
 	pr_info(SD " episode #%u samples=%u detect_gap=%lu max_tick_gap=%lu ctxsw+%llu clock+%llums jiffies+%ums\n",
 		sd_episodes, sd_nsamples, sd_detect_gap, sd_max_gap,
 		rq->nr_switches - sd_start_switches,
 		div_u64(local_clock() - sd_start_ns, NSEC_PER_MSEC),
 		jiffies_to_msecs(j - sd_start_j));
 	pr_info(SD " rq nr_running=%u cfs=%u rt=%u rt_throttled=%d rt_time=%lluus rt_runtime=%lldus sysctl_rt=%d/%u nr_switches=%llu\n",
 		rq->nr_running, rq->cfs.h_nr_running, rq->rt.rt_nr_running,
 		rq->rt.rt_throttled, div_u64(rq->rt.rt_time, NSEC_PER_USEC),
 		rt_runtime == RUNTIME_INF ? -1LL :
 			(s64)div_u64(rt_runtime, NSEC_PER_USEC),
 		sysctl_sched_rt_runtime, sysctl_sched_rt_period,
 		rq->nr_switches);
 	sd_print_gpk(gpk, rq, now);
 	sd_print_task("cur", cur, rq, now);
 	if (!full && gpk && gpk != cur)
 		sched_show_task(gpk);
 	if (regs) {
 		show_regs(regs);
 		if (user_mode(regs))
 			sd_dump_user(regs);
 	}
 	if (full) {
 		if (sd_active) {
 			sd_print_hist(SD_NR_TASKS, 16);
 			sd_print_samples(12);
 			sd_print_deltas(24);
 		}
 		sd_print_longirqs();
 	}
 	sd_print_switches(full ? 32 : 16);
 	sd_print_tasks(rq, now, window_ns ?: NSEC_PER_SEC, full);
 	if (full)
 		sd_print_rt_tasks();
 	sd_print_notes();
 	pr_err(SD "==== end of %s report ====\n", why);
 	sd_skip_irq = true;
 }

 static void sd_episode_end(unsigned long j, unsigned long starve_j)
 {
 	unsigned long back_j = j - starve_j;	/* GP kthread active again */

 	pr_warn(SD "episode #%u ended: GP kthread starved ~%u ms from uptime %u ms, samples=%u detect_gap=%lu max_tick_gap=%lu ctxsw+%llu\n",
 		sd_episodes, jiffies_to_msecs(back_j - sd_gpa), sd_j2ms(sd_gpa),
 		sd_nsamples, sd_detect_gap, sd_max_gap,
 		this_rq()->nr_switches - sd_start_switches);
 	sd_print_hist(4, 6);
 	sd_print_deltas(8);
 	sd_print_longirqs();
 	sd_active = false;
 	sd_skip_irq = true;
 }

 /*
  * Called on every tick from rcu_sched_clock_irq().  @starve_j is how long
  * the GP kthread has not shown activity while a grace period is in
  * progress (0 if no grace period is in progress).
  */
 void notrace starve_dbg_tick(int user, unsigned long starve_j,
 			     struct task_struct *gpk)
 {
 	unsigned long j = jiffies;
 	unsigned long gap = j - sd_prev_tick_j;
 	unsigned int thresh_ms = READ_ONCE(sd_thresh_ms);
 	unsigned int interval_s = READ_ONCE(sd_early_interval_s);

 	sd_prev_tick_j = j;
 	sd_gpk = gpk;
 	if (!READ_ONCE(sd_enable) || !gpk)
 		return;

 	if (starve_j < msecs_to_jiffies(max(thresh_ms, 100U))) {
 		if (sd_active)
 			sd_episode_end(j, starve_j);
 		return;
 	}

 	if (sd_active) {
 		sd_take_sample(j, user, gap);
 		return;
 	}

 	sd_episode_begin(j, starve_j, gap);
 	sd_take_sample(j, user, 0);
 	if (!sd_early_printed ||
 	    time_after(j, sd_early_j + (unsigned long)interval_s * HZ)) {
 		sd_early_printed = true;
 		sd_early_j = j;
 		sd_report(gpk, "early", false);
 	}
 }

 /* Called from the RCU CPU stall code right before panic_on_rcu_stall(). */
 void starve_dbg_report(struct task_struct *gpk, const char *why)
 {
 	sd_report(gpk, why, true);
 }

