 static void sd_print_gpk(struct task_struct *gpk, struct rq *rq, u64 now)
 {
 	struct sched_entity *se, *left = NULL;
 	struct task_struct *lt = NULL, *ct = NULL;
 	struct rb_node *n;
 	bool found = false;
 	int cnt = 0;

 	if (!gpk) {
 		pr_info(SD " GP kthread unknown\n");
 		return;
 	}
 	sd_print_task("gpk", gpk, rq, now);

 	n = rb_first_cached(&rq->cfs.tasks_timeline);
 	if (n)
 		left = rb_entry(n, struct sched_entity, run_node);
 	for (; n && cnt < 1024; n = rb_next(n), cnt++)
 		if (rb_entry(n, struct sched_entity, run_node) == &gpk->se)
 			found = true;
 	if (left && entity_is_task(left))
 		lt = container_of(left, struct task_struct, se);
