 static void sd_print_hist(int max_tasks, int max_funcs)
 {
 	struct mm_struct *mm = current->mm;
 	const struct sd_task *t;
 	const struct sd_func *f;
 	int i, k, best;

 	memset(sd_used, 0, sizeof(sd_used));
 	for (k = 0; k < max_tasks; k++) {
 		best = -1;
 		for (i = 0; i < SD_NR_TASKS; i++) {
 			if (!sd_tasks[i].hits || sd_used[i])
 				continue;
 			if (best < 0 || sd_tasks[i].hits > sd_tasks[best].hits)
 				best = i;
 		}
 		if (best < 0)
 			break;
 		sd_used[best] = true;
 		t = &sd_tasks[best];
 		pr_err(SD " top task %d(%d) %s pol=%u prio=%d: %u/%u ticks user=%u nonpreempt=%u softirq=%u\n",
 		       t->pid, t->tgid, t->comm, t->policy, t->prio, t->hits,
 		       sd_nsamples, t->user, t->nonpreempt, t->softirq);
 	}
 	if (sd_tasks_other)
 		pr_info(SD " top task <others>: %u ticks\n", sd_tasks_other);

 	if (mm && !mmap_read_trylock(mm))
 		mm = NULL;
 	memset(sd_used, 0, sizeof(sd_used));
 	for (k = 0; k < max_funcs; k++) {
 		best = -1;
 		for (i = 0; i < SD_NR_FUNCS; i++) {
 			if (!sd_funcs[i].hits || sd_used[i])
 				continue;
 			if (best < 0 || sd_funcs[i].hits > sd_funcs[best].hits)
 				best = i;
 		}
 		if (best < 0)
 			break;
 		sd_used[best] = true;
 		f = &sd_funcs[best];
 		if (!f->user)
 			pr_info(SD " top pc %u ticks pid %d %pS\n",
 				f->hits, f->pid, (void *)f->key);
 		else if (mm && f->pid == current->pid)
 			pr_info(SD " top pc %u ticks pid %d user %08lx %s\n",
 				f->hits, f->pid, f->key, sd_uaddr_str(mm, f->key));
 		else
 			pr_info(SD " top pc %u ticks pid %d user %08lx\n",
 				f->hits, f->pid, f->key);
 	}
 	if (mm)
 		mmap_read_unlock(mm);
 	if (sd_funcs_other)
 		pr_info(SD " top pc <others>: %u ticks\n", sd_funcs_other);
 }

 static void sd_print_samples(unsigned int nmax)
 {
 	unsigned int i, n;

 	n = min(nmax, min_t(unsigned int, sd_nsamples, SD_NR_SAMPLES));
 	for (i = n; i > 0; i--) {
 		const struct sd_sample *s =
 			&sd_samples[(sd_samples_head - i) & (SD_NR_SAMPLES - 1)];

 		if (s->user)
 			pr_info(SD " smp +%ums %d user pc=%08lx lr=%08lx pcnt=%#x\n",
 				jiffies_to_msecs(s->j - sd_gpa), s->pid,
 				s->pc, s->lr, s->pcnt);
 		else
 			pr_info(SD " smp +%ums %d kern pc=%pS lr=%pS pcnt=%#x\n",
 				jiffies_to_msecs(s->j - sd_gpa), s->pid,
 				(void *)s->pc, (void *)s->lr, s->pcnt);
 	}
 }

