 static void sd_account_task(struct task_struct *p, int user, unsigned int pcnt)
 {
 	struct sd_task *t;
 	int i;

 	for (i = 0; i < SD_NR_TASKS; i++) {
 		t = &sd_tasks[i];
 		if (!t->hits) {
 			t->pid = p->pid;
 			t->tgid = p->tgid;
 			t->policy = p->policy;
 			t->prio = p->prio;
 			memcpy(t->comm, p->comm, TASK_COMM_LEN);
 			t->comm[TASK_COMM_LEN - 1] = '\0';
 		} else if (t->pid != p->pid) {
 			continue;
 		}
 		t->hits++;
 		if (user)
 			t->user++;
 		if (pcnt)
 			t->nonpreempt++;
 		if (pcnt & SOFTIRQ_OFFSET)
 			t->softirq++;
 		return;
 	}
 	sd_tasks_other++;
 }

 static void sd_account_func(pid_t pid, int user, unsigned long pc)
 {
 	unsigned long key = pc, size, off;
 	struct sd_func *f;
 	int i;

 	if (user)
 		key = pc & ~0x3fUL;
 	else if (kallsyms_lookup_size_offset(pc, &size, &off))
 		key = pc - off;

 	for (i = 0; i < SD_NR_FUNCS; i++) {
 		f = &sd_funcs[i];
 		if (!f->hits) {
 			f->key = key;
 			f->pid = pid;
 			f->user = user;
 		} else if (f->key != key || f->pid != pid || f->user != !!user) {
 			continue;
 		}
 		f->hits++;
 		return;
 	}
 	sd_funcs_other++;
 }

 static void sd_take_sample(unsigned long j, int user, unsigned long gap)
 {
 	struct pt_regs *regs = get_irq_regs();
 	struct task_struct *p = current;
 	unsigned int pcnt = sd_irq_pcnt();
 	unsigned long pc = regs ? instruction_pointer(regs) : 0;
 	struct sd_sample *s;

 	if (gap > sd_max_gap)
 		sd_max_gap = gap;
 	sd_nsamples++;

 	s = &sd_samples[sd_samples_head++ & (SD_NR_SAMPLES - 1)];
 	s->j = j;
 	s->pc = pc;
 	s->lr = regs ? sd_lr(regs) : 0;
 	s->pcnt = pcnt;
 	s->pid = p->pid;
 	s->user = user;

 	sd_account_task(p, user, pcnt);
 	sd_account_func(p->pid, user, pc);
 }

 static void sd_episode_begin(unsigned long j, unsigned long starve_j,
 			     unsigned long gap)
 {
 	int cpu = smp_processor_id();
 	int i, n = min_t(int, nr_irqs, SD_MAX_IRQS);

 	sd_active = true;
 	sd_episodes++;
 	sd_gpa = j - starve_j;
 	sd_start_j = j;
 	sd_detect_gap = gap;
 	sd_max_gap = 0;
 	sd_start_ns = local_clock();
 	sd_start_switches = this_rq()->nr_switches;
 	sd_nsamples = 0;
 	sd_samples_head = 0;
 	sd_funcs_other = 0;
 	sd_tasks_other = 0;
 	memset(sd_samples, 0, sizeof(sd_samples));
 	memset(sd_funcs, 0, sizeof(sd_funcs));
 	memset(sd_tasks, 0, sizeof(sd_tasks));
 	for (i = 0; i < n; i++)
 		sd_irq_snap[i] = kstat_irqs_cpu(i, cpu);
 	for (i = 0; i < NR_SOFTIRQS; i++)
 		sd_softirq_snap[i] = kstat_softirqs_cpu(i, cpu);
 	memcpy(sd_cnt_snap, sd_cnt, sizeof(sd_cnt));
 }

