static inline bool transport_isIgnorableSocketError(const int errorCode)
{
    switch (errorCode) {
    case ECONNREFUSED:
    case EHOSTUNREACH:
    case EHOSTDOWN:
    case ENETUNREACH:
    case ENONET:
    case ENOPROTOOPT:
    case EMSGSIZE:
    case EPROTO:
    case EOPNOTSUPP:
    case EACCES:
        return true;

    default:
        return false;
    }
