//  ms_startRTPSessionRx).
//  this has caused 1-way audio problem.
//  Code is changed return a normal status so that the caller will not take action to
//  disable select-read
//==========================================================================;
static int rtpsndrcv_readError (int streamId, int sock, int saved_errno)
{
    struct msghdr msg;
    char cmsgbuf[512];
    int retVal ;
    int rc = 0;

    // don't need to display every error....
    if ((++read_error % RECV_ERROR) == READ_ERROR_DISPLAY) {
        MS_LOG_SESSION(LOG_ERR, streamMgr.ops.getSessionId(streamId),
                       "[stream=%d][sock=%d] "
                       "receive error [last errno=%s][count=%d]",
                       streamId, sock,
                       strerror(saved_errno), read_error);
    }

    // First read more detailed error
    // but do not get original message.
    memset(&msg, 0, sizeof(struct msghdr));
    memset(&cmsgbuf, 0, sizeof(cmsgbuf));
    msg.msg_control = &cmsgbuf;
    msg.msg_controllen = sizeof(cmsgbuf);
    retVal = recvmsg(sock, &msg, MSG_ERRQUEUE);

    // special error handling for these types of errors
    if (transport_isIgnorableSocketError(saved_errno)) {
        bool sendICMPErrorNow = false;
        bool sendICMPError = false;
        bool sendICMPTTLExceeded = false;
        struct cmsghdr *cmsg;
        struct sockaddr TTLExceededRemoteHost;
        rc = MS_ICMP_UNREACHABLE_ERROR;     // a connection error count as a soft error
        // this fix a 1-way audio problem seen in wifi

        // Check for actual reason
        if (retVal != MS_ERROR) {
            // valid cmsg

            for (cmsg = CMSG_FIRSTHDR(&msg); cmsg; cmsg = CMSG_NXTHDR(&msg, cmsg)) {
                // look for port unreachable ICMP error
                if ((cmsg->cmsg_level == IPPROTO_IP) && (cmsg->cmsg_type == IP_RECVERR)) {
                rtpsndrcv_icmpError(streamId, &(addr->ip),
                                    addr->port, sendICMPErrorNow);
            } else {
                LOG(LOG_ERR, "Remote address is NULL !");
            }
        } else {
            rc = MS_OK;
        }
    }
    else {
        if  (saved_errno == EAGAIN) {
            rc = MS_OK;
            LOG(LOG_WARNING, "EAGAIN occurs, [sock=%d] [errno=%d] - ignoring ",
                sock, saved_errno);
        } else {
            rc = MS_ERROR;
            LOG(LOG_ERR, "a hard error occurs, [sock=%d] [errno=%d] - unknown error ",
                sock, saved_errno);
        }
    }

int rtpsndrcv_rcvPacket(int sock, int streamId, char* buf, int bufSize)
{
    int bytes = 0;
    int retVal = MS_OK;
    unsigned int eagain_retry_count = 0;
    int sessionId = streamMgr.ops.getSessionId(streamId);
    t_peerIP peerIP;

    if (buf == NULL) {
        // can't get a buffer.  increment the packet alloc fails count.
        //  print out if ready
        if ((streamMgr.ops.incStreamPktBufAllocFailure(streamId) %
             MAX_PKT_BUF_ALLOC_FAILURE)) {//== 1) { always print error
            MS_LOG_SESSION(LOG_ERR, sessionId,
                           "[stream=%d][sock=%d] "
                           "packet buffer allocation failed [count=%d]",
                           streamId, sock,
                           streamMgr.ops.getStreamPktBufAllocFailure(streamId));
        }

        // read the data out of the socket and drop it.
        bytes = recv(sock, fail_buff, FAILBUFF_SIZE, 0);

        if (bytes < 0) {
            rtpsndrcv_readError(streamId, sock, errno);
        }
        return retVal;
    }

    do {
        // receive data in the buffer
        retVal = rtpsndrcv_readPacket(sock, streamId, buf, bufSize, &peerIP);
        bytes = retVal;

        // Resource temporarily unavailable - sleep for 5 microsecs and retry
        if ((retVal == MS_ERROR) && (errno == EAGAIN) &&
            (eagain_retry_count < EAGAIN_RECFROM_RETRY_MAX)) {
            usleep(5);
            eagain_retry_count++;
        } else {
            break;
        }
    } while (TRUE);

    if (retVal == 0) {
        rtpmgr_notProcessPacket(buf,bufSize);
        return MS_OK;
    }
        }
    } else { // recvfrom check
#ifdef EXTRA_RTP_STATS
        streamMgr.ops.incRecvErrors(streamId);
#endif
        // except ICMP_UNREACHABLE, a hard errormay cause the caller
        // to take some action
        // the existing code stops listen to this socket
        retVal = rtpsndrcv_readError(streamId, sock, errno);
        rtpmgr_notProcessPacket(buf, bufSize);
    }

    if (retVal == MS_ICMP_UNREACHABLE_ERROR) {
        retVal = MS_OK; // soft error; don't want to return -1
    }

