+    // Media sockets are non-blocking with IP_RECVERR. A datagram to a closed
+    // port brings back an ICMP port unreachable: the kernel sets sk_err and
+    // queues an entry on the socket error queue.
+    void receiveIcmpPortUnreachable() const
+    {
+        const int enabled = 1;
+        ASSERT_EQ(0, setsockopt(socket_, SOL_IP, IP_RECVERR, &enabled,
+                                sizeof(enabled)));
+        const int currentFlags = fcntl(socket_, F_GETFL, 0);
+        ASSERT_GE(currentFlags, 0);
+        ASSERT_EQ(0, fcntl(socket_, F_SETFL, currentFlags | O_NONBLOCK));
+
+        const sockaddr_in unreachable = reserveAndReleaseDestination();
+        const char request = 'x';
+        ASSERT_EQ(1, sendto(socket_, &request, sizeof(request), 0,
+                            reinterpret_cast<const sockaddr*>(&unreachable),
+                            sizeof(unreachable)));
+
+        pollfd errorPoll = {socket_, POLLERR, 0};
+        ASSERT_EQ(1, poll(&errorPoll, 1, 1000));
+        ASSERT_NE(0, errorPoll.revents & POLLERR);
+    }
+
+    // sk_err was taken but the ICMP entry is still queued: poll() reports
+    // POLLERR without data and recvfrom() returns EAGAIN until the entry is
+    // read with MSG_ERRQUEUE.
+    void assertStaleErrorQueue() const
+    {
+        pollfd stalePoll = {socket_, POLLIN, 0};
+        ASSERT_EQ(1, poll(&stalePoll, 1, 0));
+        ASSERT_NE(0, stalePoll.revents & POLLERR);
+        ASSERT_EQ(0, stalePoll.revents & POLLIN);
+    }
