    ASSERT_EQ(EBADF, errno);
}

TEST_F(NetPortProxyRxTest, DrainsIcmpErrorAndDemuxesNextStunPacket)
{
    const int enabled = 1;
    ASSERT_EQ(0, setsockopt(socket_, SOL_IP, IP_RECVERR, &enabled,
                            sizeof(enabled)));

    const sockaddr_in unreachable = reserveAndReleaseDestination();
    const char request = 'x';
    ASSERT_EQ(1, sendto(socket_, &request, sizeof(request), 0,
                        reinterpret_cast<const sockaddr*>(&unreachable),
                        sizeof(unreachable)));

    pollfd errorPoll = {socket_, POLLERR, 0};
    ASSERT_EQ(1, poll(&errorPoll, 1, 1000));
    ASSERT_NE(0, errorPoll.revents & POLLERR);

    EXPECT_EQ(MS_OK, registeredRxProcess(socket_));

    char control[512];
    msghdr errorMessage = {};
    errorMessage.msg_control = control;
    errorMessage.msg_controllen = sizeof(control);
    EXPECT_EQ(MS_ERROR,
              recvmsg(socket_, &errorMessage, MSG_ERRQUEUE | MSG_DONTWAIT));
    EXPECT_TRUE(errno == EAGAIN || errno == EWOULDBLOCK);

    const int sender = socket(AF_INET, SOCK_DGRAM, 0);
    ASSERT_GE(sender, 0);
    treatPacketAsStun = true;
    const char stunPacket[] = {
        0x00, 0x01, 0x00, 0x00,
        0x21, 0x12, static_cast<char>(0xa4), 0x42,
        0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00,
    };
    ASSERT_EQ(static_cast<ssize_t>(sizeof(stunPacket)),
              sendto(sender, stunPacket, sizeof(stunPacket), 0,
                     reinterpret_cast<const sockaddr*>(&localAddress_),
                     sizeof(localAddress_)));

    EXPECT_EQ(static_cast<int>(sizeof(stunPacket)),
              registeredRxProcess(socket_));
    EXPECT_EQ(1u, stunDemuxCalls);
    EXPECT_EQ(1u, netPortProxyCallbacks);
    EXPECT_EQ(0, close(sender));
}

