   if (!noData && !transport_isIgnorableSocketError(recvErrno)) {
     return MS_ERROR;
   }

   // Recoverable error: keep the fd. With IP_RECVERR an ICMP error is recorded
   // twice: in sk_err, which recvfrom()/sendto() take, and as an error queue
   // entry, which keeps POLLERR set until it is read with MSG_ERRQUEUE. Drain
   // the queue in both cases:
   // - ICMP errno (e.g. ECONNREFUSED): this recvfrom() just took sk_err.
   // - EAGAIN: an earlier recv()/sendto() took sk_err, the entry is stale and,
   //   without the drain, the select thread would spin on this fd.
   const unsigned int drained = ppxy_netPortProxyDrainErrorQueue(sock);

   if (noData && (drained > 0)) {
     static unsigned int staleErrQueueCount = 0;

     if ((staleErrQueueCount++ % PORT_PROXY_STALE_ERRQUEUE_LOG_INTERVAL) == 0) {
       LOG(LOG_WARNING, "[sock=%d] POLLERR without data, drained %u stale error queue entries [count=%u]",
